import { AbstractChoice, RelatedChoices, IChoice } from "./common";
import { mutuallyExclusive, chooseAtLeastOneOfOnlyIf } from "../clauseGeneration";
import { nameChoices } from "../debug";

class Choice extends AbstractChoice {

	constructor(
		parentChoice: IChoice,
		sharedIndex: number) {
		super();

		if (nameChoices) {
			this.name = `${parentChoice.name} shared index ${sharedIndex}`;
		}
	}

	public apply() {
		// We don't need to do anything
		// This choice exists only to limit other choices
	}
}

// ------------------------------------------------------------------------------------------------
// SharedCount
// A factory for creating a choice of a specific index at which to share a limited-shared thing
// Right now, this is only used for peripherals, but I've made it generic so it could be used for 
// other choices too.
//
// Basically, if a thing can be shared N times, then each time that thing is shared, it must 
// pick one index (from 0 to N-1) to share the thing at.  Then, if there is a N+1th shared choice
// that picks that thing, there won't be a shared index choice for it, and thus it can't be taken
// ------------------------------------------------------------------------------------------------

export class SharedCount {
	private readonly byShareableChoice = new RelatedChoices<number, Choice>();
	private readonly byShareableThing = new RelatedChoices<string, Choice>();

	public newChoice(
		shareableChoice: IChoice,	// choice object to select this shareable thing
		shareableThing: string,		// the thing that this choice is picking
		sharedIndex: number) {		// the index into the shared count to share this at

		const choice = new Choice(shareableChoice, sharedIndex);
		this.byShareableChoice.get(shareableChoice.id).push(choice);
		this.byShareableThing.get(shareableThing + sharedIndex).push(choice);

		return choice;
	}

	public generateClauses() {
		chooseAtLeastOneOfOnlyIf(this.byShareableChoice, null,
			"cannot choose a limited-sharedable choice unless associated with a shared count index");
		mutuallyExclusive(this.byShareableThing, null,
			"only choose a shared count index once, for a given thing to be shared");
	}
}
