import * as _ from "lodash";
import { Units, UnitsConfigurable, NumberAndUnits, UnitsPrefix, BaseUnits } from "public/defs";
import { SetSource } from "../member";
import { RuntimeObject } from "public/runtime";
import { FormattersMap } from "../../formatting/formattersMap";
import { AObjectMgr } from "../object";
import { Validations } from "../validations";
import { ConfigurableMgr } from "./configurableMgr";
import * as bigInt from "big-integer";
import { getRadix } from "../../utils/numberUtils";
import { ConfigurableComponent } from "./configurableComponent";
import { UNITS_PREFIX, getUnitsPrefix, getBaseUnits, isUnitsPrefix } from "../../utils/unitsUtils";

export abstract class UnitsConfigurableMgr<NumberType extends number | bigInt.BigInteger>
	extends ConfigurableMgr<NumberAndUnits<NumberType>, RuntimeObject, UnitsConfigurable<NumberType>> {

	public readonly ui = ConfigurableComponent.CUnitsConfigurable;
	private readonly unitsFormats: RegExp[];
	private readonly baseUnits: BaseUnits;
	private readonly permittedUnitsRange: [low: number, high: number];

	constructor(
		parentObjectMgr: AObjectMgr<RuntimeObject>,
		formattersMap: FormattersMap,
		def: UnitsConfigurable<NumberType>,
	) {
		super(parentObjectMgr, formattersMap, def);
		const permittedRangeUnitPrefixes = [
			getUnitsPrefix(this.def.range[0].units),
			getUnitsPrefix(this.def.range[1].units),
		];
		const permittedRange = _.map(permittedRangeUnitPrefixes, (u) => _.indexOf(UNITS_PREFIX, u));
		this.permittedUnitsRange = [Math.min(...permittedRange), Math.max(...permittedRange)];
		const allowedUnits = _
			.chain(UNITS_PREFIX)
			.filter((unit, i) => this.isPermittedUnitsPrefix(unit, i))
			.join("")
			.value();
		this.baseUnits = getBaseUnits(this.def.default.units);
		const unitsExpr = ` ?([${allowedUnits}]?${this.baseUnits}?|)?`;
		this.unitsFormats = this.createMatchFormats(unitsExpr);
	}

	public getValueAsString() {
		return `${this.numToString(this.value.val)} ${this.getUnits()}`;
	}

	public getMagnitudeAsString() {
		return `${this.numToString(this.value.val)}`;
	}

	public getUnits() {
		return this.value.units;
	}

	public override getUIHash(validations: Validations): string {
		if (validations.getValidation(this)) {
			return null;
		}
		return `${this.getValueAsString()}${this.uiState.readOnly}${this.uiState.hidden}`;
	}

	public override validate(validations: Validations): void {
		super.validate(validations);
		if (!this.def.range) {
			return;
		}
		// We dont need to validate the args to convertTo, so we may use convertToImpl
		const [low, high] = _.map(this.def.range, (numUnits) => this.convertToImpl(numUnits, this.value.units));
		if (!this.isInRange(this.value.val, [low, high])) {
			const range = _.map(this.def.range, ({ val, units }) => `${val} ${units}`)
				.join(" to ");
			validations.logError(`Must be in the range of ${range}`, this);
		}
	}

	public parseString(valStr: string): { val: NumberType, units: Units } {
		// Expects string to be of form "<number> <units>"
		// String should have already been checked to be in this form
		let expr: RegExp;
		if (_.startsWith(valStr, "0x")) {
			expr = /0x[0-9a-fA-F]*|[a-zA-Z]+/g;
		} else {
			expr = /[+-]?[0-9]+\.?[0-9]*|[a-zA-Z]+/g;
		}

		const raw = _.words(valStr, expr);
		let units: Units;
		const val = this.stringToNum(raw[0]);
		if (raw.length < 2) {
			units = this.value.units;
		} else {
			// The regex filter and the parsing regex above allows us to perform this casting safely
			const possibleUnit = getUnitsPrefix(raw[1] as Units);
			units = isUnitsPrefix(possibleUnit) ? (possibleUnit + this.baseUnits) as Units :
				this.baseUnits;
		}
		return { val, units };

	}

	public checkFormatMatch(valStr: string) {
		return _.some(this.unitsFormats, (f) => f.test(valStr));
	}

	public getUIOptions() {
		return _.chain(UNITS_PREFIX)
			.filter((_u, i) => this.permittedUnitsRange[0] <= i && i <= this.permittedUnitsRange[1])
			.map((u) => u + this.baseUnits)
			.value();
	}

	protected abstract convertToImpl(input: NumberAndUnits<NumberType>, output: Units | UnitsPrefix): NumberType;

	protected abstract createMatchFormats(unitsFormat: string): RegExp[];

	protected abstract stringToNum(val: string): NumberType;

	protected abstract numToString(val: NumberType): string;

	protected abstract isInRange(val: NumberType, range: [low: NumberType | number, high: NumberType | number]): boolean;

	protected abstract override isEqual(val: NumberAndUnits<NumberType>): boolean;

	protected abstract toIdealUnit(
		val: NumberAndUnits<NumberType>,
		permittedUnitsRange: [low: number, high: number],
	): NumberAndUnits<NumberType>;

	protected override validateValue(value: NumberAndUnits<NumberType>, forceWrite: boolean, source: SetSource): void {
		super.validateValue(value, forceWrite, source);

		if (!this.isPermittedUnitsPrefix(getUnitsPrefix(value.units))) {
			throw new Error(`Units ${value.units} are not allowed for this configurable.`);
		}

		const currBaseUnit = getBaseUnits(value.units);
		const expectedBaseUnit = this.baseUnits;
		if (currBaseUnit !== expectedBaseUnit) {
			throw (`The base units must be ${expectedBaseUnit} not ${currBaseUnit}.`);
		}
	}

	protected getRadix() {
		return getRadix(this.def.displayFormat);
	}

	protected override toLValue(): { val: NumberType; units: Units; as: (units: Units) => NumberType } {
		const utility = (units: Units) => this.convertTo(this.value, units);

		return {
			val: this.value.val,
			units: this.value.units,
			as: utility,
		};
	}

	protected override onSet(_newVal: { val: NumberType; units: Units; }, _source: SetSource): void {
		if (this.getRadix() === 16) {
			return;
		}
		this.value = this.toIdealUnit(this.value, this.permittedUnitsRange);
	}

	private isPermittedUnitsPrefix(u: UnitsPrefix, index?: number): boolean {
		let i = index;
		if (!i) {
			i = _.indexOf(UNITS_PREFIX, u);
		}
		return this.permittedUnitsRange[0] <= i && i <= this.permittedUnitsRange[1];
	}

	private convertTo(input: NumberAndUnits<NumberType>, output: Units | UnitsPrefix): NumberType {
		if (!isUnitsPrefix(output) && this.baseUnits !== getBaseUnits(output)) {
			throw Error(`unitsConfigurable: found ${getBaseUnits(output)} but expected ${this.baseUnits}`);
		}

		const unitsIn = !isUnitsPrefix(output) ? getUnitsPrefix(output) : output;
		if (!this.isPermittedUnitsPrefix(unitsIn)) {
			throw Error(`unitsConfigurable: ${unitsIn} is not a permitted unit`);
		}

		return this.convertToImpl(input, unitsIn);
	}
}

