export const memberSeparator = " ";

/**
 * Set the solution
 */
export function updateSolution(
	solution: PinSolution,
	ballName: string,
	peripheralPinName: string,
	interfacePinName: string,
	muxMode: string): void;
export function updateSolution(
	solution: Solution,
	peripheralName: string): void;
export function updateSolution(
	solution: Solution | PinSolution,
	ballOrPeripheral: string,
	peripheralPinName?: string,
	interfacePinName?: string,
	muxMode?: string) {

	if (solution instanceof PinSolution) {
		solution.assignedPeripheralPin = peripheralPinName.trim();
		solution.assignedInterfacePin = interfacePinName.trim();
		solution.assignedMuxMode = muxMode.trim();
	}
	solution.assignedToName = ballOrPeripheral.trim();
	solution.errorText = "";
	solution.warningText = "";
	solution.warningDetailsText = [];
	solution.errorDetailsText = [];
	delete solution.ioSet;
}

export function addErrorToSolution(solution: Solution, errorText: string) {
	solution.errorText = errorText.trim();
}

export function addVoltageWarningToSolution(solution: Solution, warningText: string) {

	solution.warningDetailsText.push(warningText.trim());
	solution.warningText =
		-1 !== solution.warningText.indexOf("Resource") ? "Resource/Voltage conflict" : "Voltage conflict";
}

export function addWarningToSolution(
	solution: Solution,
	warningDetailsText: string,
	warningText: string = ResourceConflictText.RES_CONFLICT,
) {
	solution.warningDetailsText.push(warningDetailsText.trim());
	if (solution instanceof PinSolution && (-1 !== solution.warningText.indexOf("Voltage"))) {
		solution.warningText = "Resource/Voltage conflict";
	} else if (solution.warningDetailsText.length > 1) {
		solution.warningText = ResourceConflictText.RES_CONFLICT;
	} else {
		solution.warningText = warningText;
	}
}

export function addSolverWarningToSolution(solution: Solution) {

	solution.warningDetailsText.push(
		"Solver: 'Performance can likely be improved by specifying the exact peripheral to use, " +
		"or by adding these peripherals once rest of the configuration is complete.'");
	solution.warningText = "Performance warning";
}

export function addErrorDetailsToSolution(solution: Solution, detailsText: string) {
	solution.errorDetailsText.push(detailsText.trim());
}

export function clearSolution(solution: Solution) {
	updateSolution(solution as any, "", "", "", "");
}

