function freezeDeepImpl<T>(obj: T) {
	if (!Object.isFrozen(obj)) {
		Object.freeze(obj);
		if (_.isObject(obj)) {
			_.each(obj, freezeDeepImpl);	// returns void, so we won't break out
		}
	}
}

export function freezeDeep<T>(obj: T) {
	freezeDeepImpl(obj);
	return obj;
}

export function isDeepFrozen<T>(obj: T): boolean {
	if (_.isObject(obj)) {
		return Object.isFrozen(obj) && _.every(obj, isDeepFrozen);
	} else {
		return true;
	}
}

export function forbiddenModification(msg: string) {
	throw new Error(`Forbidden modification: ${msg}`);
}

export function assertNeverThrows<T>(errorStore: ErrorStore, promiseOrFunc: Promise<T> | (() => Promise<T>)) {
	if (_.isFunction(promiseOrFunc)) {
		promiseOrFunc = promiseOrFunc();
	}
	promiseOrFunc.catch((e) => errorStore.registerException(e));
}

export function addFinally<T>(promise: Promise<T>, cb: () => void) {
	return promise
		.then((result) => {
			cb();
			return result;
		}, (e) => {
			cb();
			throw e;
		});
}

