// Converts an internal proxy object to something simple for JSON.

export function mapInternalObjectForJSON(value: any): any {
	if (_.isArray(value)) {
		return _.map(value, mapInternalObjectForJSON);
	}
	if ((_.isObject(value) as any)) {
		if (!_.isUndefined(value.name)) {
			return value.name;
		} else if (!_.isUndefined(value.$name)) {
			return value.$name;
		}
	}
	return value;
}

export function doWhenUIIdle<T>(func: () => T): Promise<T> {
	return new Promise<T>((resolve, reject) => {
		unstable_scheduleCallback(unstable_IdlePriority, () => {
			let result;
			try {
				result = func();
			} catch (err) {
				reject(err);
				return;
			}
			resolve(result);
		});
	});
}

export function convertUnknownToError(e: unknown): Error {
	if (e instanceof Error) {
		return e;
	} else if ((e as any).message && (e as any).stack) {
		return {
			name: "Unknown error",
			message: (e as any).message,
			stack: (e as any).stack,
		};
	}
	else {
		return new Error("Unknown error: " + e);
	}
}
