import * as _ from "lodash";
import { ClockTree, IPInstance } from "clockTree";
import { ClockIpInstanceMgr } from "../objectManagers/clockIpInstanceMgr";
import { PinFrequencyConfigurableMgr } from "../objectManagers/configurables/pinFrequencyConfigurableMgr";
import { namedConnectionModuleName } from "../resources/builtIn/namedConnectionModule";
import { Runtime } from "../resources/runtime";
import { addAlwaysPresentModule } from "../product/alwaysPresentModules";

type ModuleMap = { [ipName: string]: string };

// Given the clock tree data and module map, adapt the raw data into graphical data and create modules to represent
// each node in the graph

export function initClockTree(runtime: Runtime, modulePathMap: ModuleMap, rawClockTree: ClockTree, staticConfiguration?: string) {
	const clockTree = insertConnectionLabels(rawClockTree);
	const modules = associateModules(clockTree, modulePathMap, runtime);
	connectModules(clockTree, modules);
	if (staticConfiguration) {
		addAlwaysPresentModule(runtime, staticConfiguration);
	}

	return {
		modules,
		clockTree,
	};
}

// Find all important connections (those with a displayName) and create a fake node in the graph (ie a fake ip 
// instance) for it.  This allows us to lay out the graph with specific connections treated as a node in the graph 
// which could be just a label or a full box with a frequency value listed

export function insertConnectionLabels(clockTree: ClockTree): ClockTree {
	const [namedConnections, unnamedConnections] = _.partition(clockTree.connectivity, (c) => !!c.displayName);
	const namedConnectionNodes = _.map(namedConnections, (s) => {
		return {
			...s,
			type: "NamedConnection",
			shape: "NamedConnection" as const,
			inPins: [{ name: "in", displayName: "" }],
			outPins: _.isEmpty(s.targets) ? [] : [{ name: "out", displayName: "" }],
		};
	});
	const adaptedConnections = _.flatMap(namedConnections, (s) => {
		const newConnections = [{
			name: "$left-" + s.name,
			source: s.source,
			targets: [{
				instName: s.name,
				pinName: "in",
			}],
		}];
		if (!_.isEmpty(s.targets)) {
			newConnections.push({
				name: "$right-" + s.name,
				source: {
					instName: s.name,
					pinName: "out",
				},
				targets: s.targets,
			});
		}
		return newConnections;
	});
	return {
		connectivity: _.sortBy([...adaptedConnections, ...unnamedConnections], (s) => s.name),
		ipInstances: _.sortBy([...namedConnectionNodes, ...clockTree.ipInstances], (s) => s.name),
		groups: clockTree.groups,
	};
}

// Create a module instance for each ip instance and associate them with that ip instance

function associateModules(clockTree: ClockTree, modulePathMap: ModuleMap, runtime: Runtime): Record<string, ClockIpInstanceMgr> {
	return _.chain(clockTree.ipInstances)
		.map((ipInst) => {
			const mod = runtime.getModuleMgr(getModuleName(modulePathMap, ipInst));
			const inst = ClockIpInstanceMgr.createInstance(
				runtime,
				mod.module,
				ipInst
			);
			return [ipInst.name, inst];
		})
		.fromPairs()
		.value();
}

function getModuleName(modulePathMap: ModuleMap, { type }: IPInstance) {
	const module = modulePathMap[type];
	if (!module) {
		if (type === "NamedConnection") {
			// We can use the builtin module
			return namedConnectionModuleName;
		}
		throw new Error(`meta-code does not indicate how to handle the ip instance type "${type}"`);
	}
	return module;
}

// (Re)define input pins as calculated configurables that read from the output pin they are connected to

function connectModules(clockTree: ClockTree, modules: Record<string, ClockIpInstanceMgr>) {
	_.each(clockTree.connectivity, (c) => {
		const source = modules[c.source.instName].memberMgrs[c.source.pinName] as PinFrequencyConfigurableMgr;
		_.each(c.targets, (t) => modules[t.instName].addInputPin({
			name: t.pinName,
			getValue: () => source.get(),
		}));
	});
}
