import * as _ from "lodash";

export interface Selection {
	getFiltersForOverridden(): string[];
	isOverridden(): boolean;
}

// This class is used to enable disable options in dependant selections ( like html <select> ). For example,
// The peripheral selection and device pin selections are dependant on each other. If a device pin is chosen by the user
// that is available on only a particular set of peripherals than only options for those peripherals should be available
// in the peripheral select and only device pin selections mapping to those peripherals should be available.
export class SelectionFilterGroup {

	private readonly selections: Selection[] = [];
	public constructor() {
	}

	public addSelection(selection: Selection) {
		this.selections.push(selection);
	}

	public removeSelection(selection: Selection) {
		_.pull(this.selections, selection);
	}

	public filterOptions<OptionType>(
		selection: Selection, options: OptionType[], getFilterForOption: (o: OptionType) => string[]) {

		const overridenSelections = this.getOverridden();

		// there are no overrides or we are the only override, then all are enabled
		if (overridenSelections.length === 0
			|| overridenSelections.length === 1 && selection.isOverridden()) {
			return {
				enabled: options,
				disabled: [] as OptionType[],
			};
		}

		const filters = this.getFilters(overridenSelections, selection);
		const enabled: OptionType[] = [];
		const disabled: OptionType[] = [];

		_.each(options, (o) => {
			if (_.difference(filters, getFilterForOption(o)).length < filters.length) { // enabled
				enabled.push(o);
			} else {
				disabled.push(o);
			}
		});

		return {
			enabled,
			disabled,
		};
	}

	// get the filter to apply
	// the filter is the selection other than current selection, with the most restrictions
	// for example if one selection overrides limits selections to (GPIO3,GPIO0) and another
	// selection limits to (GPIO3) then Selection which limits to (GPIO3) is the most restrictive
	private getFilters(overridenSelections: Selection[], selection: Selection) {
		return _.chain(overridenSelections)
			.without(selection)
			.reduce((prev, currSelection) => {
				const currSelectionFilters = currSelection.getFiltersForOverridden();
				return (currSelectionFilters.length < prev.length || prev.length === 0) ? currSelectionFilters : prev;
			}, [] as string[])
			.value();
	}

	// get the groups that are overridden ( not isAny )
	private getOverridden() {
		return _.filter(this.selections, (selection) => selection.isOverridden());
	}

}
