import * as _ from "lodash";

import DeviceData = require("dataInterfaces");
import { AInstanceContainer, InstanceType } from "./instanceContainer";
import { PinmuxPinInterfaceInstanceMgr } from "../objectManagers/pinmuxPinInterfaceInstance";
import {
	InterfaceInstanceMgr,
	PinmuxPeripheralInterfaceInstanceMgr,
} from "../objectManagers/interfaceInstance";
import { Runtime } from "../resources/runtime";
import { InternalValidationLogger } from "../objectManagers/validations";
import { Tab } from "../tabs";

export type SomeInterfaceInstanceMgr = InterfaceInstanceMgr | PinmuxPinInterfaceInstanceMgr;

/**
 * Class to track managers for instances of a particular interface.
 */
export class InterfaceMgr
	extends AInstanceContainer<SomeInterfaceInstanceMgr> {

	private parentTab: Tab = null;

	constructor(
		private readonly runtime: Runtime,
		public readonly iface: DeviceData.Interface,
	) {
		super(iface.name);
	}

	public override getParentTab() {
		return this.parentTab;
	}

	public setParentTab(tab: Tab) {
		this.parentTab = tab;
	}

	public getName() {
		return this.iface.name;
	}

	public getSolverRequirements() {
		return _.flatMap(this.instances, (inst) => inst.getSolverRequirements());
	}

	public getNonInstUsedPins() {
		return new Set<string>();
	}

	public solveComplete() {
		_.each(this.instances, (inst) => { inst.solveComplete(); });
	}

	public applySolverValidation() {
		_.each(this.instances, (inst) => inst.applySolverValidation());
	}

	public get(index: number) {
		return this.instances[index];
	}

	public getDisplayName(): string {
		return this.iface.name;
	}

	public getMaxAllowed(): number {
		return this.iface.peripherals ? this.iface.peripherals.length : 0;
	}

	public addInstance(): SomeInterfaceInstanceMgr {
		const inst = this.createInterfaceInstance();
		this.runtime.addInterfaceInstance(inst);
		return inst;
	}

	public getNumberOfUsed(): number {
		if (!_.isEmpty(this.instances) &&
			_.first(this.instances) instanceof PinmuxPinInterfaceInstanceMgr) {
			return _.sumBy(this.instances, (inst) => inst.getVisiblePinMgrs().length);
		} else {
			return this.instances.length;
		}
	}

	public getTotalUsedAcrossContexts(): number {
		return this.runtime.getTotalUsed(this.getDisplayName(), InstanceType.Interface);
	}

	public getScriptIdentifier(): string {
		const identifers = this.runtime.getSerializationContext().getModuleIdentifiers();
		return identifers.getScriptIdentifiers(this, getScriptIdentifier(this.iface));
	}

	public getDescription(): string {
		return "";
	}

	public validate(validationLogger: InternalValidationLogger) {
		_.each(this.instances, (i) => i.validate(validationLogger));
	}

	public getDefaultInstanceName() {
		return "My" + this.iface.name;
	}

	public getRuntimeSelection() {
		return this.getSelectedMyListItem()?.managedObject;
	}

	private createInterfaceInstance() {
		if (this.runtime.getPinOptimizations().isOptimizable(this.iface.name)) {
			return new PinmuxPinInterfaceInstanceMgr(this.runtime, this.iface);
		} else {
			return new PinmuxPeripheralInterfaceInstanceMgr(this.runtime, this.iface, {}, !this.runtime.isCorePinmux());
		}
	}

}

export function getScriptIdentifier(iface: DeviceData.Interface) {
	// Interface name would ideally be a C-identifier, but it's not always.
	// Instead of generically coming up with an algorithm that is perfect, 
	// I have one that is simple, but is tested in dataSanity.ts 
	// (in the test validScriptIdentifiers)

	return "i" + iface.name.replace(/-/g, "_");
}
