import * as _ from "lodash";
import { Module as ModuleDef } from "public/defs";
import { Module } from "public/runtime";

export function validateUIAdd(mod: Module) {

	if (hasInstanceConfig(mod)) { // has instance config
		if (mod.uiAdd === "staticOnly") {
			throw new Error(`Invalid uiAdd value ${mod.uiAdd}, ${mod.$name} has instance config`);
		}
	} else if (hasStaticConfig(mod)) { // has no instance config, but has static config
		if (mod.uiAdd === "staticAndInstance" || mod.uiAdd === "instanceOnly") {
			throw new Error(`Invalid uiAdd value ${mod.uiAdd}, ${mod.$name} has no instance config defined`);
		}
	}

}

// Map to indicate if the module is instantiable.
// The keys marked true are ones which contribute to the
// configuration and thus an instance would be meaningful.
// The other keys are general module properties used for
// documentation, ui view, etc..
// Ideally, these would have been name spaced under "moduleInstance"
// similar to "moduleStatic"
// Note that templates/references/validate are  based on the module
// definition, so they will always be there, even for static modules

const configKeys: {
	[P in keyof Required<ModuleDef>]: boolean;
} = {
	moduleStatic: false,
	templates: false,
	references: false,
	maxInstances: false,
	defaultInstanceName: false,
	config: true,
	pinmuxRequirements: true,
	moduleInstances: true,
	sharedModuleInstances: true,
	modules: true,
	validate: false,
	validatePinmux: false,
	filterHardware: false,
	onHardwareChanged: false,
	displayName: false,
	description: false,
	longDescription: false,
	documentation: false,
	uiView: false,
	uiAdd: false,
	alwaysShowLongDescription: false,
	migrateLegacyConfiguration: false,
	recreateOnArgsChange: false,
	proxyFor: false,
	extendConfig: true,
	onMigrate: false,
	ports: true,
	dependencies: false,
};

// Adding exemptions for some modules to maintain backward compatibility.
// JIRA for meta content fixes - SCSTUDIO-939, SLLVGLPLG-38
const instanceCreateExemptions = [
	"/ti/radioconfig/target_config",
	"/ti/radioconfig/TargetConfig",
	"/ti/lvgl/templates_sharp",
];

export function validateInstanceCreateAllowed(mod: Module) {
	if (!hasInstanceConfig(mod)
		&& !_.includes(instanceCreateExemptions, mod.$name)) {
		throw new Error(`Can't create an instance, ${mod.$name} has no instance config defined`);
	}
}

export function hasInstanceConfig(mod: ModuleDef) {
	return _.some(mod, (_val, key: keyof ModuleDef) => configKeys[key]);
}

function hasStaticConfig(mod: ModuleDef) {
	return hasInstanceConfig(mod.moduleStatic);
}
