import * as _ from "lodash";
import { AbstractChoice } from "./common";
import { DevicePinChoices } from "./devicePin";
import { InterfacePinChoices } from "./interfacePin";
import { SolutionMap, pushOptimizablePin } from "../choices";
import { ChoiceValidator } from "./choiceValidator";
import { nameChoices, formatNameChoice } from "../debug";
import { OptimizablePin, Pin } from "../requirements";
import { addErrorToSolution, clearSolution, updateSolution } from "../../utils";
import { chooseAll } from "../clauseGeneration";
import { OptimizablePinMap, Optimizations } from "../optimizations";

// -----------------------------------------------------------------------------
// OptimizablePinChoices
// A factory for creating a choice of a specific optimizable pin to meet an optimizable 
// requirement.  When not an override, this just adds a requirement to the 
// clauses to fail solving if no free optimizable pins are available.  When it is an
// override, a real device pin choice is created, dependent on a dummy choice
// that must always be taken (or an error choice must be taken).  That 
// restricts other pin requirements from stealing our override value.
// -----------------------------------------------------------------------------

export class OptimizablePinChoices {
	private readonly nonTrivialChoices: OptimizablePinChoices.NonTrivialChoice[] = [];

	private readonly freePins: OptimizablePinMap;
	private readonly allPins: OptimizablePinMap;
	private readonly clauseText: string;
	constructor(
		private readonly choiceValidator: ChoiceValidator,
		private readonly interfacePinChoices: InterfacePinChoices,
		private readonly devicePinChoices: DevicePinChoices,
		optimizations: Optimizations,
		interfaceName: string,
	) {
		this.freePins = optimizations.getFreePins(interfaceName);
		this.allPins = optimizations.getAllPins(interfaceName);
		this.clauseText = `each pin requirement must choose one ${interfaceName} pin mapping`;
	}

	public newChoice(parentReq: OptimizablePin, pinReq: Pin) {

		if (pinReq.userOverride ||
			pinReq.restrictTo ||
			pinReq.canShareWith ||
			this.choiceValidator.isSolveRestricted()) {

			// If there are any restrictions on the optimizable choice, then we need to create a specific 
			// choice object for each possible choice.  But if not, then we can create one simple 
			// basic choice object that has some optimization tricks

			const specificChoice = new OptimizablePinChoices.NonTrivialChoice(parentReq, pinReq);
			this.nonTrivialChoices.push(specificChoice);
			const pinChoices = (pinReq.connectedToHardware || pinReq.userOverride) ? this.allPins : this.freePins;
			const hasNoChoices = _.chain(pinChoices)
				.filter((info) => this.choiceValidator.isValid(pinReq, info.devicePin, info.peripheralPin))
				.map((info) => {
					const interfacePinChoice = this.interfacePinChoices.newChoice(specificChoice, info.peripheralPin, pinReq);
					return this.devicePinChoices.newChoice(interfacePinChoice, info.peripheralPin, info.devicePin, pinReq);
				})
				.isEmpty()
				.value();

			// If there weren't any valid choices, add a choice for nothing 
			// That ensures at least an error choice is created

			if (hasNoChoices) {
				this.interfacePinChoices.newChoice(specificChoice, null, pinReq);
			}
		} else {

			// No restrictions - we can just pick a free pin after the rest of the solving is done
			new OptimizablePinChoices.BasicChoice(this.freePins, parentReq, pinReq);
		}
	}

	public generateClauses() {
		chooseAll(this.nonTrivialChoices, null, this.clauseText);
	}
}

export namespace OptimizablePinChoices {

	function getErrorId(parentReq: OptimizablePin, pinReq: Pin) {
		return parentReq.id + "->" + pinReq.getUnqualifiedName();
	}
	// This class represents a basic optimizable pin choice with no restrictions.  It's optimized to solve outside of the solver
	// and thus is a lot faster to use when possible

	export class BasicChoice {
		public readonly name?: string;

		constructor(
			private readonly pinMap: OptimizablePinMap, parentReq: OptimizablePin, private readonly pinReq: Pin) {

			// Push a optimizable pin choice to the choice array.  
			// The choice array will just see if enough free pins of that type are left, and 
			// will indicate solved or not based only on that.

			// This completely eliminates a HUGE number of clauses being generated

			const applyError = () => {
				clearSolution(pinReq.solution);
				addErrorToSolution(pinReq.solution, "Resource conflict");
			};
			pushOptimizablePin(this, { apply: applyError }, getErrorId(parentReq, pinReq), parentReq.interfaceName);

			if (nameChoices) {
				this.name = parentReq.interfaceName + " choice";
			}
		}

		public apply(solutionMap: SolutionMap) {

			// Pick any optimizable pin choice from whatever is left

			const choice = _.find(this.pinMap, (info) => {
				return !(info.devicePin.name in solutionMap.devicePins);
			});

			// Use that choice as the answer, and update the solution objects as normal
			const muxMode = _.find(choice.devicePin.mux.muxSetting, (i) => i.peripheralPin === choice.peripheralPin).mode;
			updateSolution(
				this.pinReq.solution, choice.devicePin.name, choice.peripheralPin.name, choice.interfacePin.name, muxMode);

			const ball = choice.devicePin.name;
			const devicePins = solutionMap.devicePins[ball] || (solutionMap.devicePins[ball] = []);
			devicePins.push(this.pinReq);

			const name = choice.peripheralPin.name;
			const peripheralPins = solutionMap.peripheralPins[name] || (solutionMap.peripheralPins[name] = []);
			peripheralPins.push(this.pinReq);
		}
	}

	// This choice represents a restricted pin choice, and thus must generate underlying device pin choice objects and
	// operate through the SAT solver.

	export class NonTrivialChoice extends AbstractChoice {
		constructor(
			public readonly parentReq: OptimizablePin,
			pinReq: Pin) {
			super();

			if (nameChoices) {
				this.name = parentReq.interfaceName + " SAT choice: " + formatNameChoice(pinReq);
			}
		}

		public apply() {
			// we don't need to do anything - device pin choice will update the solution
		}

		public getRequirementId() {
			return this.parentReq.id;
		}

		public getShareHash() {
			return "";
		}

		public hasError() {
			return false;
		}
	}
}
