import * as _ from "lodash";
import { SingleInstanceReferenceConfigurable } from "public/defs";
import { ModuleInstance, RuntimeObject } from "public/runtime";
import { Runtime } from "../../resources/runtime";
import { getScriptIdentifier } from "../../scripting/serialize";
import { SetSource } from "../member";
import { AObjectMgr } from "../object";
import { BaseInstanceReferenceConfigurableMgr } from "./baseInstanceReferenceConfigurableMgr";
import { ConfigurableComponent } from "./configurableComponent";

export class SingleInstanceReferenceConfigurableMgr
	extends BaseInstanceReferenceConfigurableMgr<ModuleInstance, SingleInstanceReferenceConfigurable>
{
	public readonly ui = ConfigurableComponent.SingleInstanceReferenceConfigurable;
	constructor(
		parentObjectMgr: AObjectMgr<RuntimeObject>,
		def: SingleInstanceReferenceConfigurable,
		runtime: Runtime,
	) {
		super(
			parentObjectMgr,
			runtime.getFormattersMap(),
			def,
			null,
			runtime,
		);
	}

	public getUIOptions() {
		const enabledOptions = this.getEnabledOptions();
		const selectedOptionName = this.value ? _.first(this.getValueMgrs()).getID() : null;
		if (this.def.hideNoneOption) {
			return { enabledOptions, selectedOptionName };
		}
		return { enabledOptions: [{ name: "None", data: null as ModuleInstance }, ...enabledOptions], selectedOptionName };
	}

	protected override getRValue() {
		return this.value ? getScriptIdentifier(this.runtime.getManager(this.value)) : "null";
	}

	protected override validateValue(value: ModuleInstance, forceWrite: boolean, source: SetSource) {
		super.validateValue(value, forceWrite, source);
		if (value && !this.runtime.getManager(value)) {
			throw new Error("Unknown module instance assigned");
		}
	}

	protected override getValueMgrs(value = this.value) {
		return value ? [this.runtime.getManager(value)] : [];
	}

	protected onModuleRemoved = () => {
		this.setDefault();
	}
}
