import * as _ from "lodash";
import { convertUnknownToError } from "./utils";

// Quotes strings, but returns the default string representation otherwise

export function assignmentToString(value: any, recurse = true): string {
	if (_.isArray(value)) {
		return `[${_.map(value, assignmentToString).join(", ")}]`;
	}
	if (_.isObject(value) as any) {
		if (value.name || value.$name) {
			return value.name || value.$name;
		} else if (recurse) {

			// JSON.stringify will not replace modules with $name at the top level, doesn't work with a recursive 
			// object definition, and is often too much detail.  Instead, just list the top level values and 
			// [object, object] for nested objects.

			return "{" + _.map(value, (v, k) => `${k}: ${assignmentToString(v, false)}`).join(", ") + "}";
		}
	}
	return _.isString(value) ? `'${value}'` : `${value}`;
}

// Firefox doesn't include the message with the stack, but chrome/jxbrowser do.
// This lets us fetch both regardless of the browser

export function getMessageAndStack(exception: Error) {
	return _.includes(exception.stack, exception.message) ?
		exception.stack : `${exception.name}: ${exception.message}:\n${exception.stack}`;
}

// Extends the message of an exception with some context and re-throws
// Also updates the stack if the stack includes the message

export function extendException(context: string, e: Error): never {
	const newMessage = `${e.message}:\n${context}`;
	const newError = cloneException(e);
	newError.message = newMessage;
	newError.stack = _.replace(e.stack, e.message, newMessage);
	throw newError;
}

// Magic key that we'll set on propagated exceptions.  I'm not expecting it to clash based on the name

const isInternalException = "$__isSysconfigException";

// Called anywhere that we switch from something initiated by the user, to something internal (ie where we are running
// internal meta-code).  

export function internalBoundary<T>(func: () => T) {
	try {
		return func();
	} catch (e) {
		const newError = cloneException(convertUnknownToError(e));
		newError[isInternalException] = true;
		throw newError;
	}
}

// A new exception (with a new stack) to re-throw that saves the original
// cause of an error

export class UserError extends Error {
	constructor(message: string, private readonly cause: any) {
		super(message);
		if (cause[isInternalException] ||		// if marked by us as explicitly being due to an internal cause, and not the user
			cause instanceof RangeError ||		// ... or if it's a runtime exception (vs explicitly thrown) and thus unexpected
			cause instanceof ReferenceError ||
			cause instanceof SyntaxError ||
			cause instanceof TypeError
		) {
			// ... then we need to save the stack of what caused this exception so we have that information, as well as 
			// the current stack, which will list the originating location (user code or meta-code + line number).

			// Note: we explicitly don't update the message.  We don't want the user to think that what they
			// just did is the cause of the error - instead, what they just did exposed an internal bug!

			this.stack = `${this.stack}\nCaused by: ${getMessageAndStack(cause)}`;
		} else {

			// Otherwise, the exception was thrown in response to something dumb/obvious that the code (user/meta) did.
			// We don't need to save the stack from where we detected that - the message should be plenty.  But, we do
			// want to update the message at the current context so it's known where the originating source line is

			this.message = `${this.message}: ${cause.message}`;
		}
	}

	// Access to the root case for testing purposes

	public rootCause() {
		let rootCause = this.cause;
		while (rootCause instanceof UserError) {
			rootCause = rootCause.cause;
		}
		return rootCause;
	}
}

// By using Object.create() and passing it the original prototype, we ensure the clone has the same class.  Meaning if
// SyntaxError was thrown, this will be a new SyntaxError vs just Error.  We then assign the original stack/message 
// using Object.assign

function cloneException(e: Error) {
	const newException = Object.assign(Object.create(Object.getPrototypeOf(e)), e);
	newException.message = e.message;
	newException.stack = e.stack;
	return newException;
}
