import * as _ from "lodash";
import { HardwareComponent, Module } from "public/runtime";
import { AdaptedDeviceInfo } from "dataInterfaces";
import { ModuleMgr } from "./instanceContainers/module";
import { Runtime } from "./resources/runtime";
import { guardCallbackAccess } from "./moduleAccessGuard";
import { ITreeNode } from "../components/TreeNode";

export class ModuleToHardwareMap {
	private readonly modulesToComponents: { [moduleName: string]: HardwareComponent[] } = {};
	private readonly uiDefaults: { [moduleName: string]: HardwareComponent } = {};
	private readonly componentsToModules: { [hardwareName: string]: ModuleMgr[] } = {};
	private readonly cache: { [moduleName: string]: { [hardwareName: string]: boolean } } = {};
	private allComponents: HardwareComponent[];
	private componentsToTreeNodes: { [hardwareName: string]: ITreeNode[] } = {};

	constructor(
		private readonly runtime: Runtime,
		private readonly deviceData: AdaptedDeviceInfo,
	) {
	}

	public getComponents(module: Module) {
		const key = module.$name;
		if (!this.modulesToComponents[key]) {
			this.modulesToComponents[key] =
				_.filter(this.getAllComponents(), (component) => this.fetchAndCache(module, component));
		}
		return this.modulesToComponents[key];
	}

	public getUIDefault(module: Module) {
		const key = module.$name;
		if (!(key in this.uiDefaults)) {
			const getUIDefault = module.$configByName.$hardware.getUIDefault ??
				module.moduleStatic?.$configByName.$hardware.getUIDefault;
			this.uiDefaults[key] = getUIDefault
				? guardCallbackAccess(() => getUIDefault(this.getComponents(module)), "getUIDefault")
				: null;
		}
		return this.uiDefaults[key];
	}

	public getModules(component: HardwareComponent) {
		const key = component.name;
		if (!this.componentsToModules[key]) {
			const topModules = _.map(this.runtime.getTopModules().getModuleNames(), (m) => this.runtime.getModuleMgr(m));
			this.componentsToModules[key] = _.filter(topModules, (module) => this.fetchAndCache(module.module, component));
		}
		return this.componentsToModules[key];
	}

	public getTreeNodes(component: HardwareComponent) {
		return this.componentsToTreeNodes[component.name] ?? []; // could be undefined if it's the command line version
	}

	public setTreeNode(component: HardwareComponent, treeNode: ITreeNode) {
		const entry = this.componentsToTreeNodes[component.name] ?? (this.componentsToTreeNodes[component.name] = []);
		entry.push(treeNode);
	}

	public resetTreeNodes() {
		this.componentsToTreeNodes = {};
	}

	private getAllComponents() {
		if (!this.allComponents) {
			this.allComponents = getAllComponents(this.deviceData);
		}
		return this.allComponents;
	}

	private fetchAndCache(module: Module, component: HardwareComponent) {

		// Fetch the value from the cache, and if not cached, call filterHardware

		let cache: boolean = _.get(this.cache, [module.$name, component.name], undefined);
		if (_.isUndefined(cache)) {
			cache = guardCallbackAccess(
				() => module.$configByName.$hardware.filterHardware(component),
				"filterHardware",
			) ||
				(module.moduleStatic &&
					guardCallbackAccess(
						() => module.moduleStatic.$configByName.$hardware.filterHardware(component),
						"filterHardware",
					));
			_.set(this.cache, [module.$name, component.name], cache);
		}
		return cache;
	}
}

export function getAllComponents(deviceData: AdaptedDeviceInfo) {

	// This returns all components in the system, including subComponents (which aren't 
	// necessarily under the board, but under another component).  The result must be uniq-ed
	// as a subComponent could be a link to a top level component

	return deviceData.board ? _.uniq(getSubComponentsDeep(deviceData.board.components)) : [];

	// Recursive function to get subComponents, and their subComponents, etc

	function getSubComponentsDeep(components: { [name: string]: HardwareComponent }): HardwareComponent[] {
		return ([
			..._.values(components),
			..._.flatMap(components, (component) => getSubComponentsDeep(component.subComponents)),
		]);
	}
}
