import * as _ from "lodash";
import {
	AdvancedHexRadix,
	AdvancedDecRadix,
	DisplayFormat,
	DisplayRadix,
} from "public/defs";
import { IValidatable, Validations } from "../objectManagers/validations";

const numberFormats = {
	posInt: /^\+?[0-9]*$/,
	int: /^[+-]?[0-9]*$/,
	hex: /^0x[0-9A-Fa-f]*$/,
	dec: /^[+-]?[0-9]*\.?[0-9]*$/,
} as const;

export type NumStrFormatType = keyof typeof numberFormats

export const enum Radix {
	DEC = 10,
	HEX = 16,
}

// Check whether an unrestricted string is a hex number
export function numStrIsHex(strVal: string) {
	return (numberFormats.hex).test(strVal);
}

// Check whether an unrestricted string is a decimal number
export function numStringIsDec(strVal: string) {
	return (numberFormats.dec).test(strVal);
}

// Converts a number string (dec or hex) to a hex format string with leading 0x
function numStrToHex(val: string, bitSize?: number) {
	return "0x" + // leading 0x for readability
		(
			bitSize ?
				_.padStart(val, strLenFromBitsize(bitSize), "0")
				: val
		);
}

// Converts a number string (dec or hex) to a dec format string
function numStrToDec(val: string, fixedPoint?: number) {
	return fixedPoint ?
		Number(val).toFixed(fixedPoint)
		: Number(val).toString(10);
}

// Convert a number string to a string with specific target radix
export function formatNumStr(
	strVal: string, format: Radix,
	optionalParams: { bitSize?: number, fixedPoint?: number }) {
	if (isNaN(+strVal)) {
		return "NaN";
	}
	const rawValueStr = Number(strVal).toString(format).toUpperCase();
	return format === Radix.HEX ?
		numStrToHex(rawValueStr, optionalParams.bitSize) :
		numStrToDec(rawValueStr, optionalParams.fixedPoint);
}

// Check if a number string can be converted to a specific format
export function stringMatchFormat(val: string, formats: NumStrFormatType[], isNumericMgr: boolean) {
	if (val === "") {
		return true;
	} else if (isNumericMgr && val.length > 20 && (_.indexOf(val, ".") === -1 || _.indexOf(val, ".") > 19)) {
		return false;
	}
	return _.some(formats, (f) => (numberFormats[f]).test(val));
}

export function extendNumberFormats(formats: NumStrFormatType[], extension: string): RegExp[] {
	const baseFormats = _.map(formats, (f) => numberFormats[f]);
	const ret = _.map(baseFormats, (f) => {
		const parsed = _
			.chain(f.toString())
			.trimStart("/^")
			.trimEnd("$/")
			.value();
		return new RegExp(`^${parsed}${extension}$`);
	});
	return ret.concat(baseFormats);
}

export function strLenFromBitsize(bitSize: number) {
	return Math.ceil(bitSize / 4);
}

export function getRadix(displayFormat?: DisplayFormat) {

	function isDisplayRadix(df: DisplayFormat): df is DisplayRadix {
		return _.isString(df);
	}

	if (!displayFormat) {
		return Radix.DEC;
	}

	const radix = isDisplayRadix(displayFormat) ? displayFormat : displayFormat.radix;
	return (radix === "hex" || radix === "HEX") ?
		Radix.HEX : Radix.DEC;
}

export function getAdvancedDisplayFormatOptions(opt: "fixedPoint" | "bitSize", displayFormat?: DisplayFormat) {
	if (opt === "fixedPoint") {
		return displayFormat && (displayFormat as AdvancedDecRadix)[opt];
	} else {
		return displayFormat && (displayFormat as AdvancedHexRadix)[opt];
	}
}

export function logErrorIfIntegerAndNotSafe(validations: Validations, configurable: IValidatable, val: unknown) {
	if (Number.isInteger(val) && !Number.isSafeInteger(val)) {
		validations.logWarning("Integer value must not exceed 53 bits", configurable);
	}
}

export function errorIfNotInteger(isInteger: boolean, val: any) {
	if (isInteger && !Number.isInteger(val)) {
		throw new Error("Value must be an integer");
	}
}

export function stringToNum(val: string) {
	return isNaN(+val) ? 0 : Number(val);
}

export function numToString(val: number, displayFormat?: DisplayFormat) {
	return formatNumStr(val.toString(), getRadix(displayFormat),
		{
			bitSize: getAdvancedDisplayFormatOptions("bitSize", displayFormat),
			fixedPoint: getAdvancedDisplayFormatOptions("fixedPoint", displayFormat),
		});
}

export function isInRange(val: number,
	range: [low: number, high: number]) {
	return _.isEmpty(range) || (range[0] <= val && val <= range[1]);
}
