import * as path from "path";
import { serializeProjectPath } from "../../projectPath";
import { storage } from "../../storage";
import { toLinuxPath } from "../../utils";
import { FileTextConfigurableMgr } from "./fileTextConfigurableMgr";

export class CloudFileTextConfigurableMgr extends FileTextConfigurableMgr {
	// The serialized path value can be serialized WYSIWYG
	// or relative(to a script file location when serializing to a script file)
	public override getScriptValue() {
		const outPath = serializeProjectPath ?
			toLinuxPath(path.relative(path.dirname(storage.formatPathForUser(serializeProjectPath)), this.value))
			: this.value;
		return { value: JSON.stringify(toLinuxPath(outPath)), shouldQuoteStrings: false };
	}

	// Transforms a path that is set into an absolute __user__ path in the cloud
	// The final path needs to be in user form because it is displayed in the UI
	//
	// When the path is read from a script, it could be absolute or relative.
	// Absolute __user__ path comes from serialized scripts that do not originate from files.
	// because we serialize cloud path WYSIWYG.
	// Relative path comes from serialized scripts originating from a file. In that case,
	// serializeProjectPath would be updated and contains the script file's __actual__ path.
	// So to get the absolute __user__ path, we need to resolve against the script files' __user__ path
	//
	// When the path is manually entered, it could be absolute or relative.
	// Absolute path is again the same as before.
	// Entering a relative path is possible without serializeProjectPath being set,
	// so the syscfg folder is used as the reference to resolve the relative path.

	public override transform(fpath: string) {
		if (fpath === "") {
			return fpath;
		}
		if (path.isAbsolute(fpath)) {
			return storage.formatPathForUser(fpath);
		}
		const referencePath = storage.formatPathForUser(
			serializeProjectPath
				? path.dirname(serializeProjectPath)
				: storage.getRootPaths()[0].path,
		);
		return path.resolve(referencePath, fpath);
	}
}
