import * as _ from "lodash";
import { ContainerNode } from "./viewNodes";

// Used to keep track of all tabs in the ui where the tabs represent container nodes
// This can be used instead of collapsible cards
export class TabGroup {
	private currentTab: ContainerNode;
	private tabNodes: ContainerNode[];
	constructor(containerNodes: ContainerNode[]) {
		this.tabNodes = _.filter(containerNodes, (node) => _.some(node.getChildren(), (child) => !child.isHidden()));
		this.currentTab = _.first(this.tabNodes);
		this.setParentForNodes();
	}

	public setCurrentTab(node: ContainerNode) {
		this.currentTab = node;
	}

	public getCurrentTab() {
		return this.currentTab;
	}

	public refresh(nodes: ContainerNode[]) {
		nodes = _.filter(nodes, (node) => _.some(node.getChildren(), (child) => !child.isHidden()));
		if (!_.isEqual(this.tabNodes, nodes)) {
			this.tabNodes = nodes;
			if (!_.find(this.tabNodes, (node) => node.getKey() === this.currentTab.getKey())) {
				this.currentTab = _.first(this.tabNodes);
			}
		}
		this.setParentForNodes();
	}

	public getNodes() {
		return this.tabNodes;
	}

	private setParentForNodes() {
		_.each(this.tabNodes, (node) => node.parentTabGroup = this);
	}
}
