import * as _ from "lodash";
import { ModuleInstanceMgr } from "../objectManagers/moduleInstance";
import { FormatStyle, FormatOptions, CLIFormatOptions, UIFormatOptions } from "./formattingTypes";
import { toFormattedLink, FormattedLinkAndDestination } from "./link";
import { assertUnreachable, getDisplayName, memberSeparator } from "../utils";
import { Member } from "public/defs";

export function format(instMgr: ModuleInstanceMgr, options: CLIFormatOptions, member?: string): string;
export function format(
	instMgr: ModuleInstanceMgr, options: UIFormatOptions, member?: string): FormattedLinkAndDestination;
export function format(
	instMgr: ModuleInstanceMgr, options: FormatOptions, member?: string): string | FormattedLinkAndDestination;
export function format(instMgr: ModuleInstanceMgr, options: FormatOptions, member?: string) {
	switch (options.style) {
		case FormatStyle.CLI:
			return formatCLI(instMgr, member);
		case FormatStyle.UI:
			return formatUI(instMgr, options, member);
		default:
			assertUnreachable(options);
			return "";
	}
}

// we should walk up the chain of parent modules until we find something the user will understand and
// that we can navigate to.  That means stop at the first created/modified top module, or when there is
// no parent.  We consider static modules to have no parent, as the parent is buried under "other"
// We shouldn't walk up to the parent if we're a shared module which is not a top module in graph view.
// In this case we can still click on the instance in the graph and tag an error on it
function shouldWalkToParent(m: ModuleInstanceMgr) {
	const hasParent = m.isCurrentlyShared() || m.isExclusivelyOwned();
	const hasParentInUI = hasParent && !m.isStatic();
	const hasMeaningToUser = m.isUserCreatedOrTouched() && m.isTopModule();
	return hasParentInUI && !hasMeaningToUser && !m.isHiddenSharedGraphable();
}

function formatCLI(instMgr: ModuleInstanceMgr, member?: string) {

	const memberChain = _.isEmpty(member) ? [] : [member];

	// Walk up the chain of parent modules until we find one the user will understand what it is 
	// (ie one that they created).
	// Ignore user modified setting - they may have modified it, but they don't have a left pane
	// to navigate to in this mode so they'd still want to reference from the owning module

	while (shouldWalkToParent(instMgr)) {
		const parent = instMgr.parentInstanceMgr || _.first(instMgr.getSharedBy());
		memberChain.push(
			instMgr.inArray() ?
				instMgr.parentModuleInstanceAdderMgr.getInstanceScriptIdentifier(instMgr) :
				_.find(parent.memberMgrs, (mgr) => mgr.getValue() === instMgr.managedObject).def.name,
		);
		instMgr = parent;
	}

	// Output the chain of members

	if (_.isEmpty(memberChain)) {
		return formatRootModuleCLI(instMgr);
	}
	return _.join([formatRootModuleCLI(instMgr), _.reverse(memberChain).join(".")], memberSeparator);
}

function formatRootModuleCLI(instMgr: ModuleInstanceMgr) {
	const instText = instMgr.isStatic() ?
		instMgr.managedObject.$name :
		`${instMgr.managedObject.$name}(${instMgr.getModuleMgr().static.managedObject.$name})`;

	const contextText = instMgr.getContextDisplayName();
	return contextText ? `${contextText} ${instText}` : instText;
}

function formatUI(mgr: ModuleInstanceMgr, options: UIFormatOptions, member?: string) {
	const { instMgr, memberDef, nestedInstanceNames } = getMeaningfulLocation(mgr, options, member);

	// Create the link to this UI location with meaningful text

	const formattedLink = toFormattedLink(
		instMgr.getContextId(),
		instMgr.getContextDisplayName(),
		instMgr.getPrimaryTab(),
		instMgr.getLeafTreeNode(),
		instMgr,
		memberDef,
		options.selection,
	);

	// If we had to walk the tree somewhat, then override the member path with that walk
	formattedLink.destination.memberPath = [..._.tail(_.reverse(nestedInstanceNames))];
	if (memberDef) {
		formattedLink.destination.memberPath.push(memberDef.name);
	}

	if (instMgr.isStatic()) {

		formattedLink.destination.instanceId = undefined;

		if (!instMgr.getModuleMgr().isStaticOnly()) {

			// When we try to focus on a member that is on the static module instance
			// of a module that is instantiable, we don't want to change the selected listItem.
			// Add the static module instance to the member path instead. 

			formattedLink.destination.memberPath
				= _.concat(instMgr.getNameMgr().getValue(), formattedLink.destination.memberPath);

			// Also, if this is the current selection, update the link text too

			if (member && options.selection && _.includes(instMgr.getModuleMgr().instances, options.selection.listItem)) {
				formattedLink.baseText = getDisplayName(memberDef, false);
			}
		}
	}

	return formattedLink;
}

function getMeaningfulLocation(instMgr: ModuleInstanceMgr, options: UIFormatOptions, member?: string) {
	// If no member was passed in, we should determine the parent and then set member
	// to be the passed in instMgr
	let memberDef: Member;
	if (member) {
		memberDef = instMgr.memberMgrs[member].def;
	} else if (shouldWalkToParent(instMgr)) {
		const parent = instMgr.getOwner() || _.first(instMgr.getSharedBy());
		if (parent) {
			memberDef =
				instMgr.inArray() ?
					{ name: instMgr.getName() } :
					_.find(parent.memberMgrs, (mgr) => mgr.getValue() === instMgr.managedObject).def;
			instMgr = parent;
		}
	}

	// If we can find a path from the instMgr to the current selection through a mix of owner/sharer
	// then we would want to use that path.
	// Otherwise, we will try to walk up until we get something that the user will understand
	let nestedInstanceNames = findPathToSelection(instMgr, options);
	if (_.isEmpty(nestedInstanceNames)) {
		nestedInstanceNames = [instMgr.getNameMgr().getValue()];
		while (shouldWalkToParent(instMgr)) {
			const parent = instMgr.getOwner() || _.first(instMgr.getSharedBy());
			if (parent) {
				instMgr = parent;
				nestedInstanceNames.push(instMgr.getNameMgr().getValue());
			} else {
				break;
			}
		}
	} else {
		// instMgr should be the top most module that is in the reference, so when the there is 
		// a path to the selection, it would just be that selection.
		instMgr = options.selection ? options.selection.listItem as ModuleInstanceMgr : undefined;
	}
	return { instMgr, memberDef, nestedInstanceNames };
}

// find an ownership path that can connect the argument with the selection.
function findPathToSelection(m: ModuleInstanceMgr, options: UIFormatOptions): string[] {
	// For static top modules when doing navigation always go to the 
	// module itself regardless of the selection, however if trying to 
	// focus on a member then take the selection into account 
	if (!m || !options.selection || (!options.isForFocus && m.isStatic() && m.isTopModule())) {
		return undefined;
	} else if (options.selection && m === options.selection.listItem) {
		return [m.getNameMgr().getValue()];
	} else {
		const possiblePaths = _.compact(_.map(m.getParents(), (p) => findPathToSelection(p, options)));
		if (!_.isEmpty(possiblePaths)) {
			// if there are multiple paths to the selection, it doesn't matter which one we pick
			return [m.getNameMgr().getValue(), ..._.first(possiblePaths)];
		} else {
			return undefined;
		}
	}
}
