import * as _ from "lodash";
import * as sourceMapSupport from "source-map-support";
import { rootDir } from "../services/paths";
import { isNode, isNodeWebkit, isCCS } from "./platform";

if (isNode()) {
	if (isNodeWebkit()) {
		const fs = require("fs");
		sourceMapSupport.install({
			environment: "node", // prevents an error in the console
			handleUncaughtExceptions: false,

			// NW won't know where to get map files from, as it will see files as "chrome-extension"

			retrieveSourceMap: (path) => {
				if (_.endsWith(path, ".js")) {
					let mapFile = `${rootDir()}/${_.last(_.split(path, "/"))}.map`; // our map file
					if (!fs.existsSync(mapFile)) {
						mapFile = path + ".map";	// meta-content map file?
					}
					if (fs.existsSync(mapFile)) {
						return {
							url: null,
							map: fs.readFileSync(mapFile, "utf8"),
						};
					}
				}
				return null;
			},
		});
	} else {

		// Defaults are fine

		sourceMapSupport.install();
	}
} else if (isCCS()) {
	sourceMapSupport.install({
		handleUncaughtExceptions: false,
		retrieveSourceMap: (path) => {

			// Same as NW case, but using the eclipse API instead

			if (_.endsWith(path, ".js")) {
				let mapFile = `${_.replace(path, "file:///", "")}.map`; // our map file
				if (!eclipseFileExists(mapFile)) {
					mapFile = path + ".map";	// meta-content map file?
				}
				if (eclipseFileExists(mapFile)) {
					return {
						url: null,
						map: eclipseGetFileContents(mapFile),
					};
				}
			}
			return null;
		},
	});
}

// else isCloud
// We don't want to enable it on the cloud as the map file is 7 megs in size (and growing)
// In theory, you can install with defaults, it will detect it's a browser, and will just work.
