import * as _ from "lodash";
import { FormattableObjects, IFormatter, FormatOptions } from "./formattingTypes";
import { FormattedMsgPart, FormattedMsg } from "./link";
import { abortOnError } from "../solver/debug";

export interface FormattersMap {

	set(obj: FormattableObjects, formatter: (options: FormatOptions, member?: string) => FormattedMsgPart): number;

	delete(obj: FormattableObjects): void;

	getEncodingTag(obj: FormattableObjects, member?: string, throwOnError?: boolean): string;

	getFormatter(options: FormatOptions): IFormatter;

	// Really only exists for testing

	verifySize(): number;

	clear(): void;
}

export function createFormattersMap(): FormattersMap {
	return new FormattersMapImpl();
}

export function getErrorFormatter(): IFormatter {
	const messageFormatter = (message: string) => {
		return new FormattedMsg(_.chain(message)
			.words(splitWords) // separate the msg into parts with an encoded sequence from the rest
			.map((word) => {
				const regexResult = matchEncoding.exec(word);
				if (regexResult) {
					throw new Error("Error formatter detected @@@");
				} else {
					return word;
				}
			})
			.value());
	};

	return (messageOrObj: string | FormattableObjects, member?: string) => {
		if (typeof messageOrObj === "string") {
			return messageFormatter(messageOrObj);
		} else {
			// this will always throw since we need to encode the member anyway
			throw new Error(member + " cannot be passed to error formatter");
		}
	};
}

// A three character sequence very unlikely to appear in a message normally
// Hindsight is 20-20, and we should have used an unprintable ascii character here, but we now use this pattern in the 
// legacy scripts suppressing error messages, so we can't change this without updating that syntax

const escapeSequence = "@@@";

// Regex to match an encoded sequence (@@@number.optionalString@@@), or something else (anything that's not @@@)
// Note that we can't be greedy on the optional string, as if the full error has two encoded errors, it will greedily 
// eat up to the next sequence.  
// ie: start_@@@3.SDA@@@_middle_@@@3.@@@_end should match [start_, @@@3.SDA@@@, _middle_, @@@3.@@@, _end] and not
// [start_, @@@3.SDA@@@_middle_@@@3.@@@, _end]
// However, we match @@@+ to ensure that if the member ended with @, we capture the whole member

const splitWords = new RegExp(`${escapeSequence}\\d+\\..*?${escapeSequence}+|[^${escapeSequence}]+`, "g");

// Regex to extract the number/string value from an encoded sequence
// Note that this time we do greedily match the string as we know there's not a second encoded sequence and we want to
// match any @'s in the member
// ie: @@@3.SDA@@@@ should match [3, SDA@]

const matchEncoding = new RegExp(`${escapeSequence}(\\d+)\\.(.*)${escapeSequence}`);

class FormattersMapImpl implements FormattersMap {

	private objectToId = new Map<FormattableObjects, number>();
	private idToFormatter: {
		[key: number]: (options: FormatOptions, member?: string) => FormattedMsgPart; // Type of obj is checked in "set" 
	} = {};
	private currentIndex = 0;

	public set(obj: FormattableObjects, formatter: (options: FormatOptions, member?: string) => FormattedMsgPart) {
		const id = this.currentIndex++;
		this.objectToId.set(obj, id);
		this.idToFormatter[id] = formatter;
		return id;
	}

	public delete(obj: FormattableObjects) {
		if (this.objectToId.has(obj)) {
			const id = this.objectToId.get(obj);
			this.objectToId.delete(obj);
			delete this.idToFormatter[id];
		}
	}

	public getEncodingTag(obj: FormattableObjects, member = "", throwOnError = abortOnError()) {
		if (this.objectToId.has(obj)) {
			return `${escapeSequence}${this.objectToId.get(obj)}.${member}${escapeSequence}`;
		}

		// throwOnError is set when called by the meta-code, or when abortOnError is set (during
		// testing).  This allows us to throw and fail hard during testing/development only.

		// Because react processes rendering in a queue, it's quite possible for a react component
		// to pass a stale object, and we don't want to treat that as a failure

		if (throwOnError) {
			throw new Error("Unknown object passed to getEncodingTag");
		}
		return "unknown object";
	}

	public getFormatter(options: FormatOptions): IFormatter {
		const messageFormatter = (message: string) => {
			return new FormattedMsg(_.chain(message)
				.words(splitWords) // separate the msg into parts with an encoded sequence from the rest
				.map((word) => {
					const regexResult = matchEncoding.exec(word);
					if (regexResult) {
						const encodedId = Number(regexResult[1]);
						const member = regexResult[2];
						const formatter = this.idToFormatter[encodedId];
						if (formatter) {
							return formatter(options, member);
						} else {
							throw new Error("<unknown object>");
						}
					} else {
						return word;
					}
				})
				.value());
		};

		return (messageOrObj: string | FormattableObjects, member?: string) => {
			if (typeof messageOrObj === "string") {
				return messageFormatter(messageOrObj);
			} else {
				return messageFormatter(this.getEncodingTag(messageOrObj, member));
			}
		};
	}

	// Really only exists for testing

	public verifySize() {
		if (_.size(this.idToFormatter) !== this.objectToId.size) {
			throw new Error("Size mismatch in internal objects");
		}
		return this.objectToId.size;
	}

	public clear() {
		this.idToFormatter = {};
		this.objectToId.clear();
	}
}
