import * as _ from "lodash";
import { ITreeNodeStatus, ITreeNode } from "../../components/TreeNode";
import { IMyListItem } from "../IMyListItem";
import { SelectionInNode } from "../../components/actions/selection";
import { RuntimeInstance } from "public/runtime";
import { TreeNodeStatus } from "./treeStatus";
import { TreeNodeStatusType } from "../treeNodeStatusType";
import { Validations, ValidationSummary } from "../objectManagers/validations";
import { Tab } from "../tabs";
import { ButtonDisplay } from "../treeNodeButtonDisplay";
import { TreeCategory } from "public/defs";
import { naturalSort } from "../utils";

// Takes a categorized list of nav items and create tree entries from it
export class CategoryNode implements ITreeNode {

	private status: TreeNodeStatus;
	private children: ITreeNode[];
	private readonly treeNodePath: string[];
	private parentTab: Tab = null;
	private readonly category: string;
	private readonly description: string;
	private readonly alreadySorted;
	private expanded;

	constructor(
		private readonly id: string,
		category: Omit<TreeCategory, "entries" | "categories">,
		private readonly parentNode: ITreeNode,
	) {
		this.category = category.displayName;
		this.description = category.description ?? category.displayName;
		this.alreadySorted = category.alreadySorted ?? false;
		this.expanded = category.expanded ?? true;
		this.status = new TreeNodeStatus(TreeNodeStatusType.BADGE, this.id + "badge");
		this.treeNodePath = parentNode ? [...parentNode.getNodePath(), this.id] : [this.id];
	}

	public supportsOutputMenuDocking() {
		return false;
	}

	public getUIHash(): string {

		// Who knows if our children need to refresh, so return undefined to always refresh

		return undefined;
	}

	public setChildren(children: ITreeNode[]) {
		if (!this.alreadySorted) {
			const [categories, nodes] = _.partition(children, (m) => m instanceof CategoryNode);
			this.children = [...naturalSort(nodes, (m) => m.getDisplayName(true).toLowerCase()), ...categories];
		} else {
			this.children = children;
		}
	}

	public getInstances(): IMyListItem[] {
		// just a category node
		return [];
	}

	public getID() {
		return this.id;
	}

	public getDisplayName() {
		return this.category;
	}

	public getChildren(): ITreeNode[] {
		return this.children;
	}

	public isTitle() {
		return true;
	}

	public getTooltip() {
		return this.description;
	}

	public getStatus(validations: Validations): ITreeNodeStatus[] {
		if (!this.expanded) {
			const summary = validations.getSummary(this);
			const error = summary === ValidationSummary.Error;
			const warning = summary === ValidationSummary.Warning;
			this.status.setStatus({
				error,
				warning,
				success: false,
			});
			return [this.status];
		}
		return [];
	}

	public isExpanded() {
		return this.expanded;
	}

	public toggleExpanded() {
		this.expanded = !this.expanded;
	}

	public isDisabled() {
		return false;
	}

	public showButton() {
		// If our children might show buttons, then we should reserve some padding ourself too, even
		// though we'll never have one

		return _.first(this.children)?.showButton() !== ButtonDisplay.Remove ? ButtonDisplay.Hide : ButtonDisplay.Remove;
	}

	public getSelectedMyListItem(): IMyListItem {
		return null;
	}

	public setShowUserLongDescPref(_status: boolean) {
	}

	public getAlwaysShowUserLongDesc() {
		return false;
	}

	public getSelection(): SelectionInNode {
		return null;
	}

	public setSelection(_sel: SelectionInNode) {
	}

	public getNodePath() {
		return this.treeNodePath;
	}

	public getParentNode() {
		return this.parentNode;
	}

	public getParentTab() {
		return this.parentTab;
	}

	public setParentTab(tab: Tab) {
		this.parentTab = tab;
	}

	public getUsedPins() {
		const selectedItem = this.getSelectedMyListItem();
		return selectedItem ? selectedItem.getUsedPins() : new Set<string>();
	}

	public getRuntimeSelection(): RuntimeInstance {
		return null;
	}

	public isGraphableNonTopMgr() {
		return false;
	}
}
