import { FormattersMap } from "./formattersMap";
import { ILinkActions } from "../../components/actions/ILinkActions";
import { ResourceConflictText } from "../utils";

function toFormattedMsg(text: string, action: (actions: ILinkActions) => void) {
	return {
		baseText: text,
		linkAction: action,
	};
}

export function registerConstantFormatter(map: FormattersMap) {
	map.set(ResourceConflictText.ON_HARDWARE,
		() => toFormattedMsg("Using a custom board?",
			(actions) => actions.useCustomBoard()),
	);
	map.set(ResourceConflictText.UNPINNED,
		() => toFormattedMsg("Using a custom board?",
			(actions) => actions.useCustomBoard()),
	);
}
