module.exports = {
	isNode,
	isCCS,
	isTheia,
	isNodeWebkit,
	isNodejs,
	isCloud,
	isUnderTest,
	isWin,
	getOS,
	getProcess,
	enableTest,
	isLinux,
	isEmbedded,
};

// node-like - either node webkit (standalone ui) or nodejs (command line)
function isNode() {
	return typeof require !== "undefined";
}

// jxbrowser in Eclipse or electron in Theia
// It looks for window.eclipseIsEclipse as Theia injects the same elements to make itself appear to be eclipse, in 
// order to allow older versions of SysConfig to be used too.
function isCCS() {
	return typeof window !== "undefined" && !!window.eclipseIsEclipse;
}

// Running in Theia (electron)
function isTheia() {
	return isCCS() && typeof window.top.theia !== "undefined";
}

// standalone desktop ui
function isNodeWebkit() {
	return isNode() && typeof nw !== "undefined";
}

// command line
function isNodejs() {
	return isNode() && !isNodeWebkit();
}

// cloud (dev.ti.com)
function isCloud() {
	return !isNode() && !isCCS();
}

const isEmbedJs = isNodejs()
	? false
	: document.currentScript.getAttribute("src").endsWith("embed.js");

// Running as an embedded application within a UI
// False when running under nodejs
function isEmbedded() {
	return isEmbedJs;
}

let TEST_ENABLED = false;
function enableTest() {
	TEST_ENABLED = true;
}

function isUnderTest() {
	return (isNode() && !!process.env.PINMUX_TEST_ENABLED) || TEST_ENABLED;
}

function getOS() {
	if (typeof process !== "undefined") {
		if (/^win/.test(process.platform)) {
			return "win"
		}
		if (/^linux/.test(process.platform)) {
			return "linux";
		}
		if (/^darwin/.test(process.platform)) {
			return "mac";
		}
		throw new Error("Unknown OS");
	} else {
		// default to linux because it is not always possible to tell it from
		// the appVersion
		if (navigator.appVersion.indexOf("Win") !== -1) {
			return "win";
		}
		if (navigator.appVersion.indexOf("Mac") !== -1) {
			return "mac"
		}
		return "linux";
	}
}

function isWin() {
	return "win" === getOS();
}

function isLinux() {
	return "linux" === getOS();
}

/**
 * While this REALLY returns typeof process only in the node case, we fake it out as always 
 * returning process since most use of it is in tests/cli.  Ideally, we'd find a way to assert that
 * it's only called from node, but we don't have that capability yet.
 * 
 * Note that the below line is the way of doing a typescript cast for javascript code
 * @returns {typeof process}
 */
function getProcess() {
	if (isNode()) {
		return process;
	} else if (isCCS()) {
		return {
			cwd: () => eclipseEnv.CWD,
		};
	} else {
		// cloud
		return {
			cwd: () => "/",
		}
	}
}
