import * as _ from "lodash";
import * as path from "path";
import type * as FSExtraForType from "fs-extra";

import { convertUnknownToError, parseJSON, toLinuxPath } from "./utils";
import { http, HttpError } from "./http";
import { isNode, isCCS } from "./platform";
import { fs as fileSystem } from "./fileSystem";

interface Response {
	path: string;
}

interface LoadResponse<T> {
	data: T;
}

interface OpenResponse<T> extends LoadResponse<T> {
	path: string;
}

export interface IStorageFile {
	name: string;
	path: string;
	relativePath: string;
	size?: number;
	mtime?: number;
	isDirectory: boolean;
	children?: IStorageFile[];
	expanded?: boolean;
}

interface Storage {
	saveFile(filePath: string, data: any): Promise<Response>;
	openFile(filePath: string): Promise<OpenResponse<string>>;
	deleteFile(myFilename: string): Promise<void>;
	readDirectory(filePath: string, recursive?: string): Promise<IStorageFile[]>;
	formatPathForUser(folder: string): string;
	formatPathFromUser(folder: string): string;
	getRootPaths(): { path: string, displayName: string }[];
}

export function flattenStorageFile(file: IStorageFile): IStorageFile[] {
	return [file, ..._.flatMap(file.children, (c) => flattenStorageFile(c))];
}

class NWStorage implements Storage {

	private fs: typeof FSExtraForType = require("fs-extra");

	public async saveFile(filePath: string, data: any) {
		await this.fs.writeFile(filePath, data);
		const response: Response = {
			path: filePath,
		};
		return response;
	}

	public async openFile(filePath: string) {
		const data = await this.fs.readFile(filePath, "utf-8");
		const response: OpenResponse<string> = {
			path: filePath,
			data,
		};
		return response;
	}

	public async deleteFile(myFilename: string) {
		await this.fs.unlink(myFilename);
	}

	public async readDirectory(filePath: string, recursive?: string): Promise<IStorageFile[]> {
		const children = await this.fs.readdir(filePath);
		const results = _.map(children, async (childName) => {
			const childPath = path.join(filePath, childName);
			const childStats = this.fs.statSync(childPath);
			const childIsDirectory = childStats.isDirectory();
			const childChildren = (childIsDirectory && recursive) ? await this.readDirectory(childPath, recursive) : undefined;
			return {
				name: childName,
				path: childPath,
				relativePath: recursive ? toLinuxPath(path.relative(recursive, childPath)) : toLinuxPath(childPath),
				size: !childIsDirectory ? childStats.size : undefined,
				mtime: childStats.mtime.getTime(),
				isDirectory: childIsDirectory,
				children: childChildren,
			};
		});
		return Promise.all(results);
	}

	public getRootPaths() {
		return [{ path: fileSystem.cwd(), displayName: "/" }];
	}

	public formatPathForUser(folder: string) {
		return folder;
	}

	public formatPathFromUser(folder: string) {
		return folder;
	}
}

const workspaceServer = "/workspaceserver/";
export const syscfgWorkspace = "/pinmux/default/";
const ideWorkspace = "/ide/default/";

class CloudStorage implements Storage {

	public async saveFile(filePath: string, myFiledata: any) {
		await http.put(path.join(workspaceServer, filePath), myFiledata, "application/text");
		return { path: filePath };
	}

	public async openFile(filePath: string) {
		try {
			const data = await http.get(path.join(workspaceServer, filePath));
			return {
				path: filePath,
				data,
			};
		} catch (e) {
			if (e instanceof HttpError) {
				if (404 === e.response) {
					const fileName = path.basename(filePath);
					throw new Error(`File "${fileName}" does not exist`);
				}
			}
			throw new Error(`Failed to load ${filePath}: ${convertUnknownToError(e)}`);
		}
	}

	public deleteFile(myFilename: string) {
		return http.delete(workspaceServer + myFilename);
	}

	public async readDirectory(filePath: string, recursive?: string): Promise<IStorageFile[]> {
		const jsonResult = await http.get(path.join(workspaceServer, filePath) + "?command=list");
		const results = _.map(parseJSON<IStorageFile[]>(jsonResult), async (child): Promise<IStorageFile> => {
			const childPath = path.join(filePath, child.name);
			const childChildren = (child.isDirectory && recursive) ? await this.readDirectory(childPath, recursive) : undefined;
			return {
				path: childPath,
				relativePath: recursive ? path.relative(recursive, childPath) : childPath,
				children: childChildren,
				mtime: child.mtime,
				name: child.name,
				isDirectory: child.isDirectory,
				size: !child.isDirectory ? child.size : undefined,
			};
		});
		return Promise.all(results);
	}

	public formatPathForUser(folder: string) {
		return _.chain(folder)
			.replace(_.trimEnd(syscfgWorkspace, "/"), "/syscfg")	// hide the "default" part of the workspace server path
			.replace(_.trimEnd(ideWorkspace, "/"), "/ide") 			// hide the "default" part of the workspace server path
			.trimEnd("/")											// remove the trailing /
			.value();
	}

	public formatPathFromUser(folder: string) {
		if (folder === "/syscfg") {
			return _.trimEnd(syscfgWorkspace, "/");
		} else if (folder === "/ide") {
			return _.trimEnd(ideWorkspace, "/");
		} else if (_.startsWith(folder, "/syscfg/")) {
			return _.replace(folder, "/syscfg/", syscfgWorkspace);
		} else if (_.startsWith(folder, "/ide/")) {
			return _.replace(folder, "/ide/", ideWorkspace);
		} else if (!folder) {
			return folder;
		} else {
			throw new Error("Unknown root folder specified");
		}
	}

	public getRootPaths() {
		return [
			{
				path: syscfgWorkspace,
				displayName: "syscfg",
			}, {
				path: ideWorkspace,
				displayName: "ide",
			},
		];
	}
}

class EclipseStorage implements Storage {

	private readonly eclipseRoot = path.resolve(fileSystem.cwd(), "..");

	// eslint-disable-next-line @typescript-eslint/require-await
	public async openFile(filePath: string) {

		// check and throw, this is consistent with the APIs for other platforms
		// also eclipse expects us to not call with a non existent path. However,
		// eclipse can't throw in such cases, so they return null and log an error
		// to the eclipse log.

		if (!eclipseFileExists(filePath)) {
			throw new Error(`No such file: ${filePath}`);
		}

		const response: OpenResponse<string> = {
			path: filePath,
			data: eclipseGetFileContents(filePath),
		};
		return response;
	}

	// eslint-disable-next-line @typescript-eslint/require-await
	public async saveFile(filePath: string, myFiledata: any) {
		eclipsePutFileContents(filePath, myFiledata);
		const response: Response = { path: filePath };
		return response;
	}

	// eslint-disable-next-line @typescript-eslint/require-await
	public async deleteFile(myFilename: string) {
		eclipseRm(myFilename);
	}

	public async readDirectory(filePath: string, recursive?: string): Promise<IStorageFile[]> {
		const json = eclipseGetDirContents(filePath);
		const dirInfo = parseJSON<IEclipseFileInfo[]>(json);
		const results = _.map(dirInfo, async (child) => {
			const childPath = path.join(filePath, child.name);
			const childChildren = (child.isDirectory && recursive) ? await this.readDirectory(childPath, recursive) : undefined;
			return {
				name: child.name,
				path: childPath,
				relativePath: recursive ? path.relative(recursive, childPath) : childPath,
				size: !child.isDirectory ? child.size : undefined,
				mtime: child.lastModified,
				isDirectory: child.isDirectory,
				children: childChildren,
			};
		});
		return Promise.all(results);
	}

	public getRootPaths() {
		return [{ path: this.eclipseRoot, displayName: "/" }];
	}

	public formatPathForUser(folder: string) {
		return folder;
	}

	public formatPathFromUser(folder: string) {
		return folder;
	}
}

export const storage = isNode() ? new NWStorage() : isCCS() ? new EclipseStorage() : new CloudStorage();
