import * as _ from "lodash";
import { FormattersMap } from "../formatting/formattersMap";
import { AnyMemberMgr, SetSource, isUserChange } from "./member";
import { assignmentToString } from "../niceExceptions";
import { createMemberValueAssignmentStatement } from "../scripting/serialize";
import { AObjectMgr } from "./object";
import { RuntimeObject } from "public/runtime";

// When serializing an invalid assignment, we want to preserve the reason it was invalid.  This is a
// function that hangs off of 'scripting' that allows one to indicate the value and suspected reason
// that an assignment is invalid.  The serialization code will generate calls to this so that reasons
// persist across serialization boundaries.

export function invalidAssignment<T>(value: T, reason: string, memberPath?: string[], oldDisplayName?: string) {
	return new InvalidAssignmentWrapper(value, reason, memberPath, oldDisplayName);
}

export class InvalidAssignmentWrapper<T> {
	constructor(public readonly val: T, public readonly reason: string,
		public readonly memberPath: string[] = [], public readonly oldDisplayName?: string) { }
}

export const enum InvalidAssignmentReason {
	BACKWARDS_COMPATIBILITY = "a backwards compatibility discrepancy",
	TARGET_MIGRATION = "a difference in the board or device",
}

// Capture invalid assignments while executing 'func', and assume the reason they are invalid
// is 'defaultReason' (unless explicitly indicated otherwise)

export async function capture<T>(defaultReason: InvalidAssignmentReason, func: () => Promise<T>) {
	try {
		invalidModules = [];
		rejectWith = defaultReason;
		return {
			result: await func(),
			invalidModules,
		};
	} finally {
		rejectWith = null;
	}
}

export function captureSync<T>(defaultReason: InvalidAssignmentReason, func: () => T) {
	try {
		invalidModules = [];
		rejectWith = defaultReason;
		return {
			result: func(),
			invalidModules,
		};
	} finally {
		rejectWith = null;
	}
}

// Return true if we are currently trying to capture invalid assignments of any type

export function shouldCapture(source: SetSource, reasonProvided: boolean, memberKeyValid = true) {

	// Don't capture if there's no reason, either default or explicit
	return (null !== rejectWith || reasonProvided) &&

		// Only capture user changes - meta-content changes indicate a bug and should 
		// always throw
		isUserChange(source) &&

		// Only capture invalid member accesses when explicitly doing target migration.
		// The reason is that to capture this type of invalid access, the proxy must be
		// changed to return a fake proxy for the missing member in order to capture the
		// final assignment.  That changes accesses to invalid members to return that
		// fake proxy vs undefined, and that changes "if(inst.key)"" to return true, 
		// which completely changes the meaning of the script.  As such, we ONLY want 
		// that turned on explicitly
		(memberKeyValid || rejectWith === InvalidAssignmentReason.TARGET_MIGRATION);
}

let rejectWith: InvalidAssignmentReason = null;

// Represents an invalid assignment to any member.  Created by the member to track 
// the invalid assignment going forward.

export class InvalidAssignment {

	constructor(
		private readonly value: any,
		private readonly configurable: AnyMemberMgr,
		private readonly formattersMap: FormattersMap,
		private readonly reason: string = rejectWith,
		private readonly oldDisplayName: string = null) {
		this.formattersMap.set(this, () => {
			return {
				baseText: "accepting",
				linkAction: (actions) => actions.clearInvalidAssignment(configurable),
			};
		});
	}

	public getScriptStatements(parentIdentifier: string) {
		return [
			createMemberValueAssignmentStatement(
				this.configurable.def,
				parentIdentifier,
				JSON.stringify(this.value),
				{ shouldQuoteStrings: false, invalidAssignment: this.reason, oldDisplayName: this.oldDisplayName }),
		];
	}

	public getError() {
		const accepting = this.formattersMap.getEncodingTag(this);
		return `An attempt to set this to the invalid value ${assignmentToString(this.oldDisplayName ?? this.value)} was blocked.  ` +
			`This is most likely due to ${this.reason}.  ` +
			`You can dismiss this error by either ${accepting} the current value, or changing it to another one.`;
	}

	public remove() {
		this.formattersMap.delete(this);
	}
}

// Indicates an assignment to a member that doesn't exist.  Created by an object manager for which the member
// access was attempted on.

export class InvalidMemberAccess {

	constructor(
		private readonly value: any,
		instance: AObjectMgr<RuntimeObject>,
		private readonly memberPath: string[],
		private readonly formattersMap: FormattersMap,
		public readonly reason: string = rejectWith,
		public readonly cfgDisplayName: string = _.last(memberPath)) {
		this.formattersMap.set(this, () => {
			return {
				baseText: "here",
				linkAction: (actions) => actions.clearInvalidMemberAccess(instance),
			};
		});
	}

	public getScriptStatements(parentIdentifier: string) {

		// Now generate an assignment to this invalid access that records the reason

		return [
			createMemberValueAssignmentStatement(
				{
					name: _.first(this.memberPath),
				},
				parentIdentifier,
				JSON.stringify(this.value),
				{
					shouldQuoteStrings: false,
					invalidAssignment: this.reason,
					memberPath: _.drop(this.memberPath),
				}),
		];
	}

	public getError() {
		return `An attempt was made to change the setting '${this.cfgDisplayName}' which does not exist. `;
	}

	public getClickHereMsg() {
		const here = this.formattersMap.getEncodingTag(this);
		return `Click ${here} to acknowledge and dismiss this error.`;
	}

	public getReasonMsg() {
		return `This is most likely due to ${this.reason}.  `;
	}

	public remove() {
		this.formattersMap.delete(this);
	}
}

export class InvalidPortAccess extends InvalidMemberAccess {
	public override getError() {
		return this.reason + ". ";
	}

	public override getReasonMsg() {
		return "";
	}
}

// Indicates a module was accessed that doesn't exist any more

let invalidModules: string[] = [];
export function invalidModuleAccessed(name: string) {
	invalidModules.push(name);
}
