import { Simulation } from "public/defs";
import { RuntimeInstance } from "public/runtime";
import { SelectionInNode } from "../../components/actions/selection";
import { ITreeNode, ITreeNodeStatus } from "../../components/TreeNode";
import { getConfigurationChangeNumber } from "../changeNumber";
import { IMyListItem } from "../IMyListItem";
import { Tab } from "../tabs";
import { ButtonDisplay } from "../treeNodeButtonDisplay";

export interface SimulationEntry {
	simulation: Simulation;
	productPath: string;
}

// In the future, we may have multiple products, each contributing different simulations.  Or we may have multiple 
// simulation types in just one product.  When that happens, this class would need to represent one of those specific 
// simulations that is picked in the first column.  For now, most of this code is simply to provide dummy values so 
// that code that expects there to always be a selected node is happy

export class SimulationTreeNode implements ITreeNode {
	constructor(
		public readonly def: SimulationEntry,
	) { }

	public getID(): string {
		return this.def.simulation.name;
	}

	public getDisplayName(): string {
		return this.def.simulation.displayName;
	}

	public getChildren(): ITreeNode[] {
		return [];
	}

	public isTitle(): boolean {
		return false;
	}

	public getTooltip(): string {
		return this.def.simulation.description;
	}

	public getStatus(): ITreeNodeStatus[] {
		return [];
	}

	public isExpanded(): boolean {
		return false;
	}

	public toggleExpanded(): void {
	}

	public isDisabled(): boolean {
		return false;
	}

	public setShowUserLongDescPref() {
	}

	public showButton(): ButtonDisplay {
		return ButtonDisplay.Show;
	}

	public getAlwaysShowUserLongDesc(): boolean {
		return false;
	}

	public getSelection(): SelectionInNode {
		return {
			instanceId: "dummy id",
			memberPath: [],
		};
	}

	public setSelection() {
	}

	public getNodePath(): string[] {
		return [this.getID()];
	}

	public getSelectedMyListItem(): IMyListItem {
		return null;
	}

	public getInstances(): IMyListItem[] {
		return [];
	}

	public getUsedPins(): Set<string> {
		return new Set<string>();
	}

	public getRuntimeSelection(): RuntimeInstance {
		return null;
	}

	public getParentNode(): ITreeNode {
		return null;
	}

	public getParentTab(): Tab {
		return null;
	}

	public supportsOutputMenuDocking(): boolean {
		return false;
	}

	public getUIHash(): string {
		return getConfigurationChangeNumber().toString();
	}

	public isGraphableNonTopMgr() {
		return false;
	}
}
