import * as _ from "lodash";
import { Connection, Port } from "clockTree";
import { ClockTreeEntry } from "public/defs";
import { assertUnreachable } from "../../../services/utils";

// Based on the connectivity, find all instances that feed into the passed in instances

function fanIn(connectivity: Connection[], instanceNames: string[]) {
	return _.uniq(fan(
		connectivity,
		instanceNames,
		(connection) => connection.targets,
		(connection) => [connection.source],
	));
}

// Based on the connectivity, find all instances that feed out from passed in instances

function fanOut(connectivity: Connection[], instanceNames: string[]) {
	return _.uniq(fan(
		connectivity,
		instanceNames,
		(connection) => [connection.source],
		(connection) => connection.targets,
	));
}

// Combination of fanIn and fanOut above

function fanInAndOut(connectivity: Connection[], instanceNames: string[]) {
	return _.uniq([
		...fanIn(connectivity, instanceNames),
		...fanOut(connectivity, instanceNames),
	]);
}

// Everything that leaves one node and goes to another.  
// Unlike other algorithms, it assumes that the instanceNames are related and ordered like 
// [source, sink, source2, sink2, ...]

function everythingBetween(connectivity: Connection[], instanceNames: string[]) {
	if (_.size(instanceNames) % 2) {
		throw new Error("The algorithm 'everythingBetween' requires an even number of ip instances");
	}

	return _.chain(instanceNames)
		.chunk(2)
		.flatMap(([source, sink]) => {
			const leavingSource = fanOut(connectivity, [source]);
			const enteringSink = fanIn(connectivity, [sink]);
			return _.intersection(leavingSource, enteringSink);
		})
		.uniq()
		.value();
}

function explicitlyNamedInstances(_connectivity: Connection[], instanceNames: string[]) {
	return instanceNames;
}

export function getAlgorithm({ algorithm }: Pick<ClockTreeEntry, "algorithm">) {
	if (algorithm) {
		switch (algorithm) {
			case "fanIn": return fanIn;
			case "fanOut": return fanOut;
			case "fanInAndOut": return fanInAndOut;
			case "everythingBetween": return everythingBetween;
			default: assertUnreachable(algorithm);
		}
	}
	return explicitlyNamedInstances;
}

function fan(
	connectivity: Connection[],
	instanceNames: string[],
	nextLevel: (connection: Connection) => Port[],
	currentLevel: (connection: Connection) => Port[],
) {
	let instancesAtCurrentLevel = instanceNames;
	let releventInstances = instanceNames;
	let foundConnections: Connection[] = [];
	while (!_.isEmpty(instancesAtCurrentLevel)) {

		// Find all connections that map to/from the current level

		const newConnections = _.chain(connectivity)
			.filter((c) => _.some(nextLevel(c), (s) => _.includes(instancesAtCurrentLevel, s.instName)))
			.reject((c) => _.includes(foundConnections, c)) // exclude loops
			.value();

		// Extract the names of the instances at this level

		instancesAtCurrentLevel = _.chain(newConnections)
			.flatMap(currentLevel)
			.map((t) => t.instName)
			.value();

		// Update what we've found and iterate

		releventInstances = [
			...releventInstances,
			...instancesAtCurrentLevel,
		];
		foundConnections = [
			...foundConnections,
			...newConnections,
		];
	}
	return releventInstances;
}
