import * as _ from "lodash";
import { ScriptAndProductLoader } from "../resources/otherLoaders/scriptAndProductLoader";
import { IAvailableProducts } from "../product/available";
import { ParsedArgs, ArgsError, MissingArgsError, ResolvedArgs, Script, systemContext, defaultRTOS } from "./argTypes";
import { parseArgs, applyDefaults } from "./parseArgs";
import { resolveScriptArg } from "./resolveScriptArg";
import { resolveProducts } from "./resolveProductArgs";
import { resolveTarget } from "./resolveTargetArgs";
import { getDisplayName, inParallelNoCleanup } from "../utils";
import { Product } from "../product/types";
import { getDefaultContext } from "../contexts";

/**
 * Construct an args map from a argv array passing in on the CLI.
 * @param argv - args array passed in via a CLI interface.
 * @returns formatted and validated args.
 */
export async function parseAndResolveArgs(
	argv: string[], loader: ScriptAndProductLoader, knownProducts: IAvailableProducts): Promise<ResolvedArgs> {

	// Parse the command line arguments, and then resolve any args supplied by the script

	const initialParsedArgs = checkForErrors(parseArgs(argv, true));
	let parsedArgs = await resolveScriptArg(initialParsedArgs, loader);

	// Begin loading dependent scripts, but await on the results at the end (parallelism)

	const dependentScriptsPromise = inParallelNoCleanup(loadDependentScripts(parsedArgs, loader));

	// Do some initial validation, then apply defaults

	validateArgs(parsedArgs);
	parsedArgs = applyDefaults(parsedArgs);
	_.each(parsedArgs.script, (scriptArgs) => {
		if (scriptArgs.output) {
			scriptArgs.output.value = loader.resolve(scriptArgs.output.value);
		}
	});

	// Resolve the products before resolving the target (as we can't load the board file without
	// knowing the products)

	const products = await resolveProducts(parsedArgs, loader, knownProducts);
	const loadSOCMetaData = _.isEmpty(parsedArgs.product) && !_.some(products, (product) => product.file.isBuiltIn);
	const deviceInfo = await resolveTarget(products, parsedArgs);

	// One final validation

	validateFinalArgs(parsedArgs, products);

	// Return the fully resolved arguments

	return {
		theme: parsedArgs.theme.value,
		treatWarningsAsErrors: parsedArgs.treatWarningsAsErrors.value,
		listGeneratedFiles: parsedArgs.listGeneratedFiles.value,
		listReferencedFiles: parsedArgs.listReferencedFiles.value,
		compiler: parsedArgs.compiler.value,
		products,
		loadSOCMetaData,
		ccxxImageMode: parsedArgs.ccxxImageMode.value,
		showAllContexts: parsedArgs.showAllContexts.value,
		ipcf: parsedArgs.ipcf.value,
		showSaveIcons: parsedArgs.showSaveIcons.value,
		rtos: parsedArgs.rtos.value,
		script: _.zipWith(parsedArgs.script, await dependentScriptsPromise, (scriptArgs, dependentScripts) => ({
			script: scriptArgs.script,
			output: scriptArgs.output?.value,
			context: scriptArgs.context?.value ?? getDefaultContext(products, deviceInfo),
			argsForScript: scriptArgs.scriptArgs ? _.split(scriptArgs.scriptArgs.value, " ") : [],
			dependentScripts,
		})),
		quiet: parsedArgs.quiet.value,
		referenceDesign: parsedArgs.referenceDesign.value,
		...deviceInfo,
	};
}

function checkForErrors({ parsedArgs, argsError }: { parsedArgs: ParsedArgs, argsError?: ArgsError }) {
	if (argsError) {
		throw argsError;
	}
	return parsedArgs;
}

function loadDependentScripts(parsedArgs: ParsedArgs<Script>, loader: ScriptAndProductLoader) {
	return Promise.all(_.map(parsedArgs.script, (scriptArgs) => {
		return Promise.all(_.map(scriptArgs.dependentScript, async ({ value }) => {
			value = loader.resolve(value);
			return {
				path: value,
				contents: await loader.readScriptFile(value),
			};
		}));
	}));
}

function validateArgs(parsedArgs: ParsedArgs<Script>) {
	// The board data is specified in the product, so you can't have a board without a product

	if (!parsedArgs.product && parsedArgs.board) {
		throw new MissingArgsError("Cannot specify --board without --product");
	}

	// While the core info is specified in the device data, there seems little reason to specify a
	// core, and thus a context, if you're just doing raw pinmux.  By restricting this for now, it 
	// means less we have to test (like migration).

	if (!parsedArgs.product && _.some(parsedArgs.script, (scriptArgs) => scriptArgs.context)) {

		throw new MissingArgsError("Cannot specify --context without --product");
	}

	// 99.9% of the time we are targeting a device.  We've created an "Other" device for that rare
	// time we are doing generic configuration, but it makes more sense to have an error like the
	// below vs saying "Other" is not a valid device for this product much later

	if (!parsedArgs.board && !parsedArgs.device) {
		throw new MissingArgsError("Missing argument: --board or --device must be specified");
	}

	// Every script must belong to a unique context

	const noContextDuplicates = _.chain(parsedArgs.script)
		.groupBy((scriptArgs) => scriptArgs.context?.value || systemContext)
		.filter((group) => _.size(group) > 1)
		.isEmpty()
		.value();
	if (!noContextDuplicates) {
		throw new ArgsError("Every --script must be followed by a unique --context");
	}

	// Every script must be unique

	const noScriptDuplicates = _.chain(parsedArgs.script)
		.reject((scriptArgs) => !scriptArgs.script)
		.groupBy((scriptArgs) => scriptArgs.script.path)
		.filter((group) => _.size(group) > 1)
		.isEmpty()
		.value();
	if (!noScriptDuplicates) {
		throw new ArgsError("Every --script must be unique");
	}

	// --ipcf is iar only and should name a .ipcf file

	if (parsedArgs.ipcf && parsedArgs.compiler?.value !== "iar") {
		throw new ArgsError("Cannot specify --ipcf without also specifying --compiler iar");
	}

	if (parsedArgs.ipcf && !_.endsWith(parsedArgs.ipcf.value, ".ipcf")) {
		throw new ArgsError("--ipcf name must end with '.ipcf'");
	}
}

function validateFinalArgs(parsedArgs: ParsedArgs<Script>, products: Product[]) {
	const productsWithRtos = _.filter(products, (p) => !!p.file.rtos);
	if (_.isEmpty(productsWithRtos)) {
		if (parsedArgs.rtos.value !== defaultRTOS) {
			throw new ArgsError("--rtos not supported by any product");
		}
	} else {

		// The rtos value must be valid for every product that specifies a set of values

		const invalid = _.find(productsWithRtos, (p) => !_.includes(p.file.rtos, parsedArgs.rtos.value));
		if (invalid) {
			throw new ArgsError(`The product ${getDisplayName(invalid.file, false)} does not support --rtos ${parsedArgs.rtos.value}`);
		}
	}
}
