import * as _ from "lodash";
import { ModuleMgr } from "./instanceContainers/module";
import { InterfaceMgr, SomeInterfaceInstanceMgr } from "./instanceContainers/interface";
import { ModuleInstanceMgr } from "./objectManagers/moduleInstance";
import { ModuleInstance } from "public/runtime";
import { isValidCIdentifier } from "./utils";
import { InternalValidationLogger } from "./objectManagers/validations";

interface INavItemIMyListItemPair {
	mod: ModuleMgr | InterfaceMgr;
	myListItem: ModuleInstanceMgr<ModuleInstance> | SomeInterfaceInstanceMgr;
}

// Names only need to be unique per context, so the assumption here is all modules/interfaces from one context are 
// passed in here

export function validateNames(mods: (ModuleMgr | InterfaceMgr)[], corePinmux: boolean, validationLogger: InternalValidationLogger) {
	// find items with conflicting names
	// track the myListItem along with the container navItem, which
	// is needed to produce more useful error messages
	const nameToPairs: { [key: string]: INavItemIMyListItemPair[] } = {};
	_.each(mods, (mod) => {
		_.each<ModuleInstanceMgr<ModuleInstance> | SomeInterfaceInstanceMgr>(mod.getInstances(), (myListItem) => {

			const name = myListItem.getNameMgr().getValue();

			if (!nameToPairs[name]) {
				nameToPairs[name] = [];
			}

			nameToPairs[name].push({
				mod,
				myListItem,
			});
		});
	});

	// create/clear errors
	_.each(nameToPairs, (pairs, name) => {
		if (name === "") {
			_.each(pairs, (item) => {
				validationLogger.logError("Cannot be empty.", item.myListItem.getNameMgr());
			});
		} else if (!corePinmux && !isValidCIdentifier(name)) {
			_.each(pairs, (item) => {
				if (item.myListItem.getNameMgr().isCIdentifier()) {
					validationLogger.logError("Must be a valid C identifier", item.myListItem.getNameMgr());
				}
			});
		}
		if (pairs.length !== 1) {

			_.each(pairs, (currPair) => {
				// create error message referencing all
				// NavItems excluding ourselves
				const conflictingNavItemNames = _.chain(pairs)
					.filter((pair) => pair.myListItem !== currPair.myListItem)
					.map((pair) => pair.mod.getDisplayName(false))
					.uniq()
					.sortBy()
					.join(", ")
					.value();

				const instName = currPair.myListItem.getNameMgr().getValue();
				const errorMsg
					= `Duplicate name: '${instName}' also exists on instance(s) of ${conflictingNavItemNames}`;

				validationLogger.logError(errorMsg, currPair.myListItem.getNameMgr());

			});
		}
	});
}
