import { ButtonClickResult, NavigateToUrlConfigurable } from "public/defs";
import { getAnalytics } from "../../analytics";
import { openExternalLink } from "../../externalLink";
import { IModalService } from "../../IModalService";
import { disableScriptingForCallback } from "../../scripting/scriptingGuard";
import { StandardButtonConfigurableMgr } from "./standardButtonConfigurableMgr";

// This is a button configurable that is used to open a url in the system browser or another tab

export class NavigateToUrlConfigurableMgr extends StandardButtonConfigurableMgr<NavigateToUrlConfigurable> {

	public override async getClickResultImpl(
		productPath: string, modalService: IModalService, options: { filePath?: string }): Promise<ButtonClickResult> {
		const result = await super.getClickResultImpl(productPath, modalService, options);
		const url = disableScriptingForCallback(() => this.def.onNavigate(this.getParentRuntimeObj(), result));
		getAnalytics().recordExternalNavigate(url);
		openExternalLink(url);
		return result;
	}
}
