import * as _ from "lodash";
import { ClockTreeComponentEntry, FrequencyUnit, PinFrequency, PinFrequencyConfigurable } from "public/defs";
import { ConfigurableMgr } from "./configurableMgr";
import { FormattersMap } from "../../formatting/formattersMap";
import { AObjectMgr } from "../object";
import { ModuleInstance } from "public/runtime";
import { ConfigurableComponent } from "./configurableComponent";

export class PinFrequencyConfigurableMgr extends ConfigurableMgr<PinFrequency> {

	// This is a temporary used when calling getSignalPath().  It allows each configurable to append itself when it is
	// accessed so that we can determine what all feeds into the value of the frequency at any point.

	private static signalPath: PinFrequencyConfigurableMgr[] = null;

	// This returns an array of all the pins that the signals would flow through in order to reach the pins given.  
	// That can be used by the tool to indicate which pins are unused within a given graph

	public static getUsed(pins: PinFrequencyConfigurableMgr[]) {
		// Do not use cached values for dynamic configurables, because we want to any access to actually go through to 
		// the get() function

		return ConfigurableMgr.withoutDynamicConfigurableCaching(() => {

			// Now, set signalPath to a valid array.  This will be checked for in get() and appended with all the pins 
			// hit

			PinFrequencyConfigurableMgr.signalPath = [];

			// Invoke get() on each pin to start the process

			_.each(pins, (p) => p.get());

			// Now signalPath has the result, but we want to null it out prior to return so subsequent accesses don't 
			// update it

			const result = PinFrequencyConfigurableMgr.signalPath;
			PinFrequencyConfigurableMgr.signalPath = null;
			return result;
		});
	}
	public readonly ui = ConfigurableComponent.PinFrequencyConfigurable;
	constructor(parentObjectMgr: AObjectMgr<ModuleInstance>,
		formattersMap: FormattersMap,
		def: PinFrequencyConfigurable,
		private readonly frequencyFormat: FrequencyFormat,
	) {
		super(parentObjectMgr, formattersMap, def);
	}

	// Called by the tool to update the getter for an input pin.
	// Allows meta-content to override displayName/longDescription etc for an input pin, but
	// with the getter still determined by the tool

	public updateDefinition(getValue: PinFrequencyConfigurable["getValue"]) {
		this.def.getValue = getValue;
	}

	public getValueAsString() {
		let value = this.getValue();
		if (_.isArray(value)) {
			if (value[0] !== value[1]) {

				// Format both the high and low and return a string like "low - high"

				const low = this.format(value[0]);
				const high = this.format(value[1]);
				if (low.unit === high.unit) {
					return `${low.freq} - ${high.freq} ${low.unit}`;
				}
				return `${low.freq} ${low.unit} - ${high.freq} ${high.unit}`;
			} else {

				// Convert array to a single value, and fall through

				value = value[0];
			}
		}
		const { freq, unit } = this.format(value);
		return `${freq} ${unit}`;
	}

	public override get() {

		// If signalPath is a valid array, then include ourself in the path since we're now being accessed

		if (PinFrequencyConfigurableMgr.signalPath) {
			PinFrequencyConfigurableMgr.signalPath.push(this);
		}

		// Then do the default get() handling

		return super.get();
	}

	// This returns an array of all the pins that the signal would flow through in order to reach this pin.  That 
	// allows the tool to effectively highlight the path the frequency signal took along the diagram.  

	public getSignalPath() {

		// This is easiest to calculate by just getting the used ports when querying just ourself

		return PinFrequencyConfigurableMgr.getUsed([this]);
	}

	protected override validateValue(value: PinFrequency) {
		// Could be an array of two, or a single number

		if (_.isArray(value) ? !isValidArrayFrequency(value) : !_.isNumber(value)) {
			throw new Error(`${this.def.name}: expected [low, high] or number, got ${JSON.stringify(value)}`);
		}

		function isValidArrayFrequency(asArray: [number, number]) {
			return _.size(asArray) === 2 && _.isNumber(asArray[0]) && _.isNumber(asArray[1]) && asArray[0] <= asArray[1];
		}
	}

	private format(value: number) {
		return format(value, this.frequencyFormat);
	}
}

const units: FrequencyUnit[] = ["Hz", "kHz", "MHz", "GHz"];

export function format(freq: number, frequencyFormat: FrequencyFormat) {
	let unitIndex = _.indexOf(units, frequencyFormat.defaultUnit);
	while (freq >= 1000 && unitIndex < (_.size(units) - 1)) {
		++unitIndex;
		freq /= 1000;
	}
	while (freq < 1 && unitIndex > 0) {
		--unitIndex;
		freq *= 1000;
	}
	return {
		freq: freq.toPrecision(frequencyFormat.precision),
		unit: units[unitIndex],
	};
}

export type FrequencyFormat = Required<Pick<ClockTreeComponentEntry, "defaultUnit" | "precision">>;
