import * as _ from "lodash";
import { AdaptedDeviceInfo, DevicePin, Interface, InterfacePin, PeripheralPin } from "dataInterfaces";
import { Pin } from "./requirements";
import { PinMap } from "../pinMap";
import { freezeDeep } from "../utils";

export const enum Restrictive {
	"SOMETIMES",
	"ALWAYS",
}

export type PinRestrictions = Record<string, Restrictive>;
export type AvailablePins = Record<string, number>;

interface PinInfo {
	devicePin: DevicePin;
	peripheralPin: PeripheralPin;
	interfacePin: InterfacePin;
}

export interface OptimizablePinMap {
	[devicePinName: string]: PinInfo;
}

class Optimization {
	constructor(
		private readonly allPins: OptimizablePinMap,
		private readonly freePins: OptimizablePinMap,
		private readonly restrictionsMap: Map<InterfacePin, Restrictive>,
	) {

		// We freeze this as it is also exposed to the meta-content for backwards compatibility

		freezeDeep(this.allPins);
	}

	public getAllPins(): OptimizablePinMap {
		return this.allPins;
	}

	public getFreePins(): OptimizablePinMap {
		return this.freePins;
	}

	public restricts(pinReq: Pin): Restrictive {
		if (pinReq.connectedToHardware || _.isEmpty(pinReq.interfacePins) ||
			(pinReq.userOverride && !(pinReq.userOverride in this.freePins))) {
			return null;
		}

		if (_.every(pinReq.interfacePins, (pin) => this.restrictionsMap.get(pin) === Restrictive.ALWAYS)) {
			return Restrictive.ALWAYS;
		} else if (_.every(pinReq.interfacePins, (pin) => !this.restrictionsMap.has(pin))) {
			return null;
		}
		return Restrictive.SOMETIMES;
	}

	public getPinCount(): number {
		return _.size(this.freePins);
	}
}

export class Optimizations {

	private readonly map: Record<string, Optimization> = {};

	constructor(deviceData: AdaptedDeviceInfo, pinMap: PinMap) {
		const gpioOptimization = createSinglePinOptimization(deviceData.interfaces.GPIO, deviceData, pinMap);
		const aioOptimization = createSinglePinOptimization(deviceData.interfaces.AIO, deviceData, pinMap, gpioOptimization);
		if (gpioOptimization) {
			this.map.GPIO = gpioOptimization;
		}
		if (aioOptimization) {
			this.map.AIO = aioOptimization;
		}
	}

	public isOptimizable(interfaceName: string) {
		return interfaceName in this.map;
	}

	public getOptimizableInterfaces(): Record<string, string> {
		return _.mapValues(this.map, (_unused, key) => key);
	}

	public getAllPins(optimizableInterface: string): OptimizablePinMap {
		return this.map[optimizableInterface]?.getAllPins() ?? {};
	}

	public getFreePins(optimizableInterface: string): OptimizablePinMap {
		return this.map[optimizableInterface]?.getFreePins() ?? {};
	}

	public restrictions(pinReq: Pin): PinRestrictions {
		return _.chain(this.map)
			.mapValues((optimization) => optimization.restricts(pinReq))
			.omitBy((value) => value === null)
			.value();
	}

	public getPinCount(): AvailablePins {
		return _.mapValues(this.map, (o) => o.getPinCount());
	}
}

// If the interface has one pin per peripheral, and that pin has only one possible ball mapping, and that's unique 
// across all peripherals on this interface, then we can optimize how we solve for that interface.  We can ignore
// requirements for those pins and instead just pick whatever balls remain and use that to infer the peripheral/pin 
// solution

function createSinglePinOptimization(
	optimizableIFace: Interface | undefined, deviceData: AdaptedDeviceInfo, pinMap: PinMap, conflictingOptimization?: Optimization) {
	if (optimizableIFace) {

		// Collect pin information for every pin on this interface

		const allPins: OptimizablePinMap = {};
		_.each(optimizableIFace.peripherals, (peripheral) => {
			_.each(peripheral.peripheralPins, (peripheralPin) => {
				_.each(peripheralPin.pinMappings, (devicePin) => {
					allPins[devicePin.name] = {
						devicePin,
						peripheralPin,
						interfacePin: peripheralPin.interfacePin,
					};
				});
			});
		});

		// Technically we are able to optimize banks of pins, but historically we haven't, and doing
		// so now might cause issues with reading in saved pinmux files.  So for now, disable if that's
		// how the SOC data has been described.
		// Additionally if any of the pin choices are also used on another optimization, we cannot 
		//optimize this interface.

		if (1 === _.size(optimizableIFace.interfacePins)
			&& _.size(optimizableIFace.peripherals) === _.size(allPins) &&
			(!conflictingOptimization || _.every(_.keys(allPins), (pin) => !(pin in conflictingOptimization.getAllPins())))) {

			// For every interface pin on every other interface, determine if every possible choice of a pin would 
			// restrict choices on this interface, or if only some choices would, or if none would.

			const restrictionsMap = new Map<InterfacePin, Restrictive>();
			_.each(deviceData.interfaces, (iface) => {
				_.each(iface.interfacePins, (interfacePin) => {
					const always = _.every(interfacePin.pinMappings, (peripheralPin) =>
						_.every(peripheralPin.pinMappings, (devicePin) => devicePin.name in allPins));
					if (!always) {
						const sometimes = _.some(interfacePin.pinMappings, (peripheralPin) =>
							_.some(peripheralPin.pinMappings, (devicePin) => devicePin.name in allPins));
						if (sometimes) {
							restrictionsMap.set(interfacePin, Restrictive.SOMETIMES);
						} // else means never
					} else {
						restrictionsMap.set(interfacePin, Restrictive.ALWAYS);
					}
				});
			});

			const freePins = deviceData.board ? _.pick(allPins, pinMap.getFreePins()) : allPins;
			return new Optimization(allPins, freePins, restrictionsMap);
		}
	}
	return null;
}
