import * as _ from "lodash";
import * as path from "path";
import { fs } from "../../fileSystem";
import { FileTextConfigurable } from "public/defs";
import { RuntimeObject } from "public/runtime";
import { FormattersMap } from "../../formatting/formattersMap";
import { AObjectMgr } from "../object";
import { FileTextConfigurableMgr } from "./fileTextConfigurableMgr";
import { Validations } from "../validations";
import { serializeProjectPath } from "../../projectPath";
import { toLinuxPath } from "../../utils";

export class LocalFileTextConfigurableMgr extends FileTextConfigurableMgr {
	constructor(
		parentObjectMgr: AObjectMgr<RuntimeObject>,
		formattersMap: FormattersMap,
		public override readonly def: FileTextConfigurable,
	) {
		super(parentObjectMgr, formattersMap, def);
		if (!_.isEmpty(def.default) && !path.isAbsolute(def.default)) {
			throw new Error("Default value is not an absolute path.");
		}
	}

	public override validate(validations: Validations) {
		super.validate(validations);
		if (this.def.checkExistence) {
			if (this.value && !fs.fileExists(this.value)) {
				validations.logError("File does not exists.", this);
			}
		}
	}

	// The serialized path value can be either absolute(when not serializing to a file)
	// or relative(to a script file location when serializing to a script file)
	public override getScriptValue() {
		const outPath = serializeProjectPath ?
			path.relative(path.dirname(serializeProjectPath), this.value) || "."
			: this.value;
		return { value: JSON.stringify(toLinuxPath(outPath)), shouldQuoteStrings: false };
	}

	// Transforms a path that is set into an absolute path.
	//
	// When the path is picked using the file browser, it is an absolute path,
	// resolving it against another absolute path would not change its value.
	//
	// When the path is read from a script, it could be absolute or relative.
	// Absolute path comes from serialized scripts that do not originate from files,
	// and it works the same the prior case.
	// Relative path comes from serialized scripts originating from a file. In that case,
	// serializeProjectPath would be updated and contains the script file's path.
	//
	// When the path is manually entered, it could be absolute or relative.
	// Absolute path is again the same as before.
	// Entering a relative path is possible without serializeProjectPath being set,
	// so the current process's cwd is used as the reference to resolve the relative path.
	public override transform(fpath: string) {
		if (fpath === "") {
			return fpath;
		}
		const referencePath = serializeProjectPath ? serializeProjectPath : "";
		return path.resolve(path.dirname(referencePath), fpath);
	}
}
