import { ModuleInstanceMgr } from "../objectManagers/moduleInstance";
import { Module, FileModuleFileInstance, FileModuleRootInstance } from "public/runtime";
import { Runtime } from "../resources/runtime";
import { IStorageFile, flattenStorageFile, storage } from "../storage";
import { ModuleMgr } from "./module";
import * as path from "path";
import * as _ from "lodash";
import { StaticModuleInstanceMgr } from "../objectManagers/staticModuleInstance";
import { SetSource } from "../objectManagers/member";
import { FileStatusType } from "../../components/fileTrees/common";
import { ValidationSummary } from "../objectManagers/validations";

/*
	Special module manager to track a module with the fileTreeView
*/
export class FileModuleMgr extends ModuleMgr {
	private fileTreeRoot: IStorageFile;

	constructor(runtime: Runtime, module: Module) {
		super(runtime, module);
	}

	// does not have max instance restriction
	public override validateInstanceCount() {
	}

	public shouldUpdate() {
		return this.fileTreeRoot && (this.getRequestedRootPath() !== this.getRootPath());
	}

	public getInstanceByRelativePath(relativePath: string) {
		if (relativePath === this.getRootPath()) {
			return this.static;
		} else {
			return _.find(this.instances, (i) => this.getRelativePathFromInstance(i) === relativePath);
		}
	}

	public getSelectedFileRelativePath() {
		return this.getRelativePathFromInstance(this.getSelectedMyListItem());
	}

	public getFileTree() {
		return this.fileTreeRoot;
	}

	public getRootPath() {
		return this.fileTreeRoot ? this.fileTreeRoot.path : "";
	}

	public getRequestedRootPath() {
		return this.getRelativePathFromInstance(this.static);
	}

	public getAbsolutePath(pathStr: string) {
		return path.resolve(storage.formatPathForUser(this.fileTreeRoot.path), pathStr);
	}

	public createFileInstance(file: IStorageFile) {
		const inst = this.addInstance();
		if (!_.isUndefined((inst.managedObject as FileModuleFileInstance).filePathCfg)) {
			inst.memberMgrs.filePathCfg.set(
				file.relativePath,
				SetSource.USER_ASSIGN,
				true,
			);
		}
	}

	public override removeModule() {
		this.removeAllRemovableInstances();
		this.refreshTree();
		super.removeModule();
	}

	public refreshTree(newRoot?: IStorageFile) {
		if (!newRoot) { // no root so clear all instances
			this.removeAllRemovableInstances();
			this.fileTreeRoot = undefined;
		} else {
			if (this.fileTreeRoot && newRoot.path !== this.fileTreeRoot.path) { // root change so clear all instances
				this.removeAllRemovableInstances();
			} else if (this.fileTreeRoot && newRoot.path === this.fileTreeRoot.path) { // same root, reconcile the update
				const flatNew = newRoot ? flattenStorageFile(newRoot) : [];
				const flatOldByPath = _.keyBy(flattenStorageFile(this.fileTreeRoot), (f) => f.relativePath);
				const validPaths: string[] = [];
				// some infos should be kept when the file is the same
				_.each(flatNew, (f) => {
					validPaths.push(f.relativePath);
					const oldInfo = flatOldByPath[f.relativePath];
					if (oldInfo) {
						f.expanded = oldInfo.expanded;
					}
				});
				// remove all instances that represents a file that is not in the tree anymore
				_.chain(this.instances)
					.filter((i) => !validPaths.includes(this.getRelativePathFromInstance(i)))
					.each((i) => {
						i.remove();
					})
					.value();
			}
			this.fileTreeRoot = newRoot;
		}
		return this.fileTreeRoot;
	}

	public getFileInstanceStatus(file: IStorageFile): FileStatusType {
		if (file.isDirectory) {
			const allStatus = _.chain(file.children)
				.map((f) => this.getFileInstanceStatus(f))
				.compact()
				.value();
			if (_.isEmpty(allStatus)) {
				return undefined;
			} else if (_.some(allStatus, (s) => s === "error")) {
				return "error";
			} else if (_.some(allStatus, (s) => s === "warning")) {
				return "warning";
			} else {
				return undefined;
			}
		} else {
			const inst = this.getInstanceByRelativePath(file.relativePath);
			const validations = this.runtime.getValidations();
			const summary = validations.getSummary(inst);
			if (!inst) {
				return undefined;
			} else if (ValidationSummary.Error === summary) {
				return "error";
			} else if (ValidationSummary.Warning === summary) {
				return "warning";
			} else {
				return undefined;
			}
		}
	}

	public getFileSize(file: IStorageFile): number {
		if (file.isDirectory) {
			return _.sumBy(file.children, (d) => this.getFileSize(d));
		} else {
			const padding = this.getPadding(file);
			return padding ? padding + file.size : file.size;
		}
	}

	protected override getSelectableInstances() {
		if (this.static) {
			return [this.static, ...this.getInstances()];
		} else {
			return [];
		}
	}

	private getRelativePathFromInstance(inst: ModuleInstanceMgr) {
		if (inst instanceof StaticModuleInstanceMgr) {
			return (inst.managedObject as any as FileModuleRootInstance).rootDirCfg;
		} else {
			return (inst.managedObject as any as FileModuleFileInstance).filePathCfg;
		}
	}

	private getPadding(file: IStorageFile) {
		const inst = this.getInstanceByRelativePath(file.relativePath);
		if (inst) {
			return (inst.managedObject as any as FileModuleFileInstance).paddingSizeCfg;
		} else {
			return 0;
		}
	}
}
