import * as _ from "lodash";
import { AbstractAssumption, AbstractChoice, IChoice, RelatedChoices } from "./common";
import {
	not,
	mutuallyExclusive,
	chooseAtLeastOneOf,
	chooseAtLeastOneOfOnlyIf,
	allowOnlyIfOneOf,
} from "../clauseGeneration";
import { assume } from "../choices";
import { addLiteral, endClause } from "../clauses";
import { nameChoices } from "../debug";

interface ChoicesByAssignment {
	[assignment: string]: IChoice;
}

// Shareable choices grouped by:
// 1) those that can be shared together
// 2) the requirements
// 3) the choice of assignment for each requirement

export interface SharedChoices {
	[sharedHash: string]: {
		[requirementId: string]: ChoicesByAssignment;
	};
}

interface ChoicesByRequirement {
	[requirementId: string]: IChoice[];
}

// Conflicting choices, where the conflict is allowed, grouped by:
// 1) those that conflict with each other
// 2) user requirement

export interface ConflictingChoices {
	[assignment: string]: ChoicesByRequirement;
}

// A factory for creating implications in order to minimize hardware resources

export abstract class MinimizeResources {

	// This is the map of groups of implications (either sharable or allowed to conflict).
	// The count is the total number of requirements that could be combined.
	// The combinations are all the ways any two of those requirements could be combined

	protected readonly implications: {
		[shareableGroup: string]: {
			count: number,
			combinations: { [combination: string]: UsingSameResource },
		},
	} = {};

	// This is a map of each way of combining the combinations in this.implications such that one
	// additional resource is reduced, since some of those combinations will imply the same thing.
	// The key is the ResourceReduced implication

	private readonly reqsSharedByReduction = new RelatedChoices<number, IChoice>();

	// There will be one ResourceReduced implication created for each set of combinations above.
	// If there are N combinations above, then this will be a map of N groups of N repeated 
	// ResourceReduced implications.  That way, we can assert that to free up M of them, at least
	// one unique one per entry in this map up to M will be true.

	private readonly byNumberFreed = new RelatedChoices<number, ResourceReduced>();

	// This is the same set as this.byNumberFreed, but is instead grouped by how they are related.
	// This allows us to mutually exclude related ones per entry above, so that a different one is
	// selected on subsequent entries.

	private readonly byRequirementMerged = new RelatedChoices<string, ResourceReduced>();

	private currentAssumption = 0;
	private numAssumptions = 0;

	constructor(private readonly assumptionName: string) { }

	public addRestrictions() {

		// For every valid combination of two shareable pin requirements, or requirements that
		// are allowed to conflict, create an implication that is true only when they end up being shared.

		this.createCombinations(
			this.getSharedChoices(),
			"shared",
			(arg1, arg2, arg3, arg4) => new RequirementsShared(arg1, arg2, arg3, arg4));

		this.createCombinations(
			this.getConflictingChoices(),
			"allowConflicts",
			(arg1, arg2, arg3, arg4) => new RequirementsAllowedToConflict(arg1, arg2, arg3, arg4));

		// Now, generate the implications on top of those that are true when a resource is 
		// eliminated

		this.generateResourceReductions();
	}

	public generateClauses() {
		_.each(this.implications, (group) => {
			_.each(group.combinations, (choice) => choice.generateClauses());
		});

		chooseAtLeastOneOf(this.byNumberFreed, (index) => new ForceResourceReduction(this.assumptionName + index),
			"Unless assumed 'ok', must force at least one resource to be freed up");

		mutuallyExclusive(this.byRequirementMerged, null,
			"Must choose different resources to free up in order to free up an additional one");

		chooseAtLeastOneOfOnlyIf(this.reqsSharedByReduction, null,
			"Must choose at least one of these requirements to merge to free one resource");
	}

	public minimizeResourcesBy(thisAmount: number) {
		_.times(this.numAssumptions, (index) => {

			// a "false" assumption forces sharing of resources to eliminate one resource

			const newValue = index >= thisAmount;
			const currentValue = index >= this.currentAssumption;
			if (newValue !== currentValue) {
				assume(this.assumptionName + index, newValue);
			}
		});
		this.currentAssumption = thisAmount;
		return thisAmount <= this.numAssumptions;
	}

	public getMaxAvailable() {
		return this.numAssumptions;
	}

	protected abstract getSharedChoices(): SharedChoices;
	protected abstract getConflictingChoices(): ConflictingChoices;
	protected abstract getDirectlyMinimizingChoices(): IChoice[];

	// For every valid combination of two related requirements, create an implication
	// that is true only when they end up being shared.

	private createCombinations<T>(
		relatedChoices: { [key: string]: { [key: string]: T } },
		prefix: string,
		doNew: (choices1: T, choices2: T, name1: string, name2: string) => UsingSameResource,
	) {
		_.each(relatedChoices, (reqs, relationship) => {
			relationship = `${prefix}_${relationship}`;
			const keys = _.keys(reqs);
			this.implications[relationship] = { count: keys.length, combinations: {} };
			for (let i = 0; i < keys.length; ++i) {
				for (let j = i + 1; j < keys.length; ++j) {
					this.implications[relationship].combinations[i + "_" + j] =
						doNew(reqs[keys[i]], reqs[keys[j]], keys[i], keys[j]);
				}
			}
		});
	}

	private generateResourceReductions() {

		const generate = (index: number) => {
			let implicationsCreated = 0;

			// Create a ResourceReduced implication for each way that two related requirements can 
			// be combined

			_.each(this.implications, (reqs, sharableGroupName) => {
				const size = reqs.count;
				for (let i = 0; i < size - 1; ++i) {
					const resourceReduced = new ResourceReduced(sharableGroupName + i);
					const reqsShared = this.reqsSharedByReduction.get(resourceReduced.id);
					for (let j = i + 1; j < size; ++j) {
						reqsShared.push(this.implications[sharableGroupName].combinations[i + "_" + j]);
					}
					this.byNumberFreed.get(index).push(resourceReduced);
					this.byRequirementMerged.get(sharableGroupName + i).push(resourceReduced);
					++implicationsCreated;
				}
			});

			// For choices that directly minimize resources, create a ResourceReduced implication 
			// associated with just that one choice

			_.each(this.getDirectlyMinimizingChoices(), (choice, i) => {
				const resourceReduced = new ResourceReduced(`Directly minimizing choice ${i} (${this.assumptionName})`);
				this.reqsSharedByReduction.get(resourceReduced.id).push(choice);
				this.byNumberFreed.get(index).push(resourceReduced);
				this.byRequirementMerged.get("directlyMinimizing" + i).push(resourceReduced);
				++implicationsCreated;
			});
			return implicationsCreated;
		};

		// Loop through and generate the implications

		this.numAssumptions = generate(0);

		// Now, we'll need to duplicate that for every reduction possible
		// That allows us to choose different reductions multiple times....

		if (this.numAssumptions > 0) {
			_.times(this.numAssumptions - 1, (index) => generate(index + 1));
		}
	}
}

// This class represents an implied truth in the system based on other choices that were chosen.
// Underneath, it's implemented as a "choice", but really it's not "chosen" so much as "implied by 
// other choices".  As such, it never needs to do anything in the apply function.

class AbstractImplication extends AbstractChoice {
	public apply() {
	}
}

// This is an implication that is true if the requirements passed to it end up actually using the
// same underlying resource for some reason.

abstract class UsingSameResource extends AbstractImplication {
	public abstract generateClauses(): void;
	public abstract getDependentChoices(): IChoice[];
}

// This implication is true if the choices for the two possibly shared requirements passed to it, 
// actually end up being shared

class RequirementsShared extends UsingSameResource {

	constructor(
		private readonly choices1: ChoicesByAssignment,
		private readonly choices2: ChoicesByAssignment,
		reqName1: string,
		reqName2: string) {
		super();

		if (nameChoices) {
			this.name = "Share " + reqName1 + " and " + reqName2;
		}
	}

	public generateClauses() {

		const shareableAssignments = _.intersection(_.keys(this.choices1), _.keys(this.choices2));

		const explanation = "Requirements are shared only if both choose the same assignment";

		// We are implied to be true if both sharable requirements choose the same assignment

		_.each(shareableAssignments, (assignment) => {

			// If we are false, then all of the following clauses short-circuit.
			// So if one of the two assignments is true, the other can't be false without forcing 
			// us to false.			

			addLiteral(not(this.id));
			addLiteral(not(this.choices1[assignment].id));
			addLiteral(this.choices2[assignment].id);
			endClause(explanation);

			addLiteral(not(this.id));
			addLiteral(this.choices1[assignment].id);
			addLiteral(not(this.choices2[assignment].id));
			endClause(explanation);

			// Note that if both assignments are false, then the above clauses would be true.
			// However, since clauses are added for EVERY assignment combination, then one of
			// the other combinations won't be true unless we are false.
		});

		// However if any of the non-shareable assignments are chosen, then we must be false

		const unshareableAssignments = _.difference(_.keys(this.choices1), _.keys(this.choices2));
		_.each(unshareableAssignments, (assignment) => {
			const invalidChoice = this.choices1[assignment] || this.choices2[assignment];
			addLiteral(not(this.id));
			addLiteral(not(invalidChoice.id));
			endClause("Requirements aren't shared if a non-shareable assignment is made");
		});
	}

	public getDependentChoices() {
		return [..._.values(this.choices1), ..._.values(this.choices2)];
	}
}

// This implication is true if the choices for the two requirements passed to it, which are 
// marked "allowed to conflict" actually end up conflicting.  They may not if other errors
// prevent them from being true.

class RequirementsAllowedToConflict extends UsingSameResource {

	constructor(
		private readonly choices1: IChoice[],
		private readonly choices2: IChoice[],
		reqName1: string,
		reqName2: string) {
		super();

		if (nameChoices) {
			this.name = "Share " + reqName1 + " and " + reqName2;
		}
	}

	public generateClauses() {
		const explanation = "Requirements are conflicting (thus shared) only if they were taken (no error)";

		// We are true if and only if one choice from each set is taken.

		allowOnlyIfOneOf(this.id, this.choices1, explanation);
		allowOnlyIfOneOf(this.id, this.choices2, explanation);
	}

	public getDependentChoices() {
		return [...this.choices1, ...this.choices2];
	}
}

// This implication is true if a group of shareable requirements actually were shared such that
// one resource in the system was reduced.  To reduce the resources of the system again, a second
// instance of this implication must also be true.
//
// This differs from the implication of any two resources being shared, because that implication
// doesn't necessarily imply a reduction of resources.  For instance, if there are three 
// requirements named a, b and c, then you've shared them if any of the following combinations are 
// true: ab, ac, bc.  However, of if all three of those combinations are true, you've only really
// freed up two resources (ab, ac implies bc etc).  
// 
// This class implies specifically that a resource was freed up.

class ResourceReduced extends AbstractImplication {

	constructor(
		reqName: string) {
		super();

		if (nameChoices) {
			this.name = "Free up resource from " + reqName;
		}
	}
}

// If this assumption is false, then a resource reduction is forced in the system

class ForceResourceReduction extends AbstractAssumption {
	constructor(name: string) {
		super(name);

		if (nameChoices) {
			this.name = "Free resource assumption for index: " + name;
		}
	}
}
