import { UserError } from "../niceExceptions";
import { withDeprecatedAccess, AccessSpecification } from "../deprecatedAccessGuard";

let scriptingEnabled = false;

export function enableScripting(enable: boolean) {
	scriptingEnabled = enable;
}
export function isScriptingEnabled() {
	return scriptingEnabled;
}
export function disableScriptingForCallback<Ret>(callback: () => Ret) {
	if (!scriptingEnabled) {
		return withDeprecatedAccess({}, callback);
	}
	try {
		scriptingEnabled = false;
		return withDeprecatedAccess({}, callback);
	} finally {
		scriptingEnabled = true;
	}
}

export async function disableScriptingForCallbackAsync<Ret>(callback: () => Promise<Ret>) {
	if (!scriptingEnabled) {
		return withDeprecatedAccess({}, callback);
	}
	try {
		scriptingEnabled = false;
		return await withDeprecatedAccess({}, callback);
	} finally {
		scriptingEnabled = true;
	}
}

// eslint-disable-next-line @typescript-eslint/ban-types
export function guardScriptingFunction<Func extends Function>(func: Func, context: string): Func;
export function guardScriptingFunction<Ret>(func: (...args: any[]) => Ret, context: string) {
	return (...args: any[]) => {
		if (!scriptingEnabled) {
			throw new Error("Scripting functionality is not available at this time");
		}
		try {
			return disableScriptingForCallback(() => func(...args));
		} catch (e) {
			throw new UserError(`Exception occurred calling ${context}()`, e);
		}
	};
}

let runningUserScript = false;

export function isRunningUserScript() {
	return runningUserScript;
}

export function runAsUserScript(cb: () => void, deprecatedAccess: AccessSpecification = {}) {
	enableScripting(true);
	runningUserScript = true;
	try {
		withDeprecatedAccess(deprecatedAccess, cb);
	} finally {
		runningUserScript = false;
		enableScripting(false);
	}
}
