import { AbstractAssumption, AbstractChoice, RelatedChoices } from "./common";
import { PeripheralChoices } from "./peripheral";
import { DevicePinChoices } from "./devicePin";
import { not, mutuallyExclusive, chooseAtLeastOneOf, chooseAll } from "../clauseGeneration";
import { addLiteral, endClause } from "../clauses";
import { nameChoices, formatNameChoice } from "../debug";
import { clearSolution, updateSolution, addVoltageWarningToSolution } from "../../utils";
import { PowerDomainSettings, Peripheral, Solution } from "../requirements";

// -----------------------------------------------------------------------------
// PowerChoices
// Encapsulates the voltage choice for a specific peripheral requirement that 
// ideally must apply to each pin under that requirement.  However, if the 
// pin can't be placed at that power level, it's a warning not an error.  As 
// such, the goal is to minimize warnings.
// -----------------------------------------------------------------------------

export class PowerChoices {
	public readonly warnings: { [key: string]: PowerChoices.Warning } = {};
	private readonly byPeripheral = new RelatedChoices<string, PowerChoices.Choice>();
	private readonly all: PowerChoices.Choice[] = [];
	private readonly overrides: PowerChoices.Choice[] = [];
	constructor(
		private readonly pinChoices: DevicePinChoices, private readonly powerDomainSettings: PowerDomainSettings,
		private readonly powerDomainSettingsEnabled: boolean) { }

	public addRestrictions(peripheralChoices: PeripheralChoices.Choice[], peripheralReq: Peripheral) {
		if (this.powerDomainSettingsEnabled) {
			for (const perfChoice of peripheralChoices) {
				const pinChoices = this.pinChoices.byParent.get(perfChoice.id);
				for (const pinChoice of pinChoices) {
					if (pinChoice.devicePin.powerDomain) {
						const voltage = this.powerDomainSettings[pinChoice.devicePin.powerDomain.name];
						if (voltage) {
							const powerChoice = this.getChoice(voltage, peripheralReq);
							powerChoice.pins.push(pinChoice);
						}
					}
				}
			}

			if (peripheralReq.userVoltageOverride) {
				const choice = this.getChoice(peripheralReq.userVoltageOverride, peripheralReq);
				this.overrides.push(choice);
				choice.isOverride = true;
			}
		}
	}

	public generateClauses() {
		// Must choose at least one power level

		chooseAtLeastOneOf(this.byPeripheral, null, "choose at least one power choice per peripheral");

		// But, multiple are allowed if there's a warning

		mutuallyExclusive(this.byPeripheral, (choiceName) => this.getWarning(choiceName),
			"only allow one power choice unless there's a warning");

		// Apply user overrides
		// Since the override is at the interface level, but the choice is at a 
		// peripheral level, we make the peripheral dependent on the overridden 
		// choice instead of forcing all overrides to true which would fail.

		chooseAll(this.overrides, null, "power level override");

		// Either the pin is not selected, or the power choice is selected

		for (const powerChoice of this.all) {
			for (const pinChoice of powerChoice.pins) {
				addLiteral(not(pinChoice.id));
				addLiteral(powerChoice.id);
				endClause("either the pin is not selected, or the power choice is selected");
			}
		}
	}

	private getChoice(voltage: string, peripheralReq: Peripheral) {
		const powerChoices = this.byPeripheral.get(peripheralReq.id);

		let powerChoice: PowerChoices.Choice = null;
		for (let i = 0; i < powerChoices.length && !powerChoice; ++i) {
			if (powerChoices[i].voltage === voltage) {
				powerChoice = powerChoices[i];
			}
		}
		if (!powerChoice) {
			powerChoice = new PowerChoices.Choice(voltage, peripheralReq, powerChoices);
			this.all.push(powerChoice);
		}
		return powerChoice;
	}

	private getWarning(warningId: string) {
		if (warningId in this.warnings) {
			return this.warnings[warningId];
		}

		const warning = new PowerChoices.Warning(warningId);
		this.warnings[warningId] = warning;
		return warning;
	}
}

export namespace PowerChoices {
	export class Choice extends AbstractChoice {
		public readonly pins: DevicePinChoices.Choice[] = [];
		public isOverride = false;
		private readonly voltageSolution: Solution;
		private applied = false;

		constructor(
			public readonly voltage: string,
			peripheralReq: Peripheral,
			private readonly powerChoices: PowerChoices.Choice[]) {
			super();
			this.voltageSolution = peripheralReq.voltageSolution;
			this.powerChoices.push(this);

			clearSolution(this.voltageSolution);

			if (nameChoices) {
				this.name = "Power " + formatNameChoice(peripheralReq) + "->" + voltage;
			}
		}

		public apply() {
			if ("" === this.voltageSolution.assignedToName) {
				updateSolution(this.voltageSolution, this.voltage);
				this.applied = true;
			} else {
				// Another power choice has already been selected.  Find it

				let appliedChoice: PowerChoices.Choice = null;
				for (let i = 0; i < this.powerChoices.length && !appliedChoice; ++i) {
					if (this.powerChoices[i].applied) {
						appliedChoice = this.powerChoices[i];
					}
				}

				// Between us and the currently applied choice, we want the choice to 
				// be the one that has the most associated pins, thereby minimizing 
				// warnings.  Or, the user overridden choice...
				// eslint-disable-next-line @typescript-eslint/no-this-alias
				let warningChoice: PowerChoices.Choice = this;
				const appliedPinCount = this.countAppliedPins(appliedChoice.pins);
				const warningPinCount = this.countAppliedPins(warningChoice.pins);
				if ((appliedPinCount < warningPinCount && !appliedChoice.isOverride) || warningChoice.isOverride) {
					warningChoice = appliedChoice;
					// eslint-disable-next-line @typescript-eslint/no-this-alias
					appliedChoice = this;
				}

				// Apply the correct choice, then mark the pins on the other choice 
				// with appropriate warnings

				updateSolution(appliedChoice.voltageSolution, appliedChoice.voltage);
				appliedChoice.applied = true;

				warningChoice.applied = false;
				for (const pin of warningChoice.pins) {
					if (pin.applied) {
						const warningText = pin.devicePin.powerDomain.name + " is set to " + warningChoice.voltage;
						addVoltageWarningToSolution(pin.pinReq.solution, warningText);
					}
				}
			}
		}

		private countAppliedPins(pins: DevicePinChoices.Choice[]) {
			let count = 0;
			for (const pin of pins) {
				if (pin.applied) {
					++count;
				}
			}
			return count;
		}
	}

	export class Warning extends AbstractAssumption {

		public override readonly id: number;
		public override readonly name?: string;

		constructor(warningId: string) {
			super(warningId);

			if (nameChoices) {
				this.name = "Power warning " + warningId;
			}
		}
	}
}
