import { Module } from "public/runtime";
import * as _ from "lodash";
import { keys } from "../utils";

const modKeys: Required<Module> = {
	moduleStatic: null,
	templates: null,
	references: null,
	maxInstances: null,
	defaultInstanceName: null,
	config: null,
	pinmuxRequirements: null,
	moduleInstances: null,
	sharedModuleInstances: null,
	modules: null,
	validate: null,
	validatePinmux: null,
	filterHardware: null,
	onHardwareChanged: null,
	displayName: null,
	description: null,
	longDescription: null,
	documentation: null,
	$name: null,
	$instances: null,
	$static: null,
	$configByName: null,
	uiView: null,
	uiAdd: null,
	alwaysShowLongDescription: null,
	migrateLegacyConfiguration: null,
	recreateOnArgsChange: null,
	proxyFor: null,
	extendConfig: null,
	onMigrate: null,
	ports: null,
	dependencies: null,
};

// Tool consumed members on $module should be read only. 
// But we also want to allow people to assign new members to $module.
// So, we need to keep track of the mandatory members of $module that the tool consumes,
// and block their modification through a proxy.
export const modReadOnlyKeys = keys(modKeys);

// These members itself cannot be modified from $module,
// but child keys can be added/removed at will
// They will only go through a readonly proxy and no freeze
export const modFreeKeys: (keyof Module)[] = [
	"$instances",
	"$static",
	"moduleStatic",
];

// These members itself cannot be modified from $module,
// they will also be sealed, so child keys can not be added/removed,
// however, the value of the child keys can be modified.
export const modSealedKeys: (keyof Module)[] = [
	"templates",
];

// These members itself cannot be modified from $module,
// they will also be deep frozen, so all descendants will be frozen
export const modFrozenKeys =
	_.chain(modReadOnlyKeys)
		.difference(modFreeKeys)
		.difference(modSealedKeys)
		.value();
