import * as _ from "lodash";
import { ModuleInstance } from "public/runtime";
import { FormattersMap } from "../formatting/formattersMap";
import { keys } from "../utils";
import { EnumerationConfigurableMgr } from "./configurables/enumerationConfigurableMgr";
import { ShapeConfigurable, Shape } from "public/defs";
import { validateConfigurable } from "./configurables/configurable";
import { ModuleInstanceMgr } from "./moduleInstance";
import { SCHEMA } from "../JSONschemata";

// Configurable manager for $shape.  It's basically just an enum with fixed text options and special validation

export class ShapeMemberMgr
	extends EnumerationConfigurableMgr<ModuleInstance, Shape> {
	constructor(
		parentObjectMgr: ModuleInstanceMgr,
		formattersMap: FormattersMap,
		def: ShapeConfigurable,
	) {
		validateConfigurable(def, parentObjectMgr.module.$name, SCHEMA.ShapeConfigurable, false);

		super(
			parentObjectMgr,
			formattersMap,
			{
				hidden: true,
				...def,
				options: shapeOptions,
			},
		);
	}
}

// The type ensures we didn't drop a value (try commenting out one line and you'll see)
// Ideally, we'd use an enum, but we can't have enums defined only in .d.ts files, or we'd generate the Shape type from
// an "as const" array, but then we can't have it defined only in d.ts.  As such, this is the best solution we have as
// it will at least tell us at compile time if we missed a value

const shapeWordsAsKeys: Record<Shape, number> = {
	square: 1,
	and: 1,
	or: 1,
	buffer: 1,
	xor: 1,
	nand: 1,
	nor: 1,
	not: 1,
	xnor: 1,
	oscillator: 1,
	pin: 1,
	biDirectionalPin: 1,
	power: 1,
	ground: 1,
	label: 1,
};

const shapeOptions = _.map(keys(shapeWordsAsKeys), (name) => ({ name }));
