import { ManagedObjectProxyTarget } from "./managedObjectProxyHandler";
import { InvalidAssignmentWrapper } from "../invalidAssignment";
import { RuntimeObject } from "public/runtime";

interface Target {
	path: string[];
	originalTarget: Pick<ManagedObjectProxyTarget, "invalidAccess">;
}

// This is a proxy handler to be used in a proxy when an invalid member of another proxy is accessed.
// It will track the member name, and return additional proxies with an updated member path.  When 
// a member is eventually set, it will record that invalid access back on the original object manager.

const invalidAssignmentProxyHandler: ProxyHandler<Target> = {
	get: (target, key: Extract<PropertyKey, string>) => {
		return createInvalidAssignmentProxy([...target.path, key], target.originalTarget);
	},

	set: (target, key: Extract<PropertyKey, string>, val) => {
		const invalidAssignment = val instanceof InvalidAssignmentWrapper ? val : undefined;
		val = invalidAssignment ? invalidAssignment.val : val;
		target.originalTarget.invalidAccess(val, [...target.path, key], invalidAssignment?.reason);
		return true;
	},

	ownKeys: () => {
		return [];
	},

	has: () => {
		return false;
	},

	defineProperty: () => {
		return false; // disallow
	},

	deleteProperty: () => {
		return false; // disallow
	},

	getOwnPropertyDescriptor: () => {
		return undefined;
	},

	setPrototypeOf: () => {
		return false; // disallow
	},
};

// This map is mainly used for handling invalid port assignments in a scripting.connect call
const invalidAssignmentProxyMap = new WeakMap<RuntimeObject, InvalidAssignmentProxyKey>();
export function createInvalidAssignmentProxy(path: string[], originalTarget: OriginalTarget) {
	const proxyTarget = {
		path,
		originalTarget,
	};
	const invalidAssignmentProxy = new Proxy(proxyTarget, invalidAssignmentProxyHandler);
	invalidAssignmentProxyMap.set(invalidAssignmentProxy as any as RuntimeObject, proxyTarget);
	return invalidAssignmentProxy;
}
export function getInvalidMemberAccessProxy(invalidMemberAccess: RuntimeObject) {
	return invalidAssignmentProxyMap.get(invalidMemberAccess);
}

interface InvalidAssignmentProxyKey {
	path: string[],
	originalTarget: OriginalTarget
}

type OriginalTarget = ManagedObjectProxyTarget | Pick<ManagedObjectProxyTarget, "invalidAccess">;
