const pinOverrideConfigurableName: keyof Pin = "$assign";

// Return a filter function that filters out pins not attached to this component
function createComponentFilter(componentConnections: DeviceData.DevicePin[]) {

	// No component, don't filter anything

	if (null === componentConnections) {
		return () => true;
	}

	// We have a component, return if it's a valid connection to this component,
	// or a virtual pin (like a DMA channel that's not pinned out)

	return (devicePin: DeviceData.DevicePin, pinType: PinType) => {
		return _.includes(componentConnections, devicePin) || PinType.VIRTUAL === pinType;
	};
}

// process the interface pin data for information need to create a pin override member
function processInterfacePin(
	interfacePins: DeviceData.InterfacePin[],
	componentConnections: DeviceData.DevicePin[],
	metaFilter: (devicePin: DeviceData.DevicePin, peripheralPin: DeviceData.PeripheralPin) => boolean = () => true,
	preferredTypes: string[],
	pinMap: PinMap,
) {
	// device pin name to peripheral names
	// used to track all valid peripheral choices associated with a device pin

	const devicePinNameToFilter: { [name: string]: string[] } = {};

	// track peripheral pin to device pins

	const validMappings: { [signal: string]: string[] } = {};

	let devicePins: DeviceData.DevicePin[] = [];

	// Track preferred pins

	const preferredPins: string[] = [];

	let unavailablePins: DeviceData.DevicePin[] = [];

	// Look at all possible mappings and filter them into the corresponding lists

	const boardFilter = createComponentFilter(componentConnections);
	pinMap.forEachMapping(interfacePins, null, (devicePin, peripheralPin, info) => {
		if (metaFilter(devicePin, peripheralPin)) {
			if (boardFilter(devicePin, info.type)) {
				validMappings[peripheralPin.name] = validMappings[peripheralPin.name] || [];
				validMappings[peripheralPin.name].push(devicePin.name);
				devicePins.push(devicePin);
				devicePinNameToFilter[devicePin.name] = devicePinNameToFilter[devicePin.name] || [];
				devicePinNameToFilter[devicePin.name].push(peripheralPin.peripheralName);
				if (!preferredTypes || !_.isEmpty(_.intersection(info.preferredTypes, preferredTypes))) {
					preferredPins.push(devicePin.name);
				}
			} else {
				unavailablePins.push(devicePin);
			}
		}
	});

	// We could have duplicates from multiple interface pins to the same device pin

	devicePins = _.uniqBy(devicePins, (dp) => dp.name);
	unavailablePins = _.uniqBy(unavailablePins, (dp) => dp.name);

	const options: EnumerationOption[] = _.map(devicePins,
		(dp) => {
			return {
				name: dp.name,
				displayName: dp.name,
			};
		},
	);

	const anyOption = util.createAnyOption();
	options.unshift(anyOption);

	const configurableDef = {
		name: pinOverrideConfigurableName,
		displayName: "Assign Pin",
		options,
		default: anyOption.name,
	};

	return {
		devicePins,
		devicePinNameToFilter,
		configurableDef,
		validMappings,
		preferredPins,
		unavailablePins,
	};
}

/**
 * Manages the built-in $assign and $assignAllowConflicts
 */
class PinNameTranslator {

	public constructor(
		private readonly devicePins: DeviceData.DevicePin[],
		private readonly def: EnumerationConfigurable,
		private readonly userPref: UserPreference,
		private readonly pinMap: PinMap,
	) {
	}

	public getScriptStatements(parentIdentifier: string, options: SerializationOptions, value: string) {
		return [
			createMemberValueAssignmentStatement(
				this.def,
				parentIdentifier,
				this.getRValueForScript(options, value),
			),
		];
	}

	public getRValueForScript(options: SerializationOptions, value: string) {
		let rvalue: string; // value to assign
		const selectedDevicePin = _.find(this.devicePins, (dp) => dp.name === value);

		// We should serialize using a header pin name if possible, because those will be more
		// portable to other boards

		const { headerInfo } = this.pinMap.get(selectedDevicePin);
		if (!_.isEmpty(headerInfo) && options.deviceDataMigration !== MigrationType.BOARD_TO_DEVICE) {
			const { header, headerPin } = _.first(headerInfo);
			rvalue = `${header.name}.${headerPin.number}`;
		} else {
			rvalue = this.serializeAsBall(options, selectedDevicePin)
				? `ball.${selectedDevicePin.name}`
				: selectedDevicePin.designSignalName;
		}
		return rvalue;
	}

	public transform(val: string): string {

		if (val === util.Const.ANY) {
			return val;
		}

		// If it starts with "ball.", then it's a ball for sure

		let devicePin;
		if (_.startsWith(val, "ball.")) {
			const ball = val.slice("ball.".length);
			devicePin = _.find(this.devicePins, (p) => p.name === ball);
		} else {

			// It doesn't start with "ball.", so first check if it's a signal and THEN a ball
			// The code will never serialize just a ball name, but legacy versions of the tool would

			devicePin = _.find(this.devicePins, (dp) => dp.designSignalName === val) ??
				_.find(this.devicePins, (dp) => dp.name === val);
			// If not, maybe it refers to a header pin?
			if (!devicePin) {
				const decoded = this.decodeHeaderPinText(val);
				devicePin = _.find(this.devicePins, (dp) => {
					return _.some(this.pinMap.get(dp).headerInfo, ({ header, headerPin }) => {
						return (headerPin.name === decoded.headerPinName ||
							(header.name === decoded.headerName && headerPin.number === decoded.headerPinNum));
					});
				});
				// If not maybe it refers to a remapped legacy header pin or it uses a legacy header but the pin has not been remapped?
				if (!devicePin) {
					devicePin = _.find(this.devicePins, (dp) => {
						return _.some(this.pinMap.get(dp).headerInfo, ({ header, headerPin }) => {
							const legacyHeaderMap = header.legacyPinLayout?.[decoded.headerName];
							// first check if the header with the pin remapped exists
							return legacyHeaderMap?.[_.toString(decoded.headerPinNum)] &&
								legacyHeaderMap[_.toString(decoded.headerPinNum)] === headerPin.number
								// if we have the correct header name but, don't have the pin mapped use the current pin
								|| (legacyHeaderMap && decoded.headerPinNum === headerPin.number);
						});
					});
				}
			}

		}

		// always use name (pin number) internally

		return devicePin?.name ?? val;
	}

	public validOptions() {
		// You can use either the pin name or package pin name (ball)

		const standardOptions = _.flatMap(this.devicePins, (pin) => {
			if (pin.devicePinType === "Virtual") {
				return pin.designSignalName;
			} else {
				return [pin.designSignalName, `ball.${pin.name}`];
			}
		});

		// Pins exported on a board header can also use that

		const headerOptions = _.chain(this.devicePins)
			.flatMap((devicePin) => this.pinMap.get(devicePin).headerInfo)
			.compact()
			.flatMap(({ header, headerPin }) => [`${header.name}.${headerPin.number}`, headerPin.name])
			.value();

		return [
			util.Const.ANY,
			...standardOptions,
			...headerOptions,
		];
	}

	private decodeHeaderPinText(val: string) {

		// Try to match <header name>.<pin number> first
		// That's the format for a portable name

		const match = /^(.+)\.([0-9]+)$/.exec(val);
		if (match) {
			return {
				headerName: match[1],
				headerPinNum: parseInt(match[2], 10),
				headerPinName: val,
			};
		}

		// If not, maybe is just the name of a header pin

		return { headerPinName: val };
	}

	private serializeAsBall(options: SerializationOptions, selectedDevicePin: DeviceData.DevicePin) {
		return this.serializePrefIsBall() &&						// User prefers "ball"
			MigrationType.NONE === options.deviceDataMigration && 	// Should use "ball" when migrating
			selectedDevicePin.devicePinType !== "Virtual";			// Virtual pins don't have balls
	}

	// Indicate the user's preferred serialization type

	private serializePrefIsBall() {

		// Use the design signal name if they picked "both"

		const pref = this.userPref.getPreferences().devicePinDisplayType;
		const pinDisplayOptions = pref.getSelectedEnums();
		return _.size(pinDisplayOptions) === 1 && _.first(pinDisplayOptions) === PinDisplayType.DEVICENUM;
	}
}

export function getDisabledTooltip(pinInfo: PinMapEntry) {
	switch (pinInfo.type) {
		case PinType.COMPONENT:
			return "This pin is not connected to the hardware that this software is using.";
		case PinType.FREE:
			return "Header pins are wired out to the board header and can only be selected if 'Use Hardware' is set to 'None'";
		case PinType.UNEXPORTED:
			return "Device pins are not exported anywhere on the board and can only be selected if " +
				"'Use Hardware' is set to 'None'";
		default:
			util.assertUnreachable(pinInfo.type);
		case PinType.VIRTUAL:
			throw new Error("Unexpected pin type");
	}
}

export function getEnabledTooltip(pinMap: PinMap, devicePin: DeviceData.DevicePin) {
	if (!pinMap.isBoard()) {
		return "";
	}
	const pinInfo = pinMap.get(devicePin);
	switch (pinInfo.type) {
		case PinType.COMPONENT:
			return `This pin is connected to '${util.getDisplayName(pinInfo.component, false)}'.  If supported by this software, ` +
				`select '${util.getDisplayName(pinInfo.component, false)}' from 'Use Hardware' above to avoid a warning.`;
		case PinType.FREE:
			return "Header pins are wired out to the board header and are not associated with any hardware.";
		case PinType.UNEXPORTED:
			return "Device pins are not pinned out on this board or associated with hardware.  " +
				"Switching to a device would enable the use of this pin without a warning.";
		case PinType.VIRTUAL:
			return "";
		default:
			util.assertUnreachable(pinInfo.type);
			throw new Error("Unexpected pin type");
	}
}

function getLabel(pinMap: PinMap, devicePin: DeviceData.DevicePin) {
	if (!pinMap.isBoard()) {
		return "";
	}
	const pinInfo = pinMap.get(devicePin);
	switch (pinInfo.type) {
		case PinType.COMPONENT:
			return ` (${util.getDisplayName(pinInfo.component, false)})`;
		case PinType.FREE:
			return " (Header)";
		case PinType.UNEXPORTED:
			return " (Device Only)";
		case PinType.VIRTUAL:
			return ""; // Virtual pins will only be seen with other virtual pins, so a label isn't needed
		default:
			util.assertUnreachable(pinInfo.type);
			throw new Error("Unexpected pin type");
	}
}

/**
 * Manages the built-in $assign
 */
export class PinOverrideMgr extends OverrideMgr<Pin> implements IOptions<string> {

	private readonly translator: PinNameTranslator;

	private readonly selection: Selection;

	public constructor(
		parent: PinMgr,
		configDef: EnumerationConfigurable,
		solverReq: RequirementData.Pin,
		private readonly devicePins: DeviceData.DevicePin[],
		private readonly peripheralFilter: SelectionFilterGroup,
		private readonly devicePinNameToFilter: { [name: string]: string[]; },
		userPref: UserPreference,
		private readonly unavailablePins: DeviceData.DevicePin[],
		private readonly pinMap: PinMap,
		formattersMap: FormattersMap,
	) {
		super(
			parent,
			formattersMap,
			solverReq,
			configDef,
		);

		this.translator = new PinNameTranslator(devicePins, this.def, userPref, pinMap);

		this.selection = {
			isOverridden: () => {
				return this.value !== util.Const.ANY;
			},
			getFiltersForOverridden: () => devicePinNameToFilter[this.value],
		};

		peripheralFilter.addSelection(this.selection);
	}

	public override remove() {
		this.peripheralFilter.removeSelection(this.selection);
		super.remove();
	}

	public override getCLIOptions() {

		const uiOptions = this.getUIOptions();
		const enabledOptions = _.map(uiOptions.enabledOptions, (o) => o.name);
		const disabledOptions = _.map(uiOptions.disabledOptions, (o) => {
			return { name: o.name, reason: o.description };
		});

		return {
			enabledOptions,
			disabledOptions,
		};
	}

	public override getUIOptions() {

		// Style doesn't matter when formatting device pins

		const formatter = this.formattersMap.getFormatter({ style: FormatStyle.CLI });

		const options = this.applyOverrideFilters();
		const enabledOptions = _.map(options.enabled, (devicePin) => {
			return {
				name: devicePin.name,
				displayName: `${formatter(devicePin)}${getLabel(this.pinMap, devicePin)}`,
				description: getEnabledTooltip(this.pinMap, devicePin),
				type: this.pinMap.get(devicePin).type,
			};
		});

		// Since these came from applyOverrideFilters, they can only be disabled due to pinmux overrides

		const disabledOptions = _.map(options.disabled, (devicePin) => {
			return {
				name: devicePin.name,
				displayName: `${formatter(devicePin)}${getLabel(this.pinMap, devicePin)}`,
				description: "This selection is not possible with your other pin and/or peripheral overrides",
				type: this.pinMap.get(devicePin).type,
			};
		});

		// unavailablePins are pins that are NEVER selectable (requires 'use hardware' set to none)

		disabledOptions.push(
			..._.map(this.unavailablePins, (devicePin) => ({
				name: devicePin.name,
				displayName: `${formatter(devicePin)}${getLabel(this.pinMap, devicePin)}`,
				description: getDisabledTooltip(this.pinMap.get(devicePin)),
				type: this.pinMap.get(devicePin).type,
			})));

		// sort the result - sort by type first, then the name

		return {
			enabledOptions: util.naturalSort(enabledOptions, (entry) => `${entry.type} ${util.getDisplayName(entry, false)}`),
			disabledOptions: util.naturalSort(disabledOptions, (entry) => `${entry.type} ${util.getDisplayName(entry, false)}`),
		};
	}

	public getDevicePins() {
		return this.devicePins;
	}

	// override from EnumerationConfigurableMgr

	public override generateScriptStatements(parentIdentifier: string, options: SerializationOptions) {
		const rvalue = util.Const.ANY === this.value ? this.solverReq.solution.assignedToName : this.value;
		return this.translator.getScriptStatements(parentIdentifier, options, rvalue);
	}

	// override from EnumerationConfigurableMgr

	protected override validOptions() {
		return this.translator.validOptions();
	}

	// override from EnumerationConfigurableMgr

	protected override transform(val: string) {
		return this.translator ? this.translator.transform(val) : val;
	}

	private applyOverrideFilters() {
		return this.peripheralFilter.filterOptions(
			this.selection, this.devicePins, (dp) => this.devicePinNameToFilter[dp.name],
		);
	}
}

/**
 * Manages the built-in $assignAllowConflicts
 */
class PinAllowConflictsMgr extends AllowConflictsMgr<Pin> {

	private readonly translator: PinNameTranslator;

	public constructor(
		parent: PinMgr,
		configDef: EnumerationConfigurable,
		solverReq: RequirementData.Pin,
		devicePins: DeviceData.DevicePin[],
		userPref: UserPreference,
		pinMap: PinMap,
		formattersMap: FormattersMap,
	) {
		super(
			parent,
			formattersMap,
			solverReq,
			configDef,
		);

		this.translator = new PinNameTranslator(devicePins, this.def, userPref, pinMap);
	}

	// override from EnumerationConfigurableMgr

	public override generateScriptStatements(parentIdentifier: string, options: SerializationOptions) {
		return this.translator.getScriptStatements(parentIdentifier, options, this.value);
	}

	// override from EnumerationConfigurableMgr

	protected override validOptions() {
		return this.translator.validOptions();
	}

	// override from EnumerationConfigurableMgr

	protected override transform(val: string) {
		return this.translator ? this.translator.transform(val) : val;
	}
}

/**
 * Manages the built-in $suggestSolution
 */
class PinSuggestSolutionMgr extends SuggestSolutionMgr<Pin, RequirementData.Pin> {

	private readonly translator: PinNameTranslator;

	public constructor(
		parent: PinMgr,
		configDef: StaticEnumerationConfigurable,
		solverReq: RequirementData.Pin,
		devicePins: DeviceData.DevicePin[],
		userPref: UserPreference,
		pinMap: PinMap,
		formattersMap: FormattersMap,
	) {
		super(
			parent,
			formattersMap,
			solverReq,
			configDef,
		);

		// Pass configDef to the translator so it won't translate "<error>"

		this.translator = new PinNameTranslator(devicePins, configDef, userPref, pinMap);
	}

	// override from EnumerationConfigurableMgr

	protected override validOptions() {
		return [...this.translator.validOptions(), SuggestSolutionMgr.errorTag];
	}

	// override from EnumerationConfigurableMgr

	protected override transform(val: string) {
		const translatedVal = !this.translator ? val : this.translator.transform(val);

		return super.transform(translatedVal);
	}

	// Also don't serialize if we're not being used

	protected override shouldSerialize(options: SerializationOptions) {
		return this.solverReq.used && super.shouldSerialize(options);
	}

	protected override getRValueForScript(options: SerializationOptions) {
		if (this.solverReq.solution.assignedToName) {
			return this.translator.getRValueForScript(options, this.solverReq.solution.assignedToName);
		}
		return SuggestSolutionMgr.errorTag;
	}
}

const pinUsedConfigurableMember: keyof Pin = "$used";
// Built-in is used member
class PinUsedMgr extends BooleanConfigurableMgr {
	constructor(
		parent: PinMgr,
		formattersMap: FormattersMap,
		private readonly solverReq: RequirementData.Pin,
		used: boolean,
	) {

		super(
			parent,
			formattersMap,
			{
				name: pinUsedConfigurableMember,
				displayName: "Used",
				default: used,
				hidden: true,
			},
		);

		// init
		this.setUsed(this.value);
	}

	protected override onSet(newVal: boolean) {
		this.setUsed(newVal);
	}

	private setUsed(val: boolean) {
		this.solverReq.used = val;
		if (!val) {
			// reset the solution
			util.clearSolution(this.solverReq.solution);
		}
	}
}

/**
 * Class for creating and managing solver related built-ins
 */
export class SolverRequirement {

	private readonly overrideMgr: PinOverrideMgr;
	private readonly conflictMgr: PinAllowConflictsMgr;
	private readonly usedMgr?: PinUsedMgr;
	private readonly reqData: RequirementData.Pin;
	constructor(
		reqName: string,
		parent: PinMgr,
		interfacePins: DeviceData.InterfacePin[],
		peripheralFilter: SelectionFilterGroup,
		componentConnections: DeviceData.DevicePin[],
		userPref: UserPreference,
		options: {
			canShareWith?: string,
			filter?: (devicePin: DeviceData.DevicePin, peripheralPin: DeviceData.PeripheralPin) => boolean,
			preferredTypes?: string[],
		} = {},
		pinMap: PinMap,
		formattersMap: FormattersMap,
		reserved: boolean = false,
		used = true,
	) {
		this.reqData = new RequirementData.Pin(
			reqName,
			interfacePins,
			options.canShareWith,
			reserved,
		);

		let somethingFiltered = false;
		if (options.filter) {
			const originalFilter = options.filter;
			options.filter = (devicePin, peripheralPin) => {
				const includePin = originalFilter(devicePin, peripheralPin);
				somethingFiltered = somethingFiltered || !includePin;
				return includePin;
			};
		}

		const {
			devicePins,
			devicePinNameToFilter,
			configurableDef,
			validMappings,
			preferredPins,
			unavailablePins,
		} = processInterfacePin(interfacePins, componentConnections,
			options.filter, options.preferredTypes, pinMap);

		if (somethingFiltered || null !== componentConnections) {
			this.reqData.restrictTo = validMappings;
		}
		this.reqData.preferredPins = preferredPins;

		this.reqData.connectedToHardware = null !== componentConnections;

		this.overrideMgr = new PinOverrideMgr(
			parent,
			configurableDef,
			this.reqData,
			devicePins,
			peripheralFilter,
			devicePinNameToFilter,
			userPref,
			unavailablePins,
			pinMap,
			formattersMap);

		this.conflictMgr = new PinAllowConflictsMgr(
			parent,
			_.extend(_.clone(configurableDef),
				{ name: "$assignAllowConflicts", displayName: "Assign Pin (Ignoring Conflicts)" }),
			this.reqData,
			devicePins,
			userPref,
			pinMap,
			formattersMap,
		);

		new PinSuggestSolutionMgr(
			parent,
			_.extend(_.clone(configurableDef), { name: "$suggestSolution", displayName: "Suggest Solution" }),
			this.reqData,
			devicePins,
			userPref,
			pinMap,
			formattersMap,
		);

		this.usedMgr = new PinUsedMgr(parent, formattersMap, this.reqData, used);
	}

	public getOverrideMgr() {
		return this.overrideMgr;
	}

	public getConflictMgr() {
		return this.conflictMgr;
	}

	public getUsedMgr() {
		return this.usedMgr;
	}

	public getRequirementData() {
		return this.reqData;
	}
}
