import * as _ from "lodash";
import { toPinReqs } from "../adaptModulePinReqs";
import { isPinInterfaceRequirement } from "../funcs";
import { OptimizablePinMgr } from "../optimizablePin";
import { fetchPinConnections } from "../hardwareMember";
import { InterfaceInstanceMgr } from "../interfaceInstance";
import { OptimizablePinMemberMgr, ExtendedPinMemberMgr } from "../pinObjectMembers";
import { format } from "../../formatting/moduleFormatter";
import { PinMgr } from "../pin";
import { Requirements } from "./requirements";
import { InterfaceInstanceMemberMgr } from "../interfaceInstanceMemberMgr";
import { AnyMemberMgr } from "../member";
import { InterfaceRequirement, PinInterfaceRequirement, InterfaceExtensionRequirement } from "public/defs";
import { OptimizableInterfaceAdapterMgr } from "../optimizableInterfaceAdapter";

type InterfaceRequirementsType = InterfaceRequirement | PinInterfaceRequirement | InterfaceExtensionRequirement;

export class InterfaceRequirements
	extends Requirements<"pinmuxRequirements"> {

	protected adaptReqs(reqs: InterfaceRequirementsType[]) {

		// Don't honour hidden on interface requirements.
		// Unlike normal configurables, these are never irrelevant as they always
		// have an impact on resource allocation and can lead to solver errors.

		return _.map(reqs, (req) => ({ ...req, hidden: false }));
	}

	protected categorizeReqs(
		reqs: InterfaceRequirementsType[],
		cause?: AnyMemberMgr,
	) {
		if (cause === this.instanceMgr.hardwareMemberMgr) {
			// $hardware changing should force all to update
			return {
				newReqs: reqs,
				removedReqs: this.currentRequirements,
			};
		} else {
			// make a copy of the prev reqs as the initial removed reqs so we can remove un-removed reqs from here one by one
			const removedReqs = _.clone(this.currentRequirements);
			const { newReqs, updateReqs, recreateReqs } = _.groupBy(
				reqs,
				(req) => {
					const matchingPrevReq = _.head(_.remove(removedReqs, (pr) => pr.name === req.name));
					if (matchingPrevReq) {
						if (!_.isEqual(matchingPrevReq, req)) {
							if (isEqualExcludingPins(matchingPrevReq, req)) {
								return "updateReqs";
							} else {
								return "recreateReqs";
							}

						} else {
							return "unchangedReqs"; // filtered out and not returned
						}
					} else {
						return "newReqs";
					}
				},
			);
			return {
				removedReqs: [...removedReqs ?? [], ...recreateReqs ?? []],
				newReqs: [...newReqs ?? [], ...recreateReqs ?? []],
				updateReqs,
			};
		}
	}

	protected getFunctionName(): "pinmuxRequirements" {
		return "pinmuxRequirements";
	}

	protected resolve(newReqs: InterfaceRequirementsType[], updatedReqs: InterfaceRequirement[]) {
		_.each(newReqs, (req) => {
			if ("extend" in req) {
				return this.resolveExtendedReq(req);
			} else if (!isPinInterfaceRequirement(req, this.runtime.getPinOptimizations().isOptimizable(req.interfaceName))) {
				return this.resolveNewPerfReq(req);
			} else {
				return this.resolveOptimizablePinReq(req);
			}
		});

		_.each(updatedReqs, (req) => {
			return this.updatePins(req);
		});
	}

	private resolveExtendedReq(req: InterfaceExtensionRequirement) {

		// Get the interface manager that we're going to extend

		const interfaceInstanceMgr = this.runtime.interfaceMap.get(req.extend);
		if (!interfaceInstanceMgr) {
			throw new Error("tried to extend an unknown peripheral requirement");
		}

		// Create a fake interface requirement so we can construct a pin requirement from it
		// Note that toPinReqs returns an array, but we know we have only one pin requirement

		const solverReq = interfaceInstanceMgr.getSolverRequirement();
		const pinReq = _.first(toPinReqs(
			solverReq.interfaceName, [req], !!solverReq.canShareWith, this.runtime.getDeviceData(),
		).pinReqs);

		// Create a pin manager for this requirement, and then a member manager to manage it as a member
		// of this module instance vs the interface instance

		const newPinMgr = new PinMgr(
			this.runtime,
			(options) => format(this.instanceMgr, options, pinReq.name),
			pinReq.name,
			interfaceInstanceMgr.getPeripheralFilter(),
			pinReq.interfacePins,
			fetchPinConnections(req.signalTypes, this.instanceMgr.managedObject.$hardware),
			_.extend({}, pinReq.solverOptions, { preferredTypes: req.signalTypes }),
			this.instanceMgr,
			this.instanceMgr.getID() + ".",
			false,
			this.instanceMgr,
			pinReq.used || true,
			pinReq.config || [],
		);

		return new ExtendedPinMemberMgr(
			newPinMgr,
			req,
			this.instanceMgr,
			interfaceInstanceMgr,
			this.runtime.getFormattersMap(),
		);

	}

	private resolveNewPerfReq(req: InterfaceRequirement) {
		const { iface, pinReqs } = this.toPinReqs(req);
		const newInterfaceInstMgr = this.runtime.getPinOptimizations().isOptimizable(iface.name)
			? new OptimizableInterfaceAdapterMgr(this.runtime, iface, this.instanceMgr, req)
			: new InterfaceInstanceMgr(this.runtime, iface, this.instanceMgr, req);
		newInterfaceInstMgr.newPinReqs(pinReqs, this.instanceMgr.managedObject.$hardware, req.signalTypes);
		return new InterfaceInstanceMemberMgr(newInterfaceInstMgr, this.runtime.getFormattersMap(), req, this.instanceMgr);
	}

	private resolveOptimizablePinReq(req: PinInterfaceRequirement) {
		const inst = new OptimizablePinMgr(
			this.runtime,
			(options) => format(this.instanceMgr, options, req.name),
			req.name,
			{
				canShareWith: req.canShareWith ? req.canShareWith : undefined,
				filter: req.filter,
				preferredTypes: req.signalTypes,
			},
			fetchPinConnections(req.signalTypes, this.instanceMgr.managedObject.$hardware),
			this.instanceMgr,
		);

		return new OptimizablePinMemberMgr(
			inst,
			this.runtime.getFormattersMap(),
			req,
			this.instanceMgr,
		);
	}

	private updatePins(req: InterfaceRequirement) {
		const prevReq = _.find(this.currentRequirements, (r) => r.name === req.name) as InterfaceRequirement;
		const newPinReqs = this.toPinReqs(req).pinReqs;
		const prevPinReqs = this.toPinReqs(prevReq).pinReqs;

		const unchanged = _.intersectionWith(newPinReqs, prevPinReqs, _.isEqual);

		const interfaceInstanceMgr = this.instanceMgr.memberMgrs[req.name] as any as InterfaceInstanceMemberMgr;
		interfaceInstanceMgr.valueObjectMgr.newPinReqs(
			newPinReqs, this.instanceMgr.managedObject.$hardware, req.signalTypes, unchanged);
	}

	private toPinReqs(req: InterfaceRequirement) {
		return toPinReqs(req.interfaceName, req.resources, !!req.canShareWith, this.runtime.getDeviceData());
	}
}

function isEqualExcludingPins(a: InterfaceRequirementsType, b: InterfaceRequirementsType) {
	return _.isEqual({ ...a, resources: undefined }, { ...b, resources: undefined });
}
