import * as _ from "lodash";
import { InstanceMemberMgr } from "./instanceMemberMgr";
import { ModuleInstanceMgr, ModuleInstanceMgrFactory } from "../moduleInstance";
import { SharedModuleInstanceRequirement, InstanceArgs, InstanceArgsValue, ImpliedConnection } from "public/defs";
import { LeafNode, SharedAssignLeafNode, createUIStatements, ViewNode } from "../viewNodes";
import { Runtime } from "../../resources/runtime";
import { SetSource, InstanceArgType } from "../member";
import { SerializationOptions } from "../../scripting/toScript";
import { Assignment, Statement } from "../../scripting/serialize";
import { ModuleInstance } from "public/runtime";
import { ChangesToChild, isAssignable } from "../moduleRequirements/sharedModuleCompatibility";
import { minimumNodeSize } from "../../../components/graphableModules/layout/constants";
import { findValidPosition } from "../positionMemberMgr";
import { PortMemberMgr } from "../portMemberMgr";

export class SharedInstanceMemberMgr
	extends InstanceMemberMgr<ModuleInstanceMgr, SharedModuleInstanceRequirement> {

	private readonly sharedAssignLeafNode: LeafNode;
	private readonly initialAssignSeq: number;
	private disposeSharedRef: () => void;

	constructor(
		runtime: Runtime,
		valueObjectMgr: ModuleInstanceMgr,
		def: SharedModuleInstanceRequirement,
		instanceMgr: ModuleInstanceMgr,
		collapsed: boolean,
	) {
		super(null, runtime, def, instanceMgr, { collapsed });
		this.sharedAssignLeafNode = new SharedAssignLeafNode(this);
		const child = valueObjectMgr ?? createNew(runtime, def, instanceMgr);
		this.set(child.managedObject, SetSource.TOOL_INTERNAL);
		this.initialAssignSeq = this.getUserModSeqNum();
		this.checkForHiddenArgs();
	}

	// Creates a new shared child instance and replaces the current assignment with it

	public createNew() {
		const newChild = createNew(this.runtime, this.def, this.parentObjectMgr);
		this.set(newChild.managedObject, SetSource.USER_ASSIGN);
	}

	public getInstancesOfValidType() {
		const selectedInstance = this.valueObjectMgr;
		const instancesContainer = selectedInstance.getModuleMgr();
		return _.filter(instancesContainer.instances, (inst) => inst.canBeShared());
	}

	public update(newReq: SharedModuleInstanceRequirement) {

		if (!_.isEqual(newReq.requiredArgs, this.def.requiredArgs)) {
			this.valueObjectMgr.removeReqArgs(this.def.requiredArgs, this.parentObjectMgr);
			this.def.requiredArgs = newReq.requiredArgs;
			this.valueObjectMgr.setValueFromRequiredArgs(this.def.requiredArgs, this.parentObjectMgr);
			this.checkForHiddenArgs();
		}

		if (!_.isEqual(newReq.impliedConnections, this.def.impliedConnections)) {
			this.valueObjectMgr.removeImpliedConnections(this.parentObjectMgr, this.def.impliedConnections);
			this.def.impliedConnections = newReq.impliedConnections;
			this.valueObjectMgr.addImpliedConnections(this.parentObjectMgr, this.def.impliedConnections);
		}
	}

	public getUIOptions() {
		return _.chain(this.getInstancesOfValidType())
			.map((inst) => {
				const compatible = inst === this.valueObjectMgr ||
					isAssignable(ChangesToChild.ALLOWED, inst, this.def);
				return {
					name: inst.getName(),
					displayName: inst.getName(),
					compatible: compatible ? "enabled" : "disabled",
					description: !compatible && "Incompatible with required settings",
				};
			})
			.groupBy((option) => option.compatible)
			.value();
	}

	public override generateScriptStatements(rvalue: string, options: SerializationOptions) {
		// Since shared members supply required args, they are assigned in order as part of the child's
		// configuration.  As such, parentIdentifier in the super class definition is actually the child 
		// being assigned (and thus I renamed the parameter to rvalue).  It's being assigned to (ie the
		// lvalue) the real parent manager

		// if we're cloning this instance than we don't care about the parent
		if (options.cloneInstance) {
			return [];
		}
		const identifiers = this.runtime.getSerializationContext().getModuleInstanceIdentifiers();
		const parentIdentifer = identifiers.get(this.parentObjectMgr);
		const lvalue = this.createScriptIdentifier(parentIdentifer);
		let statements: Statement[] = [
			...this.parentObjectMgr.getAddInstanceStatements(),	// Ensure parent has been added before accessing
			new Assignment(lvalue, rvalue),
		];

		// Optionally serialize the UI state too

		if (options.includeUIState) {
			statements = [
				...statements,
				...createUIStatements(parentIdentifer, this),
			];
		}

		return statements;
	}

	public override isUserModified() {
		// a shared member is only considered modified it was set to a different value
		// i.e a.sharedMember = b; // user modified 
		// a.sharedMember.val = "foo" // not user modified
		return this.getUserModSeqNum() !== this.initialAssignSeq;
	}

	public override getTitleNode(): LeafNode {
		return this.sharedAssignLeafNode;
	}

	public override getChildren(): ViewNode[] {
		return ([
			...this.valueObjectMgr.getViewNodes(),
		]);
	}

	public override remove(): void {
		this.clearInvalidAssignment();
		this.removeSharedBy();
	}

	public override setValueFromRequiredArgs(): void {
		throw new Error("Cannot use requiredArgs to set members on an indirectly shared descendant");
	}

	public override setValueFromArgs(args: InstanceArgsValue, argType: InstanceArgType): void {
		if (argType === InstanceArgType.USER) {
			if (this.runtime.getManager(args as unknown as ModuleInstance)) {
				this.set(args, SetSource.USER_ARGS);
			} else {
				super.setValueFromArgs(args as InstanceArgs, argType);
			}
		} else {
			throw new Error("Cannot use args to set members on an indirectly shared descendant");
		}
	}

	protected override shouldSerialize() {
		return true;
	}

	protected override validateValue(newInst: ModuleInstance, forceWrite: boolean, source: SetSource) {
		super.validateValue(newInst, forceWrite, source);

		if (newInst !== this.value &&
			!isAssignable(ChangesToChild.ALLOWED, this.runtime.getManager(newInst), this.def)
		) {
			throw new Error("Incompatible with required settings");
		}
	}

	protected override onSet(newInst: ModuleInstance) {

		const newInstManager = this.runtime.getManager(newInst);
		if (newInstManager === this.valueObjectMgr) {
			// nothing to do here, and will cause problems with unlinking
			return;
		}

		// Remove the old connection

		if (this.valueObjectMgr) {
			this.removeSharedBy();
		}

		// Setup the new connection
		// pass along shareWithByDefault only if this is the initial assignment.  That allows users to assign something
		// different (hence the "by default").

		this.valueObjectMgr = newInstManager;
		const shareWithByDefault = _.isUndefined(this.initialAssignSeq) ? this.def.shareWithByDefault : undefined;
		this.disposeSharedRef = this.valueObjectMgr.addSharedBy(this.parentObjectMgr, shareWithByDefault);

		// Apply requiredArgs and impliedConnections

		if (this.def.requiredArgs) {
			this.valueObjectMgr.setValueFromRequiredArgs(
				this.def.requiredArgs,
				this.parentObjectMgr,
			);
		}
		this.valueObjectMgr.addImpliedConnections(this.parentObjectMgr, this.def.impliedConnections);
	}

	protected override checkSharedInstance(name: string) {
		return this.def.name === name;
	}

	private removeSharedBy() {
		if (this.def.requiredArgs) {
			this.valueObjectMgr.removeReqArgs(this.def.requiredArgs, this.parentObjectMgr);
		}
		if (this.def.impliedConnections) {
			this.valueObjectMgr.removeImpliedConnections(this.parentObjectMgr, this.def.impliedConnections);
		}
		this.disposeSharedRef();
	}
}

function createNew(runtime: Runtime, req: SharedModuleInstanceRequirement, parent: ModuleInstanceMgr) {
	const mod = runtime.getModuleMgr(req.moduleName).module;
	const child = ModuleInstanceMgrFactory.createInstance(
		runtime,
		mod,
		false,
		{});

	setRelativePosition(parent, child, req.impliedConnections);
	return child;
}

function setRelativePosition(parent: ModuleInstanceMgr, child: ModuleInstanceMgr, impliedConnections: ImpliedConnection[]): void {

	const [outputs, inputs] = _.partition(impliedConnections, (connection) => {
		const ownPort = parent.memberMgrs[connection.ownPort] as PortMemberMgr;
		if (!(ownPort instanceof PortMemberMgr)) {
			throw new Error(`sharedInstanceMgr: ownPort '${connection.ownPort}' not found`);
		}

		return ownPort.def.type === "output";
	});

	// spacing between parent and child
	let spacing: number;
	if (inputs.length > 0 && outputs.length > 0) {
		// Place below
		spacing = 0;
	} else if (outputs.length > 0) {
		// Place on right
		// 3X looked reasonable - nothing special
		spacing = minimumNodeSize * 3;
	} else {
		// Place on left
		spacing = minimumNodeSize * -3;
	}

	// Set the newly pulled in child to be a reasonable distance away from the parent.  Otherwise, they likely will
	//  appear on top of each other

	const parentPosition = parent.memberMgrs.$position;
	const childPosition = child.memberMgrs.$position;
	if (parentPosition && childPosition) {
		const position = parentPosition.getValue();
		childPosition.set(
			findValidPosition(
				parent.getModuleMgr(),
				[position[0] + spacing, position[1]],
				child.getID()
			),
			SetSource.TOOL_INTERNAL,								// prevents promotion to "user changed"
		);
	}
}
