import * as _ from "lodash";
import { IDialogValidationLogger, IValidationLogger } from "public/defs";
import { ModuleInstance, RuntimeInstance, RuntimeObject } from "public/runtime";

import { FormattersMap } from "../formatting/formattersMap";
import { FormattableObjects } from "../formatting/formattingTypes";
import { AObjectMgr } from "./object";
import { IValidatable, Validation, Validations } from "./validations";

type ManagersMap = Map<RuntimeObject, AObjectMgr<RuntimeObject>>;

export function getValidatableObjs(
	managersMap: ManagersMap,
	inst: RuntimeInstance,
	member?: string | string[],
): IValidatable[] {
	const mgr = managersMap.get(inst);
	if (!mgr) {

		throw new Error("Unknown instance");
	}

	if (member) {

		const members = _.isArray(member) ? member : [member];

		return _.map(members, (m) => {
			const memberMgr = mgr.memberMgrs[m];
			if (!memberMgr) {
				throw new Error(`Unknown member: ${m}`);
			}
			return memberMgr;
		});

	} else {
		return [mgr];
	}
}

// explicitly implement as function instead of class to avoid exposing internal members to meta content.
function newValidationImpl(
	managersMap: ManagersMap,
	validations: Validations,
	formattersMap: FormattersMap,
	forDialog: boolean,
): IValidationLogger | IDialogValidationLogger {

	function log(
		type: "logError" | "logWarning" | "logInfo" | "logDialogError",
		message: string, inst: ModuleInstance,
		member?: string | string[],
	) {
		_.each(getValidatableObjs(managersMap, inst, member), (obj) => validations[type](message, obj));
	}

	function logError(message: string, inst: ModuleInstance, member?: string | string[]): void {
		log("logError", message, inst, member);
	}

	function logDialogError(message: string, inst: ModuleInstance, member?: string | string[]): void {
		log("logDialogError", message, inst, member);
	}

	function logWarning(message: string, inst: ModuleInstance, member?: string | string[]): void {
		log("logWarning", message, inst, member);
	}

	function logInfo(message: string, inst: ModuleInstance, member?: string | string[]): void {
		log("logInfo", message, inst, member);
	}

	function getReference(inst: FormattableObjects, member?: string): string {
		return formattersMap.getEncodingTag(inst, member);
	}

	if (forDialog) {
		return {
			logError: logDialogError,
			logWarning,
			logInfo,
			getReference,
		};
	}

	return {
		logError,
		logWarning,
		logInfo,
		getReference,
	};
}

export function newValidation(
	managersMap: ManagersMap,
	validations: Validations,
	formattersMap: FormattersMap,
): IValidationLogger {
	return newValidationImpl(managersMap, validations, formattersMap, false) as IValidationLogger;
}

export function newDialogValidation(
	managersMap: ManagersMap,
	validations: Validations,
	formattersMap: FormattersMap,
): IDialogValidationLogger {
	return newValidationImpl(managersMap, validations, formattersMap, true) as IDialogValidationLogger;
}

// legacy validation interface
export interface LegacyInstanceValidation {
	/**
	 * Validation messages at a module;
	 */
	$instance: Validation;

	/**
	 * Instance {@link Member} and/or {@link Group} names to validation message.
	 */
	[name: string]: Validation;
}
