import * as _ from "lodash";
import { Statement } from "./serialize";
import { ArgTypes, defaultRTOS } from "../args/argTypes";
import { scriptDirProductName } from "../product/loadResources";
import { Runtime } from "../resources/runtime";
import { assertUnreachable } from "../utils";

type IPortableArgs
	= Pick<ArgTypes, "board" | "device" | "package" | "part" | "product" | "ccxxImageMode" | "context" | "rtos">;

function joinArgNameValue(argName: string, argValue: string | boolean) {
	return _.isBoolean(argValue) ? `--${argName}` : `--${argName} "${argValue}"`;
}

export function createCLIArgs(runtime: Runtime, forceDevice = false) {

	const deviceData = runtime.getDeviceData();
	const args: IPortableArgs = {};

	if (deviceData.board && !forceDevice) {
		args.board = deviceData.board.source;
	}
	if (forceDevice || !deviceData.board ||
		deviceData.board.device !== deviceData.device ||
		deviceData.board.part !== deviceData.part ||
		deviceData.board.package !== deviceData.package
	) {
		args.device = deviceData.device;
		args.package = deviceData.package;
		args.part = deviceData.part;
	}
	if (_.some(runtime.getProducts(), (p) => p.file.contexts)) {
		args.context = runtime.getName();
	}

	if (runtime.isCCXXImageMode()) {
		args.ccxxImageMode = true;
	}

	if (runtime.getRTOS() !== defaultRTOS) {
		args.rtos = runtime.getRTOS();
	}

	args.product
		= _.chain(runtime.getProducts())
			.filter((p) => p.file.name !== scriptDirProductName)
			.filter((p) => !p.file.isBuiltIn)
			.map((p) => `${p.file.name}@${p.file.version}`)
			.value();

	const cliArgs = _.join(_.flatMap(args, (argValue, argName) => {
		if (_.isArray(argValue)) {
			return _.map(argValue, (v) => joinArgNameValue(argName, v));
		} else {
			return joinArgNameValue(argName, argValue);
		}
	}), " ");

	return cliArgs;
}

// Note, this function doesn't need to be asynchronous.  However it previously had to be as it had 
// to fetch a template first.  I'd like to keep it async for now, as I can see other changes down 
// the road also requiring it to be async, and it's easier to keep the async-ness now vs having to 
// change everything and then change it back later.

export function toScript(runtime: Runtime, scriptPath: string) {
	const statements = runtime.serialize({}, scriptPath);
	const cliArgs = createCLIArgs(runtime);
	const versions = JSON.stringify(runtime.getDeviceData().versions);
	return scriptTemplate(statements, cliArgs, versions);
}

export function scriptTemplate(statements: Statement[], cliArgs?: string, versions?: string) {
	return [
		...getHeaderCommentLines(cliArgs, versions),
		...toStatementLines(statements),
	].join("\n") + "\n";
}

function getHeaderCommentLines(cliArgs: string, versions: string) {
	return [
		"/**",
		" * These arguments were used when this file was generated. They will be automatically applied on subsequent loads",
		" * via the GUI or CLI. Run CLI with '--help' for additional information on how to override these arguments.",
		` * @cliArgs ${cliArgs}`,
		` * @versions ${versions}`,
		" */",
	];
}

function toStatementLines(statements: Statement[]) {
	let alignment = 0;
	return _.map(statements, (statement, index) => {
		switch (statement.type) {
			case "blockComment":
				alignment = calculateSectionAlignment(statements, index);
				return `\n${toComment(statement.comment)}`;
			case "blankLine":
				alignment = calculateSectionAlignment(statements, index);
				return "";
			case "functionCall":
				return `${statement.value};`;
			case "assignment":
				return `${_.padEnd(statement.lvalue, alignment, " ")} = ${statement.rvalue};`;
			default:
				assertUnreachable(statement);
		}
	});
}

// calculate where the = statements should occur
function calculateSectionAlignment(statements: Statement[], sectionStart: number) {
	const sectionEnd = _.findIndex(statements, (statement) => {
		return statement.type === "blockComment" || statement.type === "blankLine";
	}, sectionStart + 1);
	return _.chain(_.slice(statements, sectionStart, sectionEnd === -1 ? undefined : sectionEnd))
		.map((statement) => statement.type === "assignment" ? _.size(statement.lvalue) : 0)
		.max()
		.value();
}

// Split the text into a block comment with no line going over 120 characters
function toComment(text: string) {
	const maxLineLength = 120 - 3; // space * space at the beginning

	let comment = "/**";
	while (_.size(text) > maxLineLength) {
		const line = text.substring(0, _.lastIndexOf(text, " ", maxLineLength));
		text = text.substring(_.size(line) + 1);
		comment += "\n * " + line;
	}
	comment += "\n * " + text + "\n */";
	return comment;
}

export const enum MigrationType {
	NONE = 0,			// Not migrating at all - equal to falsy
	DEFAULT,			// part/package migration, device->device or board->board
	BOARD_TO_DEVICE,	// board->device
}

export interface SerializationOptions {
	includeUIState: boolean;
	includeNonSerializable: boolean; // serialize objects set to nonSerializale, only for history stack
	deviceDataMigration: MigrationType;
	lockPinmux: boolean;
	cloneInstance: boolean;
}

export const defaultSerializationOptions: SerializationOptions = {
	includeUIState: false,
	includeNonSerializable: false,
	deviceDataMigration: MigrationType.NONE,
	lockPinmux: false,
	cloneInstance: false,
};
