import * as _ from "lodash";
import { AdaptedDeviceInfo } from "dataInterfaces";
import { InterfaceResourceRequirement, StandardConfigurable } from "public/defs";
import DeviceData = require("dataInterfaces");
import { getDisplayName } from "../utils";

export interface PinReq {
	name: string;
	displayName?: string;
	interfacePins: DeviceData.InterfacePin[];
	solverOptions?: {
		canShareWith?: string,
		filter?: (devicePin: DeviceData.DevicePin, peripheralPin: DeviceData.PeripheralPin) => boolean,
	};
	used: boolean;
	config: StandardConfigurable[];
	legacyNames?: string[];
}

export function toPinReqs(
	interfaceName: string,
	resources: (InterfaceResourceRequirement | string)[],
	interfaceShared: boolean,
	deviceData: AdaptedDeviceInfo,
): { iface: DeviceData.Interface, pinReqs: PinReq[] } {

	const iface = deviceData.interfaces[interfaceName];
	if (!iface) {
		throw new Error(`unknown interface: "${interfaceName}"`);
	}

	// process optional pins requirements
	if (resources) {

		const findIfacePin = (ifacePinName: string) => {
			const ifacePin = iface.interfacePins[ifacePinName];
			if (!ifacePin) {
				throw new Error(`unknown resource interface "${ifacePinName}" on interface "${iface.name}"`);
			}
			return ifacePin;
		};

		const pinReqs = _.map(resources, (pinReq) => {
			if (typeof pinReq === "string") {
				const ifacePin = findIfacePin(pinReq);

				return {
					name: ifacePin.name,
					interfacePins: [ifacePin],
					used: true,
					config: [],
				};
			} else {
				const interfaceNames = pinReq.interfaceNames || [pinReq.name];
				const ifacePins = _.map(interfaceNames, (name) => findIfacePin(name));
				return {
					name: pinReq.name,
					displayName: getDisplayName(pinReq, false),
					interfacePins: ifacePins,
					solverOptions: {
						canShareWith: interfaceShared ? pinReq.canShareWith : undefined,
						filter: pinReq.filter,
					},
					used: _.isUndefined(pinReq.used) ? true : pinReq.used,
					config: pinReq.config || [],
					legacyNames: pinReq.legacyNames,
				};
			}
		});

		return { iface, pinReqs };
	} else {
		// default to all pins
		const pinReqs = _.map(iface.interfacePins, (ifacePin) => {
			return {
				name: ifacePin.name,
				interfacePins: [ifacePin],
				used: true,
				config: [],
			};
		});
		return { iface, pinReqs };
	}
}
