import * as _ from "lodash";
import { MultiInstanceReferenceConfigurable } from "public/defs";
import { ModuleInstance, RuntimeObject } from "public/runtime";
import { Runtime } from "../../resources/runtime";
import { getScriptIdentifier } from "../../scripting/serialize";
import { SetSource } from "../member";
import { ModuleInstanceMgr } from "../moduleInstance";
import { AObjectMgr } from "../object";
import { BaseInstanceReferenceConfigurableMgr } from "./baseInstanceReferenceConfigurableMgr";
import { ConfigurableComponent } from "./configurableComponent";

export class MultiInstanceReferenceConfigurableMgr
	extends BaseInstanceReferenceConfigurableMgr<ModuleInstance[], MultiInstanceReferenceConfigurable>
{
	public readonly ui = ConfigurableComponent.MultiInstanceReferenceConfigurable;
	constructor(
		parentObjectMgr: AObjectMgr<RuntimeObject>,
		def: MultiInstanceReferenceConfigurable,
		runtime: Runtime,
	) {
		super(
			parentObjectMgr,
			runtime.getFormattersMap(),
			def,
			[],
			runtime,
		);
	}

	public getUIOptions() {
		const enabledOptions = this.getEnabledOptions();
		const selectedOptionName = _.map(this.getValueMgrs(), (mgr) => mgr.getID());
		return { enabledOptions, selectedOptionName };
	}

	protected override getRValue() {
		return "[" + _.map(this.getValueMgrs(), getScriptIdentifier).join(", ") + "]";
	}

	protected override validateValue(value: ModuleInstance[], forceWrite: boolean, source: SetSource) {
		super.validateValue(value, forceWrite, source);
		if (_.some(this.getValueMgrs(value), (mgr) => !mgr)) {
			throw new Error("Unknown module instance assigned");
		}
	}

	protected override getValueMgrs(value = this.value) {
		return _.map(value, (inst) => this.runtime.getManager(inst));
	}

	protected onModuleRemoved = (inst: ModuleInstanceMgr) => {
		const newValue = _.chain(this.getValueMgrs())
			.difference([inst])
			.map((i) => i.managedObject)
			.value();
		this.set(newValue, SetSource.USER_ASSIGN);
	}
}
