// Contains class providing common facilities for all member managers

import * as _ from "lodash";
import { AObjectMgr } from "./object";
import {
	Member as MemberDef,
	UIState,
	InstanceArgsValue,
} from "public/defs";
import { RuntimeObject } from "public/runtime";
import { createChildIdentifier, createValidationSuppressionStatement, Statement } from "../scripting/serialize";
import { FormattersMap } from "../formatting/formattersMap";
import {
	forbiddenModification,
	assertUnreachable,
	getDisplayName,
	getValidationKey,
	convertUnknownToError,
} from "../utils";
import { InternalValidationLogger, IValidatableMember, Validations } from "./validations";
import { ConfigurableMgr } from "./configurables/configurableMgr";
import { SerializationOptions } from "../scripting/toScript";
import { internalBoundary } from "../niceExceptions";
import { InvalidAssignment, shouldCapture } from "./invalidAssignment";
import { ModuleInstanceMgr, OnModuleChangedType } from "./moduleInstance";
import { isRunningUserScript, isScriptingEnabled } from "../scripting/scriptingGuard";
import { AccessType, validateDeprecatedAccess } from "../deprecatedAccessGuard";
import { configurationChanged } from "../changeNumber";

export type AnyMemberMgr = AMemberMgr<any>;

export const enum InstanceArgType {
	META, // This is when args are applied normally
	USER, // This is for when args are applied through the addInstance() call by the user
	REAPPLY, // This is when middle parent recreates child so now all parents above it need to re-apply their args
}

/**
 * Base class extended by all members. Defines related member on runtime object and manages observing changes
 * to it's value.
 */
export abstract class AMemberMgr<
	ValueType,
	RuntimeObjectType extends RuntimeObject = RuntimeObject,
	MemberDefinition extends MemberDef = MemberDef,
	LValueType = ValueType> implements IValidatableMember {

	/**
	 * current ui state of the member
	 * Must be readonly as we have a proxy object that tracks it
	 */
	public readonly uiState: UIState;

	public requiredByParent: ModuleInstanceMgr[] = [];

	/**
	 * actual value of the member variable as seen on the runtime instance
	 */
	protected value: ValueType;

	// track the actual cause if the source is meta assign
	protected valueMetaAssignCause?: MetaAssignCause;
	// source of the value assignment if not default value
	protected valueAssignSource?: SetSource = null;
	// remember the read-only-ness right before we become required by parent
	protected readOnlyBeforeRequiredByParent: boolean | string = false;
	// remember the last value set by an arg, if never set by arg, then it would be null
	protected lastArgValue: ValueType = null;
	// last value set by onChange handler
	protected lastValueSetByOnChange?: { configurableName: string, value: ValueType } = null;
	// last user modification
	private userModSeqNum = -1;
	// Last change of any kind
	private anyModSeqNum = -1;
	// source of the current readonly setting
	private readOnlyCause?: MetaAssignCause;
	// track invalid assignments
	private invalidAssignment: InvalidAssignment = null;
	// last source for a value not set by the user
	private lastNonUserSetSource?: SetSource = null;
	// last value not set by the user
	private lastNonUserSetValue: ValueType;
	// track what the user mod seq num is at force write.
	private userModSeqNumAtForceWrite = -1;
	// track the last value that was forced by args/meta-assign and overwritten
	private lastOverwrittenReadOnlyValue: ValueType = null;
	// managed object for meta-content to access uiState
	private managedUIState: UIState = null;

	constructor(
		public parentObjectMgr: AObjectMgr<RuntimeObjectType>,
		protected readonly formattersMap: FormattersMap,
		public readonly def: MemberDefinition,
		protected readonly initValue: ValueType,
	) {
		// initialize
		this.initValue = this.transform(initValue);
		this.value = this.initValue;

		this.lastNonUserSetValue = this.value;
		this.uiState = {
			hidden: getMemberDefaultHiddenState(this.def),
			readOnly: getMemberDefaultReadonlyState(this.def),
		};

		// link ourselves to the parent.
		this.parentObjectMgr.addMember(this);
	}

	public getDisplayName(displayScriptName: boolean) {
		return getDisplayName(this.def, displayScriptName);
	}

	public getToolTip(_validations: Validations): string {
		if (!_.isEmpty(this.requiredByParent)) {
			return "Value was locked by " +
				_.chain(this.requiredByParent)
					.uniq()
					.map((p) => this.formattersMap.getEncodingTag(p.managedObject))
					.join(", ")
					.value();
		} else if (_.isString(this.uiState.readOnly)) {
			return this.uiState.readOnly;
		} else if (this.uiState.readOnly && this.readOnlyCause) {
			return `Value was locked by ${this.formattersMap.getEncodingTag(
				this.readOnlyCause.configurable.getParentRuntimeObj(), this.readOnlyCause.configurable.def.name)
				}`;
		}
		return this.def.description || "";
	}

	// Returns a hash code the UI can use to determine if anything has changed since the last time.  If the returned 
	// hash string is unchanged, no re-render is necessary.  If it returns null, always consider it changed and 
	// re-render.

	public getUIHash(validations: Validations): string | null {
		if (validations.getValidation(this)) {
			return null;
		}
		return `${this.value}${this.uiState.readOnly}${this.uiState.hidden}`;
	}

	public get(): LValueType {
		if (this.def.deprecated) {
			validateDeprecatedAccess(AccessType.READ);
		}

		return this.toLValue();
	}

	// Used by the proxy object when mapping values to something for JSON.jsonify().  By default, just use the 
	// underlying value

	public jsonify(): any {
		return this.get();
	}

	/**
	 * Set a member value. Enforce any modification restrictions, run validate.
	 * @param val - value to set
	 * @param source - source that originated the change
	 * @param forceWrite - force write a potentially a readOnly value
	 */
	public set(val: any, source: SetSource, forceWrite = false, reasonIfInvalid?: string, oldDisplayName?: string) {
		if (this.validateSet(source, val, forceWrite, reasonIfInvalid, oldDisplayName)) {
			val = this.transform(val);
			const isValueChanged = !this.isEqual(val);

			if (isValueChanged) {
				this.onNewValueWritten(source, forceWrite, val);
			} else {
				this.onSameValueReWritten(source);
			}
		}
	}

	/**
	 * Clean up managed parent object and remove from parent.
	 */
	public remove() {
		this.clearInvalidAssignment();
	}

	public resetDefaultUIState() {
		this.uiState.hidden = getMemberDefaultHiddenState(this.def);
		this.setReadOnly(getMemberDefaultReadonlyState(this.def));
	}

	public setReadOnly(val: boolean | string) {
		this.uiState.readOnly = val;
	}

	public validate(validationLogger: InternalValidationLogger) {
		const wasIncorrectlyModifiedByUser =
			this.uiState.readOnly
			&& this.isUserModified()
			&& !this.wasForceWritten() // use force write to ignore warnings
			&& this.lastOverwrittenReadOnlyValue !== null
			&& this.value !== this.lastOverwrittenReadOnlyValue;

		const wasIncorrectlyModifiedByOnChangeInScript =
			!_.isEmpty(this.requiredByParent)
			&& this.valueAssignSource === SetSource.META_ASSIGN
			&& this.lastOverwrittenReadOnlyValue !== null
			&& this.value !== this.lastOverwrittenReadOnlyValue;

		if (wasIncorrectlyModifiedByUser || wasIncorrectlyModifiedByOnChangeInScript) {
			if (!_.isEmpty(this.requiredByParent)) {
				validationLogger.logWarning(
					"This member is locked by " +
					_.chain(this.requiredByParent)
						.uniq()
						.map((p) => this.formattersMap.getEncodingTag(p.managedObject))
						.join(", ")
						.value()
					+ ", and has changed. " +
					"This is caused by an incorrect text edit of the script or backwards compatibility discrepancy.",
					this);
			} else if (!this.readOnlyCause) {

				// This can happen when
				// 1) Read only by default is incorrectly over written by user edit
				// 2) Was writable but now becomes read only, thus backwards compatibility
				// 3) Was readonly by default but some change made it writable, but that causing change
				// was not serialized. This is still problematic because the UI is set to read only with
				// user modified or side effect value set. How problematic is hard to determine, it will
				// depend on if and how intuitively the user can get out of that state.  

				validationLogger.logWarning(
					"Read only value changed. " +
					"This is likely caused by an incorrect text edit of the script, " +
					"a backwards compatibility discrepancy, and/or by a unsaved change that temporarily made this value writable.",
					this);

			} else if (isMetaCauseAssignCurrent(this.readOnlyCause) && this.userModSeqNum > this.readOnlyCause.userModSeqNum) {
				// we can definitively conclude it was user edit or
				// backwards compatibility issue.
				validationLogger.logWarning(
					`This member is locked by ${this.formattersMap.getEncodingTag(
						this.readOnlyCause.configurable.getParentRuntimeObj(),
						this.readOnlyCause.configurable.def.name,
					)
					}, and has changed. ` +
					"This is caused by an incorrect text edit of the script or backwards compatibility discrepancy.",
					this);
			}
		}

		if (this.invalidAssignment) {
			validationLogger.logError(this.invalidAssignment.getError(), this);
		}
	}

	public getValue(): ValueType {
		return this.value;
	}

	public getSerializationOrder(_options: SerializationOptions) {
		return this.anyModSeqNum;
	}

	public getUserModSeqNum() {
		return this.userModSeqNum;
	}

	public getAnyModSeqNum() {
		return this.anyModSeqNum;
	}

	public isUserModified() {
		return this.valueAssignSource !== null && isUserChange(this.valueAssignSource);
	}

	public isFromMeta() {
		return this.valueAssignSource !== null && isMetaChange(this.valueAssignSource);
	}

	// Abstract methods that must be supported by all members to support generic

	// set the value from an instance args object
	public abstract setValueFromArgs(args: InstanceArgsValue, argType: InstanceArgType): void;
	public abstract setValueFromRequiredArgs(
		args: InstanceArgsValue,
		origin: ModuleInstanceMgr,
	): void;
	public abstract removeArgs(args: InstanceArgsValue): void;
	public abstract removeReqArgs(args: InstanceArgsValue, origin: ModuleInstanceMgr): void;
	public removeRequiredByParent(_origin: ModuleInstanceMgr) { }

	// serialization and validation handling.

	/**
	 * Get statements to serialize member to script.
	 *  @param parentIdentifier - parent script identifier of which to hang member specific script statements.
	 */
	public getScriptStatements(parentIdentifier: string, options: SerializationOptions, validations: Validations) {
		if (this.invalidAssignment) {
			return this.invalidAssignment.getScriptStatements(parentIdentifier);
		}

		const validationStatements = this.generateValidationStatements(parentIdentifier, validations);

		if (!this.shouldSerialize(options)) {
			return validationStatements;
		}

		return [...this.generateScriptStatements(parentIdentifier, options), ...validationStatements];
	}

	public getParentRuntimeObj() {
		return this.parentObjectMgr.managedObject;
	}

	/**
	 * Create a script identifier for this member.
	 * @param parentIdentifier 
	 */
	public createScriptIdentifier(parentIdentifier: string): string {
		return createChildIdentifier(parentIdentifier, this.def.name);
	}

	// Returns true if this member shouldn't exist in validation/uiState/etc maps
	public excludeFromInternalMaps() {
		return this.excludeFromOwnProperties();
	}

	// Returns true if this member should be hidden from the properties on the instance
	public excludeFromOwnProperties() {
		return this.def.deprecated;
	}

	public clearInvalidAssignment() {
		if (this.invalidAssignment) {
			this.invalidAssignment.remove();
			this.invalidAssignment = null;
		}
	}

	public getManagedUIState() {
		if (this.managedUIState) {
			return this.managedUIState;
		}

		this.managedUIState = this.createManagedUIState();
		return this.managedUIState;
	}

	protected valIsInstance(val: any): boolean {
		// check if val is the same type as this.value
		return (typeof val) === this.defaultValueType();
	}

	protected createManagedUIState() {

		const managedUIState = {};

		// uiState has two properties: hidden and readOnly
		// We want to return something to meta-content that:
		// 		1) prevents sets outside of onChange
		// 		2) tracks what changed readOnly (for accurate tooltips, errors)
		// We'll do that via defineProperty

		Object.defineProperty(
			managedUIState,
			"hidden",
			{
				enumerable: true,
				get: () => {
					return this.uiState.hidden;
				},
				set: (val) => {
					if (!this.parentObjectMgr.currentlyAllowMetaAssign()) {
						forbiddenModification("Cannot set hidden outside of onChange");
					}
					this.uiState.hidden = val;
				},
			},
		);

		Object.defineProperty(
			managedUIState,
			"readOnly",
			{
				enumerable: true,
				get: () => {
					return this.uiState.readOnly;
				},
				set: (val) => {
					if (this.isCalculated()) {
						forbiddenModification("Cannot change read-only on calculated configurables");
					}
					if (!this.parentObjectMgr.currentlyAllowMetaAssign()) {
						forbiddenModification("Cannot set read-only outside of onChange");
					}
					if (this.uiState.readOnly === val) {
						return;
					}
					if (!_.isEmpty(this.requiredByParent) && !val) {
						forbiddenModification("Cannot set read-only to false:\nConfigurable is locked by parent:");
					}
					this.readOnlyCause = this.getMetaAssignCause();
					this.uiState.readOnly = val;
				},
			},
		);

		return managedUIState as UIState;
	}

	protected isCalculated() {
		return false;
	}

	protected abstract shouldSerialize(options: SerializationOptions): boolean;
	protected abstract generateScriptStatements(parentIdentifier: string, options: SerializationOptions): Statement[];

	protected modifiedInUI() {
		this.parentObjectMgr.modifiedInUI();
	}

	protected wasForceWritten() {
		return this.isUserModified() && this.userModSeqNum === this.userModSeqNumAtForceWrite;
	}

	// allow child classes to validate incoming value before it is set
	protected validateValue(val: ValueType, _forceWrite: boolean, _source: SetSource) {

		const configType = this.defaultValueType();

		const valType = typeof val;

		if (!this.valIsInstance(val)) {
			this.typeMismatch(configType, valType);
		}
	}

	protected typeMismatch(expected: string, actual: string) {
		throw new Error(`Type mismatch, expected = ${expected}, actual = ${actual}`);
	}

	// allow child classes to transform an rvalue written to the real ValueType somehow
	protected transform(val: ValueType) {
		return val;
	}

	// allow child classes to transform the current value to the lvalue type somehow
	protected toLValue(): LValueType {
		return this.value as any as LValueType;
	}

	// allow child classes to indicate if the value has actually changed or not
	protected isEqual(val: ValueType) {
		return this.value === this.transform(val);
	}

	// allow child classes to do any post processing
	protected onSet(_newVal: ValueType, _source: SetSource) {
		// nothing by default
	}

	// allow child classes to specify type of the expected value
	protected defaultValueType(): string {
		return typeof {};
	}

	protected formatInvalidValue(_value: unknown): string {
		return null;
	}

	protected getValueMetaAssignCause() {
		return this.valueMetaAssignCause;
	}

	protected handleInvalidAssignment(reason: string, value: any, oldDisplayName: string, _e: Error) {
		this.invalidAssignment = new InvalidAssignment(value, this, this.formattersMap,
			reason, oldDisplayName ?? this.formatInvalidValue(value));
		this.userModSeqNum = configurationChanged();
		return false;
	}

	private validateSet(source: SetSource, val: any, forceWrite: boolean, reasonIfInvalid: string, oldDisplayName: string) {
		if (this.def.deprecated) {
			validateDeprecatedAccess(AccessType.WRITE);
		}

		if (source === SetSource.META_ASSIGN && !this.parentObjectMgr.currentlyAllowMetaAssign()) {
			forbiddenModification(
				"Updates are only allowed in an onChange handler to an instance's own configurables.");
		}

		if (!this.validateAssignment(val, source, forceWrite, reasonIfInvalid, oldDisplayName)) {
			return false;
		}
		return true;
	}

	private onNewValueWritten(source: SetSource, forceWrite: boolean, val: any) {
		if (source === SetSource.USER_ASSIGN && !isScriptingEnabled()) {
			this.modifiedInUI();
		}

		// We explicitly check if this is an illegal change (onChange modifying self, or a write to readonly when
		// not allowed) AFTER checking if the value changes.  That allows certain constructs to exist in the meta
		// code where values are commonly calculated/written always in a way where it's known the value won't change
		// when it's not supposed to, and then the meta-code doesn't have to explicitly check.
		if (source === SetSource.META_ASSIGN &&
			this.getMetaAssignCause()?.configurable === this as AnyMemberMgr) {
			forbiddenModification("An onChange handler can never change itself");
		}

		if (!forceWrite) {
			this.forbidReadOnlyIfNeeded(source);
		}

		this.value = val;

		this.anyModSeqNum = configurationChanged();
		if (isUserChange(source)) {
			this.userModSeqNum = this.anyModSeqNum;
			this.valueAssignSource = this.isEqual(this.lastNonUserSetValue) ? this.lastNonUserSetSource : source;
			this.userModSeqNumAtForceWrite = forceWrite ? this.userModSeqNum : -1;
		} else {
			this.lastNonUserSetValue = this.value;
			this.lastNonUserSetSource = source;
			this.valueAssignSource = source;

			if (source === SetSource.META_ASSIGN) {
				this.captureMetaAssign();
				const currentMetaAssign = this.parentObjectMgr.currentMetaAssign();
				if (currentMetaAssign && !isOnModuleChanged(currentMetaAssign)) {
					this.lastValueSetByOnChange = { configurableName: currentMetaAssign.def.name, value: this.value };
				}
			} else if (source === SetSource.META_ARGS) {
				this.lastArgValue = this.value;
				this.userModSeqNum = this.anyModSeqNum;
			}
		}

		// Calling handlers of this change - mark that as an internal boundary so we'll 
		// save the real location of any exceptions
		internalBoundary(() => {
			this.onSet(this.value, source);
			this.parentObjectMgr.onMemberChanged(this, source);
		});
	}

	private onSameValueReWritten(source: SetSource) {
		// If the same value is re-assigned we have to consider the following cases
		// META_* => META_*
		// Should update the cause, so it does not get captured as side effect. 
		// USER_* => META_ASSIGN
		// NOP - This means we may end up with some redundant statements in the config script. However, consider
		// that when changing to meta we have to worry about problematic side effect because the configurable could
		// be read at the time of the meta set, but if keep it as a user change it has to be non read only. 
		// problematic side effects.   
		// META_* => USER_*
		// USER_* => USER_*
		// NOP - keep as original state

		if (this.lastNonUserSetSource && isMetaChange(this.lastNonUserSetSource) && isMetaChange(source)) {
			this.valueAssignSource = source;
			this.captureMetaAssign();
			this.lastOverwrittenReadOnlyValue = null;
		}
	}

	// This validates an incoming assignment.  If it's initiated by the user (ie the script), and
	// we're in the UI, then we'll treat it as a validation error.  If the meta-code set it, or if
	// we're in the CLI, then fail-fast with an exception			

	private validateAssignment(value: any, source: SetSource, forceWrite: boolean, reason?: string, oldDisplayName?: string) {
		this.clearInvalidAssignment();
		try {
			this.validateValue(value, forceWrite, source);
		} catch (e) {
			if (shouldCapture(source, !!reason)) {
				return this.handleInvalidAssignment(reason, value, oldDisplayName, convertUnknownToError(e));
			}
			throw e;
		}

		return true;
	}

	private captureMetaAssign() {
		this.valueMetaAssignCause = this.getMetaAssignCause();
	}

	private forbidReadOnlyIfNeeded(source: SetSource) {

		// Due to reasons related to serialization and backwards compatibility of user scripts,
		// we can't restrict users from changing read-only values, however those changes will 
		// turn into warnings if the configurable doesn't become writable later.

		// Meta-content can always change read only values they marked read only themselves.  That
		// means that args cannot change read only values, and changes marked read only due to 
		// requiredArgs cannot be changed by the child.  Either would indicate that one module is 
		// violating the constraints of the other.

		const hasRequiredArg = !_.isEmpty(this.requiredByParent);
		if (
			// read only by self, changed by parent
			(!hasRequiredArg && this.uiState.readOnly && isMetaChange(source) && source !== SetSource.META_ASSIGN) ||

			// read only by parent (requiredArg), changed by self, and not running a script
			(hasRequiredArg && isMetaChange(source) && !isRunningUserScript())
		) {

			// When being invoked from meta content we want to fail hard. 

			forbiddenModification("Configurable is read only");
		} else if (this.uiState.readOnly && !this.isUserModified()) {
			// we want to capture the value in the case of something locked by META_* is assigned to 
			// a different value by the user
			this.lastOverwrittenReadOnlyValue = this.value;
		} else {
			this.lastOverwrittenReadOnlyValue = null;
		}
	}

	private getMetaAssignCause() {

		const metaAssign = this.parentObjectMgr.currentMetaAssign();
		let cause: MetaAssignCause;

		// Since, changing from outside of onChange is only a warning right now
		// we may have cases where a meta assign is not associated with a member
		if (metaAssign) {
			if (isOnModuleChanged(metaAssign)) {
				cause = {
					userModSeqNum: null,
					inOnModuleChanged: metaAssign,
				};
			} else {
				cause = {
					configurable: metaAssign,
					userModSeqNum: metaAssign.getUserModSeqNum(),
				};
			}
		}
		return cause;
	}

	private generateValidationStatements(parentIdentifier: string, validations: Validations): Statement[] {
		const validation = validations.getValidation(this);
		return _.map(validation?.suppressedWarnings,
			(v) => createValidationSuppressionStatement(parentIdentifier, getValidationKey(v).matcher, this.def));
	}
}

function isOnModuleChanged(obj: any): obj is OnModuleChangedType {
	return obj && "moduleMgr" in obj && "configurables" in obj;
}

function getMemberDefaultHiddenState(def: MemberDef) {
	return def.hidden || def.deprecated || false; // force values to be defined	
}

function getMemberDefaultReadonlyState(def: MemberDef) {
	return def.readOnly || false; // using || false so as not to convert a reason to a boolean
}

// Source of what initiated the change
export const enum SetSource {
	USER_ASSIGN, // user script/GUI assignment
	USER_ARGS, // user via the addModule/addInstance args api
	META_ASSIGN, // meta via assignment
	META_ARGS, // meta via requirement args
	TOOL_INTERNAL, // internal tool change
}

export function isUserChange(source: SetSource) {
	switch (source) {
		case SetSource.USER_ASSIGN:
		case SetSource.USER_ARGS:
			return true;
		case SetSource.META_ASSIGN:
		case SetSource.META_ARGS:
		case SetSource.TOOL_INTERNAL:
			return false;
		default:
			assertUnreachable(source);
	}
}

export function isMetaChange(source: SetSource) {
	switch (source) {
		case SetSource.USER_ASSIGN:
		case SetSource.USER_ARGS:
		case SetSource.TOOL_INTERNAL:
			return false;
		case SetSource.META_ASSIGN:
		case SetSource.META_ARGS:
			return true;
		default:
			assertUnreachable(source);
	}
}

// Track the cause of a change to a member
interface MetaAssignCause {
	configurable?: ConfigurableMgr<any>; // name of the member which changed to cause this change
	userModSeqNum: number; // user modification number of the change
	inOnModuleChanged?: OnModuleChangedType; // changed by another module's onModuleChanged
}

// Verify that the cause is still current. i.e the configurable
// value has since been changed.
export function isMetaCauseAssignCurrent(cause: MetaAssignCause) {
	// if no cause than it was read only by default.
	return cause?.configurable.getAnyModSeqNum() === cause?.userModSeqNum;
}
