
import * as _ from "lodash";
import { IMyListItem } from "../IMyListItem";
import { SelectionInNode } from "../../components/actions/selection";

export class NodeSelection<T extends IMyListItem> {

	private selection: SelectionInNode = { instanceId: null, memberPath: [] };
	private selectionIndex = 0;
	constructor(private readonly getInstances: () => T[]) {
	}

	public getSelectedMyListItem() {
		this.resetSelectionIfNeeded();
		return this.getSelectedInstance();
	}

	public getSelection() {
		this.resetSelectionIfNeeded();
		return this.selection;
	}

	public setSelection(selection: SelectionInNode, tabUpdate?: boolean) {
		this.selection = selection;
		const inst = this.getSelectedInstance();
		if (inst) {
			this.selectionIndex = _.indexOf(this.getInstances(), inst);
			inst.revealMember(selection.memberPath, tabUpdate);
		}
	}

	protected fixInvalidSelection(instances: T[]) {
		const maxIndex = _.size(instances) - 1;
		const index = Math.min(maxIndex, this.selectionIndex);
		this.setSelection({ instanceId: instances[index]?.getID(), memberPath: [] });
	}

	private getSelectedInstance() {
		return _.find(this.getInstances(), (i) => i.getID() === this.selection.instanceId);
	}

	private resetSelectionIfNeeded() {
		if (!this.isSelectionValid()) {
			this.fixInvalidSelection(this.getInstances());
		}
	}

	private isSelectionValid() {
		const instances = this.getInstances();
		return (
			_.some(instances, (i) => i.getID() === this.selection.instanceId) ||
			_.isEmpty(instances) && !this.selection.instanceId
		);
	}
}
