import * as _ from "lodash";
// Load legacy JSON .pinmux file
import { getRenamedDeviceId, getDeviceDescriptions } from "../data";
import {
	Adapt,
	isGPIOInterfaceGroup,
	isMultiPin,
	LegacyDeviceV2,
	LegacyGPIO,
	LegacyMultiPin,
	LegacyPeripheral,
	LegacyPin,
} from "./requirementsData";
import { PinmuxPinInterfaceInstanceMgr } from "../objectManagers/pinmuxPinInterfaceInstance";
import { PinmuxPeripheralInterfaceInstanceMgr } from "../objectManagers/interfaceInstance";
import {
	PinInterfaceInstance,
	InterfaceInstance,
	MultiPin,
	Pin,
} from "public/runtime";
import { SysConfig } from "../sysConfig";
import { Const } from "../utils";
import { SuggestSolutionMgr } from "../objectManagers/assignMembers";
import { powerDomainsModuleName, getPowerDomainsModule } from "../resources/builtIn/powerDomainsModule";
import { ConfigurableValue } from "solutionObj";
import { ResolvedArgs } from "../args/argTypes";

export interface PinMuxFileData {
	deviceRequirements: LegacyDeviceV2;
	boardId: string;
	deviceId: string;
	partId: string;
	packageId: string;
}

interface NameToPin {
	[name: string]: Pin;
}

type ConfigurableType = "checkbox" | "dropdown" | "textbox";

export async function getResolvedArgsFromLegacy(pinMuxFile: PinMuxFileData, resolvedArgs: ResolvedArgs): Promise<ResolvedArgs> {
	const deviceId = getRenamedDeviceId(pinMuxFile.deviceId, await getDeviceDescriptions());
	const { partId, packageId } = pinMuxFile;
	return {
		...resolvedArgs,
		deviceId,
		partId,
		packageId,
	};
}

export function loadLegacy(sysConfig: SysConfig, pinMuxFile: PinMuxFileData) {
	// Legacy .pinmux files may have had optimized GPIO, but nothing else would have been optimized
	const isGPIOOptimizable = sysConfig.getSolver().getPinOptimizations().isOptimizable("GPIO");
	pinMuxFile.deviceRequirements = Adapt(pinMuxFile.deviceRequirements, isGPIOOptimizable);
	load(sysConfig, pinMuxFile);
}

function load(sysConfig: SysConfig, pinMuxFile: PinMuxFileData) {

	// power domains

	if (pinMuxFile.deviceRequirements.powerDomainSettingsEnabled) {
		const scripting = sysConfig.getKnownSingleRuntime().getScripting();

		// Workaround for PMUX-1320 
		// Even if this is later fixed, we're reading a legacy file here...
		// Plus, we've also seen "-" as a member in there for some unknown reason?

		const mod = getPowerDomainsModule(sysConfig.getKnownSingleRuntime().getDeviceData());
		const validNames = _.map(mod.moduleStatic.config, (c) => c.name);
		const args = _.pick(pinMuxFile.deviceRequirements.powerDomainSettings, validNames);
		scripting.addModule(powerDomainsModuleName, args);
	}

	// interface 

	const interfaces = sysConfig.getDeviceData().interfaces;

	// run through the file and update instances

	_.each(pinMuxFile.deviceRequirements.groupRequirements, (group, interfaceName) => {
		if (group.requirements.length > 0) {

			const iface = interfaces[interfaceName];
			const runtime = sysConfig.getKnownSingleRuntime();

			if (isGPIOInterfaceGroup(group)) {
				_.each(group.requirements, (reqData) => {
					const inst = new PinmuxPinInterfaceInstanceMgr(runtime, iface);
					loadGPIOInterfaceInstance(inst.managedObject, reqData, _.size(iface.peripherals));
					runtime.addInterfaceInstance(inst);
				});
			} else {
				_.each(group.requirements, (reqData) => {
					const inst = new PinmuxPeripheralInterfaceInstanceMgr(runtime, iface, {}, false);
					loadInterfaceInstance(inst.managedObject, reqData);
					runtime.addInterfaceInstance(inst);
				});
			}
		}
	});
}

function loadGPIOInterfaceInstance(inst: PinInterfaceInstance, reqData: LegacyGPIO, maxGPIOs: number) {

	inst.$name = reqData.name;
	inst.$numPins = Math.min(reqData.requirements.length, maxGPIOs);

	_.chain(reqData.requirements)
		.take(inst.$numPins)	// Some legacy pinmux files are corrupted and contain too many requirements
		.each((perphReqData, index) => {
			const pinReqData = perphReqData.pinRequirements[0];
			const pinInstances: NameToPin = inst as any;
			if (!isMultiPin(pinReqData)) {
				loadPinInstance(pinInstances[index], pinReqData);
			} else {
				throw new Error("GPIO requirement with multi pin reqs encountered");
			}
		})
		.value();

}

function loadInterfaceInstance(inst: InterfaceInstance, reqData: LegacyPeripheral) {

	inst.$name = reqData.name;
	inst.$useCase = reqData.selectedUseCase;

	if (reqData.selectedInstance !== Const.ANY) {
		inst.$assign = reqData.selectedInstance;
	} else if (reqData.peripheralSolution.assignedToName) {
		inst.$suggestSolution = reqData.peripheralSolution.assignedToName;
	}

	if (reqData.peripheralSolution.errorText) {
		inst.$suggestSolution = SuggestSolutionMgr.errorTag;
	}

	if (reqData.selectedVoltage !== Const.ANY) {
		inst.$assignVoltage = reqData.selectedVoltage;
	}

	// load config
	loadConfig(inst, reqData.configurables || reqData.configOptions);
	_.each(reqData.pinRequirements, (pinReq) => {
		if (isMultiPin(pinReq)) {
			loadPinGroupInstance(inst.$pinGroup, pinReq);
		} else {
			const pinInstances: NameToPin = inst as any;
			if (pinInstances.hasOwnProperty(pinReq.name)) {
				loadPinInstance(pinInstances[pinReq.name], pinReq);
			}
		}
	});
}

function loadPinGroupInstance(inst: MultiPin, reqData: LegacyMultiPin) {
	inst.$numPins = reqData.count;
	const pinInstances: NameToPin = inst as any;
	_.each(reqData.pinRequirements, (pinReq) => {
		if (pinInstances.hasOwnProperty(pinReq.name)) {
			loadPinInstance(pinInstances[pinReq.name], pinReq);
		}
	});
}

function loadPinInstance(inst: Pin, reqData: LegacyPin) {

	inst.$used = reqData.used;

	if (reqData.assignedToName !== Const.ANY) {
		inst.$assign = reqData.assignedToName;
	} else if (reqData.solution.assignedToName) {
		inst.$suggestSolution = reqData.solution.assignedToName;
	}

	if (reqData.solution.errorText) {
		inst.$suggestSolution = SuggestSolutionMgr.errorTag;
	}

	loadConfig(inst, reqData.configurables || reqData.configOptions);
	loadLegacyConfig(inst, reqData);
}

interface NameToConfigurableVale {
	[key: string]: ConfigurableValue;
}

// load the legacy check box based configurables from the very early versions of the tool
function loadLegacyConfig(inst: Pin, reqData: LegacyPin) {
	const interfacePin = inst.$interfacePins[0]; // only 1 in core pinmux
	const legacyConfigs = _.filter(interfacePin.configurables, (c) =>
		isLegacy(c) &&   									// Is this a legacy-style configurable
		!(reqData.configurables || reqData.configOptions));	// ... and has the saved value not been previously converted?
	const configValues: NameToConfigurableVale = {};

	_.each(legacyConfigs, (c) => {
		if (isDropDown(c)) {
			// check box groups converted to drop downs
			const selectedOption = _.find(c.options, (o) => !!(reqData as any)[o.name]);
			configValues[c.name] = selectedOption ? selectedOption.name : c.default;
		} else {
			// only set the value if defined 
			// it is possible some checkbox were never initialized and got serialized as 'undefined'
			const val = (reqData as any)[c.name];
			if (typeof val !== "undefined") {
				configValues[c.name] = val;
			}
		}
	});

	loadConfig(inst, configValues);
}

function loadConfig(inst: Pin | InterfaceInstance, config: NameToConfigurableVale) {
	_.each(config, (value, key) => {
		if (inst.hasOwnProperty(key)) {
			(inst as any)[key] = isOption(value) ?
				value.name :
				value;
		}
	});
}

function isOption(val: ConfigurableValue): val is DeviceInfo.Option {
	// confirms its an object with a name property, the other two types are primitives.
	return typeof (val as DeviceInfo.Option).name !== "undefined";
}

function getConfigurableType(configurable: DeviceInfo.Configurable) {
	return ((configurable as any).type as string).toLowerCase() as ConfigurableType;
}

function isDropDown(configurable: DeviceInfo.Configurable): configurable is DeviceInfo.DropDown {
	return getConfigurableType(configurable) === "dropdown";
}

function isLegacy(configurable: DeviceInfo.Configurable): boolean {
	return (configurable as any).legacy;
}
