import * as _ from "lodash";
import { AnyMemberMgr, SetSource } from "../member";
import { isScriptingEnabled } from "../../scripting/scriptingGuard";
import { ForceWrite } from "../../scripting/forceWrite";
import { UserError, assignmentToString } from "../../niceExceptions";
import { getCurrentlyRunningCallbackContext, getCurrentlyRunningCallbackName } from "../../moduleAccessGuard";
import { InvalidAssignmentWrapper, shouldCapture } from "../invalidAssignment";
import { createInvalidAssignmentProxy } from "./invalidAssignmentProxy";
import { RuntimeObject } from "public/runtime";
import { AObjectMgr } from "../object";
import { AccessType, validateDeprecatedAccess } from "../../deprecatedAccessGuard";

export type ManagedObjectProxyTarget = AObjectMgr<RuntimeObject>;

type MemberMap = ManagedObjectProxyTarget["memberMgrs"];

export class StaleProxyError extends Error {
}

// This is a proxy handler to be used in a proxy for an object manager.  It will present controlled access to the 
// managed members of the object manager.

export const managedObjectProxyHandler: ProxyHandler<ManagedObjectProxyTarget> = {
	get: (target, key: Extract<PropertyKey, string>) => {
		return getHelper(target, key);
	},

	set: (target, key: Extract<PropertyKey, string>, value) => {
		return setHelper(target, key, value);
	},

	// Hide internal properties from Object.keys() (not hidden properties)

	ownKeys: (target) => {
		const inst = target.memberMgrs;
		return _.chain(inst)
			.keys()
			.filter((key) => hasOwnProperty(inst, key))
			.value();
	},

	// Hide internal properties from 'in' (not hidden properties)

	has: (target, key: Extract<PropertyKey, string>) => {
		return hasOwnProperty(target.memberMgrs, key);
	},

	defineProperty: () => {
		return false; // disallow
	},

	deleteProperty: () => {
		return false; // disallow
	},

	getOwnPropertyDescriptor: (target, key: Extract<PropertyKey, string>) => {
		const inst = target.memberMgrs;
		if (hasOwnProperty(inst, key)) {

			// Node won't let us return that it's not configurable, so instead we'll return 
			// getters/setters vs the raw value at least

			return {
				configurable: true,
				enumerable: true,
				get: () => inst[key].get(),
				set: (val: any) => () => {
					setImpl(target, key, val);
				},
			};
		}
		return undefined;
	},

	setPrototypeOf: () => {
		return false; // disallow
	},
};

function toJSON(inst: MemberMap) {
	return (
		_.chain(inst)
			.keys()
			.filter((memberName) => hasOwnProperty(inst, memberName))
			.sortBy()
			.reduce((obj, memberName) => {
				obj[memberName] = inst[memberName].jsonify();
				return obj;
			}, {} as any as { [key: string]: any })
			.value()
	);
}

function setImpl(target: ManagedObjectProxyTarget, key: Extract<PropertyKey, string>, val: any) {
	const forceWrite = val instanceof ForceWrite;
	val = forceWrite ? val.val : val;

	let reason: string | undefined;
	let oldDisplayName;
	if (val instanceof InvalidAssignmentWrapper) {

		// This was previously recorded as an invalid assignment.  However, maybe it's valid now?
		// If we don't have a deeper path, just extract the original value/reason and re-try
		// If we do, extract the next key and recursively try to set at one level deeper.
		oldDisplayName = val.oldDisplayName;
		if (_.isEmpty(val.memberPath)) {
			reason = val.reason;
			val = val.val;
		} else {
			target.memberMgrs[key].get()[_.first(val.memberPath)] =
				new InvalidAssignmentWrapper(val.val, val.reason, _.drop(val.memberPath), oldDisplayName);
			return;
		}
	}

	target.memberMgrs[key].set(
		val, isScriptingEnabled() ? SetSource.USER_ASSIGN : SetSource.META_ASSIGN, forceWrite, reason, oldDisplayName);
}

function validateTargetContext(target: ManagedObjectProxyTarget, key: string) {
	const context = getCurrentlyRunningCallbackContext();
	if (context && (context !== target)) {
		const inst = target.memberMgrs;
		const callBackName = getCurrentlyRunningCallbackName();
		const cannotAccessError =
			new Error(`Cannot access members of ${inst.$name.get()} from ${context.memberMgrs.$name.get()}`);
		if (callBackName === "pinmuxRequirements") {
			// exception to support "extend"
			const requestedObj = inst[key].get();
			if (!_.isObject(requestedObj)) {
				throw cannotAccessError;
			}
		} else if (callBackName === "ports" && key === "$name") {
			// Allow the ports function to read the name of other modules
			// Allows it to work with instance reference picker to rename ports on the fly
		} else {
			throw cannotAccessError;
		}
	}
}

function hasOwnProperty(inst: MemberMap, key: string) {
	return inst.hasOwnProperty(key) && !inst[key].excludeFromOwnProperties();
}

export function getKeyWithLegacyName(legacyName: string, inst: { [memberName: string]: AnyMemberMgr; }) {
	const memberMgr = _.find(inst, (mgr) => {
		return _.includes(mgr.def.legacyNames, legacyName);
	});

	return memberMgr?.def.name;
}

function setHelper(target: ManagedObjectProxyTarget, key: Extract<PropertyKey, string>, value: any): boolean {
	const inst = target.memberMgrs;

	// Allow "set" for deprecated configurables
	if (inst.hasOwnProperty(key)) {
		try {
			setImpl(target, key, value);
		} catch (e) {
			throw new UserError(`cannot set '${key}' to ${assignmentToString(value)}`, e);
		}
		return true;
	} else if (value instanceof InvalidAssignmentWrapper) {

		// Invalid member, but was saved as a known invalid access 
		// Simply re-record the 100% invalid access

		const { val, reason, memberPath } = value;
		target.invalidAccess(val, [key, ...memberPath], reason);
		return true;
	} else if (getKeyWithLegacyName(key, inst)) {
		validateDeprecatedAccess(AccessType.WRITE);
		return setHelper(target, getKeyWithLegacyName(key, inst), value);
	} else if (isScriptingEnabled() && shouldCapture(SetSource.USER_ASSIGN, false, false)) {
		target.invalidAccess(value, [key]);
		return true;
	}

	throw new TypeError("unknown property: " + key.toString());
}

function getHelper(target: ManagedObjectProxyTarget, key: Extract<PropertyKey, string>): any {
	const inst = target.memberMgrs;
	if (!inst) {
		throw new StaleProxyError("Attempted to access stale module instance");
	}

	if (inst.hasOwnProperty(key)) {
		validateTargetContext(target, key);
		return inst[key].get();
	} else if (key === "hasOwnProperty") {
		return (key2: string) => hasOwnProperty(inst, key2);
	} else if (key === "toString") {
		return () => ({}).toString();
	} else if (key === "toJSON") {
		return () => toJSON(inst);
	} else if (getKeyWithLegacyName(key, inst)) {
		validateDeprecatedAccess(AccessType.READ);
		return getHelper(target, getKeyWithLegacyName(key, inst));
	} else if (isScriptingEnabled() && shouldCapture(SetSource.USER_ASSIGN, false, false)) {
		return createInvalidAssignmentProxy([key], target);
	}
	return undefined;
}
