import * as _ from "lodash";
import { ChildProcessWithoutNullStreams } from "child_process";
import { ButtonConfigurable, IDialogValidationLogger } from "public/defs";
import { ModuleInstance } from "public/runtime";
import { ModuleInstanceMgr } from "../moduleInstance";
import { Validations, ValidationSummary } from "../validations";
import { ConfigurableMgr } from "./configurableMgr";
import { ConfigurableComponent } from "./configurableComponent";
import { IModalService } from "../../IModalService";
import { StaticModuleInstanceMgr } from "../staticModuleInstance";
import { FormattersMap } from "../../formatting/formattersMap";
import { addAlwaysPresentModule } from "../../product/alwaysPresentModules";
import { Runtime } from "../../resources/runtime";
import { AObjectMgr } from "../object";
import { disableScriptingForCallback } from "../../scripting/scriptingGuard";

export interface ButtonClickOptions {
	filePath?: string,
	onProcessCreate?: (process: ChildProcessWithoutNullStreams) => {},
}

interface AdditionalSetting {
	label: string;
	buttonText: string;
	isSet: () => Promise<boolean>;
	set: () => Promise<boolean>;
}

export abstract class ButtonConfigurableMgr<
	ResultType, MemberDefinition extends ButtonConfigurable<ResultType> = ButtonConfigurable<ResultType>>
	extends ConfigurableMgr<string, ModuleInstance, MemberDefinition> {
	public readonly ui = ConfigurableComponent.CButtonConfigurable;
	public override parentObjectMgr: ModuleInstanceMgr
	private readonly popupMgr: StaticModuleInstanceMgr;
	private accessErrorMsg = `${this.def.name} has no value.  It is only to provide a button in the UI.`;
	private validations: Validations;
	private validationLogger: IDialogValidationLogger;

	constructor(
		parentObjectMgr: AObjectMgr<ModuleInstance>,
		formattersMap: FormattersMap,
		def: MemberDefinition,
		runtime: Runtime,
	) {
		super(parentObjectMgr, formattersMap, def);
		if (def.popupModule) {
			this.validations = runtime.getValidations();
			this.validationLogger = runtime.getDialogValidationLogger();
			this.popupMgr = addAlwaysPresentModule(runtime, def.popupModule);
			const modDef = this.popupMgr.getModuleMgr().module.$static.$module;
			_.each(["sharedModuleInstances", "pinmuxRequirements", "modules", "ports"] as const, (key) => {
				if (modDef[key]) {
					throw new Error(`Cannot define ${key} on a module used as a pop up`);
				}
			});
			this.removeActionFromRuntime = runtime.registerAdditionalValidationAction(
				() => this.validateDialog(false));
		}

		if (!def.popupModule && def.validateDialog) {
			throw new Error("Cannot define validateDialog when popupModule is not defined.");
		}

		if (def.popupModule && (def.fileFilter || def.pickDirectory)) {
			throw new Error("Cannot define popupModule when either of fileFilter or pickDirectory are defined.  " +
				"Instead, add a file browse to the pop up module definitions");
		}
	}

	public override get(): string {
		return undefined;
	}

	public override set() {
		throw Error(this.accessErrorMsg);
	}

	public override shouldSerialize() {
		return false;
	}

	public override getToolTip(validations: Validations) {
		const reason = this.getDisabledReason(validations);
		return reason ?? super.getToolTip(validations);
	}

	public isDisabled(validations: Validations): boolean {
		return !!this.uiState.readOnly || !!this.getDisabledReason(validations);
	}

	public override getUIHash(validations: Validations): string {
		if (this.isDisabled(validations)) {
			return null;
		}
		return super.getUIHash(validations);
	}

	public override remove() {
		super.remove();
		this.removeActionFromRuntime();
	}

	// Get the module instance manager that should be used as a pop up when the button is clicked

	public getPopupMgr() {
		return this.popupMgr;
	}

	// Get a one-time action that must happen

	public getAdditionalSetting(): AdditionalSetting {
		return null;
	}

	// Do whatever the button was designed to do, and return the object to pass back into the callback functions

	public async getClickResult(
		productPath: string,
		modalService: IModalService,
		options: ButtonClickOptions,
	) {
		if (this.def.validateDialog) {
			this.validateDialog(true);
			const summary = this.validations.getSummary(this.popupMgr);
			if (summary === ValidationSummary.Error) {
				return { result: null, validationSuccess: false };
			}
		}
		const result = await this.getClickResultImpl(productPath, modalService, options);
		return { result, validationSuccess: true };
	}

	protected abstract getClickResultImpl(
		productPath: string,
		modalService: IModalService,
		options: ButtonClickOptions
	): Promise<ResultType>;

	// Returns the reason why we are disabled, if there is one

	protected getDisabledReason(validations: Validations): string {
		const disabled = !this.def.ignoreErrors && validations.getOverallSummary() === ValidationSummary.Error;
		return disabled ? "Action unavailable when design errors exist" : null;
	}

	private validateDialog(confirmClicked: boolean) {
		if (this.def.validateDialog) {
			disableScriptingForCallback(() =>
				this.def.validateDialog(
					this.parentObjectMgr.managedObject,
					this.popupMgr.managedObject,
					confirmClicked,
					this.validationLogger));
		}
	}

	private removeActionFromRuntime = () => { };
}
