
let pathsVisible = false;

export function arePathsVisible() {
	return pathsVisible;
}

export function allowPathVisibility<T>(func: () => T) {
	try {
		pathsVisible = true;
		return func();
	} finally {
		pathsVisible = false;
	}
}

export function guardPathVisibility<T>(func: () => T) {
	return () => {
		if (!pathsVisible) {
			throw Error("filesystem paths cannot be accessed at this time");
		}
		return func();
	};
}
