import { HardwareImpl } from "./hardware";
import { ModulesImpl } from "./modules";
import { PeripheralsImpl } from "./peripherals";
import { ScriptingObject } from "public/runtime";
import { Runtime } from "../resources/runtime";
import { guardScriptingFunction } from "./scriptingGuard";
import { freezeDeep } from "../utils";
import { forceWrite } from "./forceWrite";
import { invalidAssignment } from "../objectManagers/invalidAssignment";
import { createScriptingConnect, createScriptingProbe } from "../objectManagers/portMemberMgr";

export function createScriptingObject(runtime: Runtime): ScriptingObject {
	const modules = new ModulesImpl(runtime);
	const peripherals = new PeripheralsImpl(runtime);
	const hardware = new HardwareImpl(runtime);
	return freezeDeep({
		addModule: guardScriptingFunction(modules.add, "scripting.addModule"),
		addHardware: guardScriptingFunction(hardware.add, "scripting.addHardware"),
		addPeripheral: guardScriptingFunction(peripherals.add, "scripting.addPeripheral"),
		forceWrite: guardScriptingFunction(forceWrite, "scripting.forceWrite"),
		invalidAssignment: guardScriptingFunction(invalidAssignment, "scripting.invalidAssignment"),
		suppress: guardScriptingFunction(runtime.suppress, "scripting.suppress"),
		excludeFromBuild: guardScriptingFunction(runtime.excludeFromBuild, "scripting.excludeFromBuild"),
		connect: guardScriptingFunction(createScriptingConnect(runtime), "scripting.connect"),
		probe: guardScriptingFunction(createScriptingProbe(runtime), "scripting.probe"),
	});
}
