import * as _ from "lodash";
// Functionality related to managing a pin configurable object

import * as DeviceData from "dataInterfaces";
import { applyUseCaseOverride, simpleValidation, addMetaContentConfigurableMgrs } from "./funcs";
import { MetaContentConfigurableMgr, createMetaContentConfigurableMgr } from "./configurables/configurable";
import { AObjectMgr } from "./object";
import { SolverRequirement } from "./pinMembers";
import { PinInterfacePin, Pin, PinSolution } from "public/runtime";
import { SelectionFilterGroup } from "./selectionFilterGroup";
import { FixedDataMember } from "./fixedDataMember";
import { SetSource } from "./member";
import { OptimizablePin, Peripheral } from "../solver/requirements";
import { setAssignedValue } from "./interfaceInstance";
import { Runtime } from "../resources/runtime";
import { FormatOptions } from "../formatting/formattingTypes";
import { FormattedMsgPart } from "../formatting/link";
import { ModuleInstanceMgr } from "./moduleInstance";
import { StandardConfigurable } from "public/defs";
import { InternalValidationLogger, IValidatableMember, IValidatableObject } from "./validations";
import { Const } from "../utils";
import { TextConfigurableMgr } from "./configurables/textConfigurableMgr";

function isUseCasePin(
	useCasePinOrInterfacePins:
		DeviceData.InterfacePin[] | DeviceData.UseCasePin): useCasePinOrInterfacePins is DeviceData.UseCasePin {
	return !_.isArray(useCasePinOrInterfacePins);
}

export interface PinSolverOptions {
	canShareWith?: string;
	filter?: (devicePin: DeviceData.DevicePin, peripheralPin: DeviceData.PeripheralPin) => boolean;
	preferredTypes?: string[];
}

export abstract class APinMgr<T extends Pin | PinInterfacePin> extends AObjectMgr<T> {

	public readonly metaContentConfigurableMgrs: { [memberName: string]: MetaContentConfigurableMgr } = {};
	private solverRequirement: SolverRequirement;
	private useCasePin?: DeviceData.UseCasePin;
	private readonly solutionMember: FixedDataMember<PinSolution, T>;

	constructor(
		runtime: Runtime,
		formatter: (options: FormatOptions, member?: string) => FormattedMsgPart,
		private reqName: string,
		peripheralFilter: SelectionFilterGroup,
		useCasePinOrInterfacePins: DeviceData.InterfacePin[] | DeviceData.UseCasePin,
		componentConnections: DeviceData.DevicePin[],
		solverOptions: PinSolverOptions,
		private readonly parent: IValidatableObject,
		solverReqNamespace = "",
		private readonly reserved: boolean = false,
		private readonly parentModuleMgr?: ModuleInstanceMgr,
		used = true,
		config: StandardConfigurable[] = [],
	) {
		super(runtime, formatter);
		let interfacePins: DeviceData.InterfacePin[];

		if (isUseCasePin(useCasePinOrInterfacePins)) {
			this.useCasePin = useCasePinOrInterfacePins;
			config = useCasePinOrInterfacePins.interfacePin.configurables;
			interfacePins = [this.useCasePin.interfacePin];

		} else {
			interfacePins = useCasePinOrInterfacePins;
		}

		addMetaContentConfigurableMgrs(
			this,
			_.map(config,
				(def) => createMetaContentConfigurableMgr(def, this, reqName, this.runtime, true)),
		);

		const formattersMap = this.runtime.getFormattersMap();
		this.addFixedMember(formattersMap, "$interfacePins", interfacePins);
		this.solutionMember = new FixedDataMember(this, formattersMap, "$solution", null);

		this.solverRequirement = new SolverRequirement(
			solverReqNamespace + reqName,
			this,
			interfacePins,
			peripheralFilter,
			componentConnections,
			runtime.getUserPreference(),
			solverOptions,
			runtime.getPinMap(),
			formattersMap,
			reserved,
			used,
		);

		formattersMap.set(this.solverRequirement.getRequirementData(), formatter);
	}

	public override getContainingInstanceMgrs() {
		return this.parent.getContainingInstanceMgrs();
	}

	public override getContainingTreeNodes() {
		return this.parent.getContainingTreeNodes();
	}

	public modifiedInUI() {
		if (this.parentModuleMgr) {
			this.parentModuleMgr.modifiedInUI();
		}
	}

	public getName(): string {
		return this.reqName;
	}

	// apply the use case override
	public applyUseCaseOverrides(useCasePin: DeviceData.UseCasePin) {

		// apply use case override for configurables
		_.each(this.useCasePin.interfacePin.configurables, (c) => {
			const mem = this.memberMgrs[c.name];
			const override = _.find(this.useCasePin.configurables, (o) => o.name === c.name);
			if (override) {
				applyUseCaseOverride(mem, override);
			} else {
				mem.resetDefaultUIState();
			}
		});

		// set to the value of option if defined other was leave as default(true)
		if (typeof useCasePin.optional !== "undefined") {
			this.memberMgrs.$used.set(!useCasePin.optional, SetSource.TOOL_INTERNAL);
		} else {
			this.memberMgrs.$used.set(true, SetSource.TOOL_INTERNAL);
		}
	}

	public getOverrideMember() {
		return this.solverRequirement.getOverrideMgr();
	}

	public getConflictMember() {
		return this.solverRequirement.getConflictMgr();
	}

	public getUsedMember() {
		return this.solverRequirement.getUsedMgr();
	}

	public getSolverRequirement() {
		return this.solverRequirement.getRequirementData();
	}

	public getSolverRequirements(): (OptimizablePin | Peripheral)[] {
		return [];
	}

	public setLockStatus(status: boolean) {
		setAssignedValue(status, this);
	}

	public solveComplete() {

		const solverReqData = this.solverRequirement.getRequirementData();
		const dp = _.find(this.solverRequirement.getOverrideMgr().getDevicePins(), (c) => {
			return c.name === solverReqData.solution.assignedToName;
		});
		this.solutionMember.changeData({
			peripheralPinName: dp ? solverReqData.solution.assignedPeripheralPin : null,
			devicePinName: dp ? dp.designSignalName : null,
			packagePinName: dp ? dp.name : null,
			muxMode: dp ? solverReqData.solution.assignedMuxMode : null,
			warning: solverReqData.solution.warningText,
			error: solverReqData.solution.errorText,
		});
	}

	public getUsed() {
		return this.managedObject.$used;
	}

	public setUsed(value: boolean, source: SetSource) {
		if (!this.getUsedMember().uiState.readOnly) {
			this.memberMgrs.$used.set(value, source);
		}
	}

	public getSolution() {
		return this.solverRequirement.getRequirementData().solution;
	}

	public getSelectedDevicePin() {
		return this.solverRequirement.getOverrideMgr().getValue();
	}

	public setSelectedDevicePin(name: string) {
		this.memberMgrs.$assign.set(name, SetSource.USER_ASSIGN);
	}

	// get all the configurables that are not built in, but are declared in meta data
	public getNonBuiltInConfigurables() {
		if (this.reserved) {
			return [];
		} else if (this.useCasePin) {
			return _.map(this.useCasePin.interfacePin.configurables, (c) => this.metaContentConfigurableMgrs[c.name]);
		} else {
			return _.values(this.metaContentConfigurableMgrs);
		}
	}

	public override validate(validationLogger: InternalValidationLogger) {
		super.validate(validationLogger);
		_.each(this.metaContentConfigurableMgrs, (mem) => {
			if (mem instanceof TextConfigurableMgr) {
				simpleValidation(mem, validationLogger);
			}
		});
	}

	public getAllVisibleMemberName() {
		return this.getName();
	}

	public getEncodingTag() {
		return this.runtime.getFormattersMap().getEncodingTag(this.managedObject);
	}

	public getLockedAdversaries(): PinMgr[] {
		const conflictDevicePinName = this.memberMgrs.$assign.getValue();
		const allPinMgrAssignedToDevicePin = this.runtime.getAllPinMgrSetToDevicePin(conflictDevicePinName);
		const lockedAdversaries = _.chain(allPinMgrAssignedToDevicePin)
			.without(this)
			.filter((p) => {
				const locked = p.getSelectedDevicePin() !== Const.ANY;
				return locked && p.getSolverRequirement().solution.errorText === "";
			})
			.value();
		return lockedAdversaries;
	}

	public applySolverValidation(memberMgr: IValidatableMember) {
		const solverReqData = this.solverRequirement.getRequirementData();
		if (solverReqData.solution.warningText) {
			this.runtime.getValidations().logWarning(
				{
					shortText: solverReqData.solution.warningText,
					longTexts: solverReqData.solution.warningDetailsText,
				},
				memberMgr,
			);
		}
		if (solverReqData.solution.errorText) {
			this.runtime.getValidations().logError(
				{
					shortText: solverReqData.solution.errorText,
					longTexts: solverReqData.solution.errorDetailsText,
				},
				memberMgr,
			);
		}
	}

	public override getContainingModule(): { modInstMgr: ModuleInstanceMgr, memberPath: string[] } {
		if (!this.parentModuleMgr) {
			// for raw peripherals which will never have displayNames
			return { modInstMgr: null, memberPath: [] };
		}
		const interMgr
			= _.find(this.parentModuleMgr.getInterfaceInstanceMemberMgrs(), (mgr) => mgr.valueObjectMgr === this.parent);
		return { modInstMgr: this.parentModuleMgr, memberPath: [interMgr?.def.name, this.reqName] };
	}

	protected override preRemove() {
		this.runtime.getFormattersMap().delete(this.solverRequirement.getRequirementData());
	}
}

export class PinMgr extends APinMgr<Pin> { }
