import * as _ from "lodash";
import { ElkLabel, ElkPoint } from "elkjs/lib/elk-api";
import { generateGraphGroup, GraphGroup, IPInstanceNode, GraphType } from "./generateGraph";
import { ClockTree, Pin } from "clockTree";
import { ExtendedElkEdge, ExtendedElkLine, ExtendedElkNode, ExtendedElkPort } from "./customTypes";
import { getNodeSize } from "./nodeSizes";
import { Named } from "public/common";
import { maxNodeWidth } from "../../graph/styling/graphStyles";
import { getGroupLayoutOptions, getNodeLayoutOptions, getPosition } from "./layoutOptions";
import { GraphSettings } from "../../../services/instanceContainers/clockTreeNode";
import { elkLayout } from "../../graph/autoLayout/elkLayout";

const portSize = 0;

// Generate an elk port from an ip instance and specific pin

function generatePort(ipInstance: IPInstanceNode, pin: GraphType<Pin>, index: number, inPin: boolean): ExtendedElkPort {
	return {
		id: pin.id,
		width: portSize,
		height: portSize,
		layoutOptions: {
			"port.side": inPin ? "WEST" : "EAST",
			"port.index": inPin ? (_.size(ipInstance.inPins) - index).toString() : index.toString(),
		},
		data: {
			pin,
			ipInstance,
		},
	};
}

// Returns a dummy label for the node so that it will not have lines cross over it

function generateLabel(node: Named): ElkLabel[] {
	return [{
		id: node.name + "label",
		// We don't want to re-generate the graph if the option changes, so choose the bigger of name/displayName
		text: _.size(node.name) > _.size(node.displayName) ? node.name : node.displayName,
		width: maxNodeWidth,
		height: 10,
	}];
}

// Generate an elk node from an ip instance

function generateNode(ipInstance: IPInstanceNode, graphSettings: GraphSettings): ExtendedElkNode {
	const inPorts = _.map(ipInstance.inPins, (pin, index) => generatePort(ipInstance, pin, index, true));
	const outPorts = _.map(ipInstance.outPins, (pin, index) => generatePort(ipInstance, pin, index, false));
	return {
		id: ipInstance.id,
		labels: generateLabel(ipInstance),
		...getNodeSize(ipInstance, graphSettings),
		ports: [...inPorts, ...outPorts],
		layoutOptions: getNodeLayoutOptions(ipInstance, graphSettings),
		data: {
			ipInstance,
		},
		...getPosition(ipInstance, graphSettings),
	};
}

// Generate an elk graph description based on a specific filtered NodeGroup

function generateGraphForGroup(
	clockTree: ClockTree,
	group: GraphGroup,
	graphSettings: GraphSettings,
): ExtendedElkNode {
	const subGroups = _.map(group.groups, (g) => generateGraphForGroup(clockTree, g, graphSettings));
	return {
		id: group.name,
		layoutOptions: getGroupLayoutOptions(group, graphSettings),
		children: [
			..._.map(group.ipInstances, (i) => generateNode(i, graphSettings)),
			...subGroups,
		],
		edges: _.map(group.edges, (edge, index) => {
			return {
				id: group.name + index.toString(),
				sources: [edge.source.id],
				targets: [edge.target.id],
				data: {
					edge: edge,
				},
			};
		}),
		data: {
			ipInstance: {
				name: group.name,
				displayName: group.displayName,
				shape: "LargeSquare",
				type: "Group",
			},
		},
		labels: generateLabel(group),
		...getPosition(group, graphSettings),
	};
}

// Generate an elk graph description based on the clock tree and a specific ip instance that is selected in the left pane

function generateGraph(clockTree: ClockTree, instances: string[], graphSettings: GraphSettings
): Omit<ExtendedElkNode, "data"> {
	const groupedNodes = generateGraphGroup(clockTree, instances, graphSettings);
	return generateGraphForGroup(clockTree, groupedNodes, graphSettings);
}

// Take the clock tree, the instances we want to render, and any provided custom layout and use ELK to generate
// a reasonable layout and return an extended ELK node that can be passed on to the react graphing components

export async function getLayout(
	clockTree: ClockTree,
	instances: string[],
	graphSettings: GraphSettings,
) {
	const graph = generateGraph(clockTree, instances, graphSettings);
	const layout = await elkLayout(graph) as ExtendedElkNode;
	return processConnections(layout);
}

function processConnections(layout: ExtendedElkNode): ExtendedElkNode {
	if (!layout.children) {
		return layout;
	}
	const joints = extractJoints(layout.edges);
	const singleEdges = removeOverlappingEdges(layout.edges, joints);
	const lines = extendConnections(singleEdges, layout);
	const children = _.map(layout.children, processConnections);
	return {
		...layout,
		children,
		lines,
		joints,
	};
}

export function coordinateEqual(a: number, b: number) {
	// The coordinates are floats, so to compare them equal they need to be within some tolerance.  We can't use 
	// Number.EPSILON, but must pick something reasonable for our application.
	// See https://dev.to/alldanielscott/how-to-compare-numbers-correctly-in-javascript-1l4i for a better explanation.
	//
	// For example, I've seen Elk generate 1089.628205128205 and 1089.6282051282053 for two x coordinates that ought to
	// be the same (like a line and joint).
	//
	// Since 1 equals 1 pixel in ELK, a reasonable tolerance should be 0.25 (power of 2, and clearly under pixel 
	// rounding errors.

	return Math.abs(a - b) < 0.25;
}

function isVertical(line: { start: ElkPoint, end: ElkPoint }) {
	return line.start.x === line.end.x;
}

// Elk outputs one "edge" as a line with multiple bends going from one output to one input.  If there are two 
// connections to one input, then those edges will partially overlap.  Unfortunately, the browser will render two svg 
// paths as a thicker than normal line, at least if you zoom out.  As such, we want to convert every edge into a series 
// of non-overlapping lines.

function removeOverlappingEdges(edges: ExtendedElkEdge[], unsortedJoints: ElkPoint[]): ExtendedElkLine[] {
	const joints = _.sortBy(unsortedJoints, ["x", "y"]);
	return _.chain(edges)
		.flatMap((edge) => {

			// First, convert the bend points into multiple separate lines

			const section = edge.sections[0];
			const points = section.bendPoints ? [...section.bendPoints, section.endPoint] : [section.endPoint];
			let start = section.startPoint;
			return _.map(points, (end) => {
				const line = { start, end, edge: edge.data.edge };
				start = end;
				return line;
			});
		})
		.map((line) => {

			// Next, ensure that every line is described left-to-right or top-to-bottom.  That will make the next 
			// section easier to reason about.

			if ((isVertical(line) && line.start.y > line.end.y) || line.start.x > line.end.x) {
				return {
					...line,
					start: line.end,
					end: line.start,
					reversed: true,
				};
			}
			return {
				...line,
				reversed: false,
			};
		})
		.flatMap((line) => {

			// Find all the joints that are on this line.  Note that a line's start is always less than the end

			const filter = isVertical(line)
				? (joint: ElkPoint) => coordinateEqual(joint.x, line.start.x) && line.start.y < joint.y && joint.y < line.end.y
				: (joint: ElkPoint) => coordinateEqual(joint.y, line.start.y) && line.start.x < joint.x && joint.x < line.end.x;
			const jointsOnLine = _.filter(joints, filter);

			// We can now build new lines from the original start/end plus all the joints.

			let start = line.start;
			return _.map([...jointsOnLine, line.end], (end) => {
				const newLine = { ...line, start, end };
				start = end;
				return newLine;
			});
		})
		.groupBy((line) => `${line.start.x}_${line.start.y}_${line.end.x}_${line.end.y}`)
		.map((lines) => {

			// Return a single line, but include all the original data of all the edges encompassed
			// Note that if it was reversed, reverse it back - that allows the hover animation to follow the actual 
			// direction of the signal flow

			const line = lines[0];
			return {
				start: line.reversed ? line.end : line.start,
				end: line.reversed ? line.start : line.end,
				data: {
					edges: _.map(lines, (l) => l.edge),
				},
			};
		})
		.value();
}

// Extends any lines at their source if marked as "extendAtSource".  This is necessary for oscillators with multiple 
// out ports, as oscillators are drawn as a circle, but elk assumes all nodes are square, so we need to extend the 
// connection from the containing square in to the edge of the circle

function extendConnections(lines: ExtendedElkLine[], layout: ExtendedElkNode) {
	return _.map(lines, (line) => {
		if (line.data.edges[0].extendAtSource) {

			// This line must be extended, but only if it's the section of line connects to the named source.  We can 
			// figure that out by checking if the port would have equivalent coordinates

			const node = _.find(layout.children, (c) => c.id === line.data.edges[0].source.instName);
			if (_.some(node?.ports, (p) => coordinateEqual(p.x + node.x, line.start.x) && coordinateEqual(p.y + node.y, line.start.y))) {
				return {
					...line,
					start: {
						x: line.start.x - 2, // eyeballing indicates that ~2 pixels is correct - no need for fancy math
						y: line.start.y,
					},
				};
			}
		}
		return line;
	});
}

function extractJoints(edges: ExtendedElkEdge[]) {
	return _.chain(edges)
		.flatMap((edge) => edge.junctionPoints)
		.compact()
		.uniq()
		.value();
}
