import { compileTemplate } from "../resources/templateCompiler";
import * as _ from "lodash";
import { CodeGenTemplateFile, ReferenceFile } from "dataInterfaces";
import * as path from "path";
import { runTemplate } from "../codeGeneration/templateRunner";
import { contextify } from "../resources/contextify";

export function ipcfGenTemplateFunc(templates: CodeGenTemplateFile[], referencedFiles: ReferenceFile[]) {
	const generatedFiles = _.map(templates, (template) => "$PROJ_DIR$" + path.sep + path.normalize(template.name));
	const referencedFileFullPaths = _.map(referencedFiles,
		(referencedFile) => path.normalize(referencedFile.iarPath) || referencedFile.path);
	const files = [...referencedFileFullPaths, ...generatedFiles];
	const template = require("./SysConfig_Generated_Files.ipcf.xdt");
	const templateFunc = contextify("SysConfig_Generated_Files.ipcf.xdt", compileTemplate(template), [])();
	return runTemplate(() => templateFunc(files));
}
