import * as _ from "lodash";
import { InstanceArgs, SharedModuleInstanceRequirement } from "public/defs";
import { RuntimeObject } from "public/runtime";
import { ModuleInstanceMgr } from "../moduleInstance";
import { AObjectMgr } from "../object";
import { ObjectMemberManager } from "../objectMember";
import { BreakUserConnections, PortMemberMgr } from "../portMemberMgr";

function areRequiredSettingsCompatible(
	requiredArgs: InstanceArgs,
	child: AObjectMgr<RuntimeObject>,
	allowUnlocked: boolean,
): boolean {
	return _.every(requiredArgs, (arg, key) => {
		const member = child.memberMgrs[key];
		if (member instanceof ObjectMemberManager) {
			return areRequiredSettingsCompatible(arg as InstanceArgs, member.valueObjectMgr, allowUnlocked);
		} else {
			// When allowUnlock is true, any member that is not readOnly is considered compatible.
			// - auto assign => no allowUnlocked
			// - user assign => allowUnlocked because we will change the unlocked members into compatible values
			// - validation => no allowUnlocked because at this point all changes should have been made 
			return (allowUnlocked && !member.uiState.readOnly) ||
				_.isEqual(arg, member.getValue());
		}
	});
}

export const enum ChangesToChild {
	DISALLOWED = 0,
	ALLOWED = 1,
}

// Returns true if the child can be assigned to the parent, either with or without changes to the child.  For example, 
// to check if an existing instance can be used automatically, you'd want to disallow changes.  However, to check if an
// instance could be explicitly selected to use you would want to allow changes.  The idea is that you wouldn't want
// automatic behaviour to alter existing settings that may be tested and working, but if the user explicitly selected 
// it, then they must understand the consequences.
// It specifically looks at if the required settings either already match the existing settings (no changes) or if they
// could be changed to match it, as well as if any implied connections would replace existing connections (no changes) 
// or if it would replace existing implied connections (should never be allowed)

export function isAssignable(
	changes: ChangesToChild, child: ModuleInstanceMgr, { requiredArgs, impliedConnections }: SharedModuleInstanceRequirement,
) {
	return child.canBeShared() &&
		areRequiredSettingsCompatible(requiredArgs, child, changes === ChangesToChild.ALLOWED) &&
		_.every(impliedConnections, ({ childPort }) => {
			const port = child.memberMgrs[childPort];
			if (port instanceof PortMemberMgr) {
				return port.canImplyConnection(
					changes === ChangesToChild.ALLOWED ? BreakUserConnections.ALLOW : BreakUserConnections.DISALLOW);
			}
			return true;
		});
}
