class SATFailure extends Error {
}

// There are multiple choices for a pin, but all of them must be invalid for one or more reasons 
// for that pin to have an error associated with it.  This interface indicates why one choice 
// couldn't be taken, and addPinErrorDetails will generate one per choice, then fill out error 
// information

interface ChoiceInfo {

	// True if the parent peripheral choice is valid for this device pin choice

	validPeripheral: boolean;

	// True if the parent peripheral choice that would make this device pin choice valid is in use
	// by another peripheral requirement

	validPeripheralsInUse: boolean;

	// List of other pin requirements that use the peripheral pin that would be needed for this 
	// choice

	peripheralPinConflicts: Pin[];

	// True if the peripheral pin is free.  This isn't the same as peripheralPinConflicts being 
	// empty, because a device pin choice could be possible from more than one peripheral pins, and
	// thus one of them could be in use, and the other could be valid

	validPeripheralPin: boolean;

	// True if the choice isn't in any IOSet.  This is likely a bug in the SOC data, but it happens

	excludedInEveryIOSet: boolean;

	// The list of peripheral requirements using the peripheral needed for this choice.  This isn't 
	// the same as validPeripheralsInUse because the choice could be possible for an in use 
	// peripheral, but then valid for a not-in use one.
	peripheralConflicts: PeripheralReq[];

	// True if the ioset is invalid

	invalidIOSet?: boolean;

	// List of other pin requirements using this device pin

	inUseBy?: string;

	// Encoded name to use when forming an error message

	tag: string;
}

// -----------------------------------------------------------------------------
// SatSolver
// Solver that solves by defining a bunch of "choices" that must be made and 
// then expressing those choices as a boolean expression in conjunctive normal
// form (CNF).  Once expressed, it uses glucose, an open source boolean 
// satisfiability solver to determine if the boolean expression can be solved
// or not
// -----------------------------------------------------------------------------

export class Solver {
	// ignore unbound check as we always call solve with this
	// eslint-disable-next-line @typescript-eslint/unbound-method
	public solve = profile ? this.solveProfile : this.solveImpl;
	private readonly unrestrictedChoices = new ChoiceValidator();
	private deviceData: AdaptedDeviceInfo = null;
	private lastSolution: SavedSolution = null;
	private peripheralChoices: PeripheralChoices = null;
	private interfacePinChoices: InterfacePinChoices = null;
	private devicePinChoices: DevicePinChoices = null;
	private optimizablePinChoices: Record<string, OptimizablePinChoices> = null;
	private minimizeOptimizablePins: Record<string, MinimizeOptimizablePins> = null;
	private minimizePeripherals: MinimizePeripherals = null;
	private ioSetChoices: IOSetChoices = null;
	private powerChoices: PowerChoices = null;
	private freeGPIOPins = new Set<string>();
	private formattersMap: FormattersMap;
	private pinMap: PinMap;
	private optimizations: Optimizations;

	constructor(
		dData: AdaptedDeviceInfo,
		deviceRequirements: Device,
		fMap: FormattersMap,
		pinMap: PinMap,
	) {
		this.initData(dData, deviceRequirements, fMap, pinMap);
	}

	public getPinOptimizations() {
		return this.optimizations;
	}

	public initData(
		dData: AdaptedDeviceInfo,
		deviceRequirements: Device,
		fMap: FormattersMap,
		pinMap: PinMap,
	) {
		this.formattersMap = fMap;
		this.pinMap = pinMap;
		this.optimizations = new Optimizations(dData, pinMap);

		glucoseBudget.restarts = glucoseBudget.restartsInit;
		this.deviceData = dData;
		init(this.deviceData);
		this.saveSolution(deviceRequirements);

		const gpio = this.deviceData.interfaces.GPIO;
		this.pinMap.forEachMapping(_.values(gpio?.interfacePins), PinType.FREE, (devicePin) => this.freeGPIOPins.add(devicePin.name));
		deviceRequirements.gpioPinsTotal = this.freeGPIOPins.size;

		if (summarizeData) {
			log("Peripherals: " + Object.keys(this.deviceData.peripherals).length);
			log("Peripheral pins: " + Object.keys(this.deviceData.peripheralPins).length);
			log("Device pins: " + Object.keys(this.deviceData.devicePins).length);

			const numIOSets = _.reduce(this.deviceData.peripherals, (total: number, peripheral: Peripheral) => {
				return total + peripheral.ioSets.length;
			}, 0);
			log("IO Sets: " + numIOSets);

			let numMappings = 0;
			let numSolutions = 1;
			_.each(this.deviceData.devicePins, (devicePin) => {
				if (undefined !== devicePin.mux) {
					numMappings += devicePin.mux.muxSetting.length;
					if (0 !== devicePin.mux.muxSetting.length) {
						numSolutions *= devicePin.mux.muxSetting.length;
					}
				}
			});
			log("Possible mappings: " + numMappings);
			log("Total possible solutions: " + numSolutions);
		}
	}

	public saveSolution(deviceRequirements: Device, useSuggestedSolution?: boolean) {
		this.lastSolution = new SavedSolution(deviceRequirements, useSuggestedSolution);
	}

	private gatherPinsUsed = (component: HardwareComponent): string[] => {
		return ([
			..._.map(component.signals, (signal) => signal.devicePin ? signal.devicePin.name : null),
			..._.flatMap(component.subComponents, this.gatherPinsUsed),
		]);
	}

	private reportSATFailure(message: string) {
		if (glucoseBudget.restarts < glucoseBudget.restartsMax) {
			throw new SATFailure(message);
		} else {
			logicError(this.formattersMap.getFormatter({ style: FormatStyle.CLI })(message).toString());
		}
	}
	private resetChoices(
		deviceRequirements: Device,
		restrictToPreferredPins: boolean,
		suggestedSolution: SuggestedSolution,
		powerDomainSettingsEnabled: boolean,
	) {
		reset(this.optimizations.getPinCount());

		const choiceValidator = new ChoiceValidator(restrictToPreferredPins, suggestedSolution);
		const pinConflictAllower = new PinConflictTracker(deviceRequirements);
		const perfConflictAllower = new PeripheralConflictTracker(deviceRequirements);
		this.peripheralChoices = new PeripheralChoices(choiceValidator, suggestedSolution, perfConflictAllower);
		this.interfacePinChoices = new InterfacePinChoices(suggestedSolution, pinConflictAllower, this.optimizations);
		this.devicePinChoices = new DevicePinChoices(choiceValidator, pinConflictAllower, this.optimizations);
		this.optimizablePinChoices = _.mapValues(this.optimizations.getOptimizableInterfaces(), (iFace) =>
			new OptimizablePinChoices(choiceValidator, this.interfacePinChoices, this.devicePinChoices, this.optimizations, iFace));
		this.minimizeOptimizablePins = _.mapValues(this.optimizations.getOptimizableInterfaces(), (iFace) =>
			new MinimizeOptimizablePins(this.interfacePinChoices, this.devicePinChoices, this.optimizations, iFace));
		this.minimizePeripherals = new MinimizePeripherals(this.peripheralChoices);
		this.ioSetChoices = new IOSetChoices(this.devicePinChoices);
		this.powerChoices = new PowerChoices(
			this.devicePinChoices, deviceRequirements.powerDomainSettings, powerDomainSettingsEnabled);
	}

	private determinePeripheralChoices(interfaceName: string, peripheralReq: PeripheralReq) {

		const { peripherals } = this.deviceData.interfaces[interfaceName];

		// If there are no choices, add an empty choice then return

		if (_.isEmpty(peripherals)) {
			this.peripheralChoices.newChoice(null, peripheralReq);
			return [];
		}

		// Return an array of choice objects for each possible peripheral that
		// could satisfy this requirement

		return _.chain(this.deviceData.interfaces[interfaceName].peripherals)
			.map((peripheral) => {
				return this.peripheralChoices.newChoice(peripheral, peripheralReq);
			})
			.compact() // Remove any invalid choices
			.value();
	}

	private determinePinChoices(
		peripheralReq: PeripheralReq,
		thisInterfacePerfChoices: PeripheralChoices.Choice[]) {

		// Given the peripheral choices already made, create interface and device pin choices for each
		// pin requirement underneath.  We do this for each peripheral choice as the underlying choices
		// depend on which peripheral choice is chosen.

		_.each(peripheralReq.pinRequirements, (pinReq) => {
			if (pinReq.used) {
				const type = (pinReq.connectedToHardware || pinReq.userOverride) ? null : PinType.FREE;
				_.each(thisInterfacePerfChoices, (perfChoice) => {
					let currentPin: PeripheralPin;
					let choice: InterfacePinChoices.Choice;
					this.pinMap.forEachMapping(pinReq.interfacePins, type, (devicePin, peripheralPin) => {
						if (peripheralPin.peripheralName === perfChoice.peripheral.name) {
							choice = (currentPin === peripheralPin) ? choice :
								this.interfacePinChoices.newChoice(perfChoice, peripheralPin, pinReq);
							currentPin = peripheralPin;
							if (choice && devicePin) {
								this.devicePinChoices.newChoice(choice, peripheralPin, devicePin, pinReq);
							}
						}
					}, true);
					if (!choice) {
						this.interfacePinChoices.newChoice(perfChoice, null, pinReq);
					}
				});
			}
		});
	}

	private determineIOSetChoices(perfChoices: PeripheralChoices.Choice[]) {
		_.each(perfChoices, (perfChoice) => {
			const peripheral = perfChoice.peripheral;
			_.each(peripheral.ioSets, (ioSet) => {
				this.ioSetChoices.newChoice(perfChoice, ioSet);
			});
		});
	}

	private determineChoices(deviceRequirements: Device) {
		// Sort by interface name to ensure reproducibility of solution

		_.each(deviceRequirements.interfaceRequirementsMap, (interfaceReq) => {
			const interfaceName = interfaceReq.name;
			_.each(interfaceReq.requirements, (instanceReq) => {

				if (instanceReq instanceof PeripheralReq) {

					// Create a new choice for the specific peripheral to meet this requirement

					const thisInterfacePerfChoices = this.determinePeripheralChoices(interfaceName, instanceReq);

					// Create a new choice for the specific pin mapping to meet the pin requirements underneath 

					this.determinePinChoices(instanceReq, thisInterfacePerfChoices);

					this.determineIOSetChoices(thisInterfacePerfChoices);

					this.powerChoices.addRestrictions(thisInterfacePerfChoices, instanceReq);
				} else {
					_.each(instanceReq.pinRequirements, (req) => {
						if (req.used) {
							this.optimizablePinChoices[instanceReq.interfaceName].newChoice(instanceReq, req);
						}
					});
				}
			});
		});

		_.each(this.minimizeOptimizablePins, (choices) => choices.addRestrictions());
		this.minimizePeripherals.addRestrictions();
	}

	private generateClauses() {
		resetClauses();

		// Fetch the various clauses, and then write a header that looks like
		// p cnf <num variables> <num clauses>

		this.peripheralChoices.generateClauses();
		this.interfacePinChoices.generateClauses();
		this.devicePinChoices.generateClauses();
		_.each(this.optimizablePinChoices, (choices) => choices.generateClauses());
		_.each(this.minimizeOptimizablePins, (choices) => choices.generateClauses());
		this.minimizePeripherals.generateClauses();
		this.ioSetChoices.generateClauses();

		// Note, PowerChoices MUST be generated last (choices.ts requires that warnings 
		// are added at the end - we could fix that up, but it's good for now)

		this.powerChoices.generateClauses();

		applyClauses();

		initializeAssumptions();
	}

	private setOptimizablePinsNeeded = (amountsNeeded: Record<string, number>) => {
		return _.every(amountsNeeded, (amountNeeded, interfaceName) =>
			this.minimizeOptimizablePins[interfaceName].minimizeResourcesBy(amountNeeded));
	}

	private minimizePeripheralUsage() {
		const maxAvailable = this.minimizePeripherals.getMaxAvailable();

		// Binary search to find the max number that can be minimized

		const maxPossible = _.sortedIndexBy(_.keys(Array(maxAvailable + 1)) as any as number[], null, (value) => {
			if (value === null) {
				return 2; // between 1 or 3
			}
			this.minimizePeripherals.minimizeResourcesBy(value);
			return solveChoices(this.setOptimizablePinsNeeded) ? 1 : 3;
		}) - 1;

		// Now minimize to the correct amount, and do the final solve

		this.minimizePeripherals.minimizeResourcesBy(maxPossible);
		if (!solveChoices(this.setOptimizablePinsNeeded)) {
			this.reportSATFailure("glucose was unable to find a solution that should exist");
		}
	}

	private minimizePowerWarnings() {
		let solved = true;

		_.each(Object.keys(this.powerChoices.warnings), (warningId) => {

			// Assume there's no warning, but if solving fails then we'll have to assume there is

			assume(warningId, false);
			solved = solveChoices(this.setOptimizablePinsNeeded);
			if (!solved) {
				assume(warningId, true);
			}
		});

		if (!solved) {
			solved = solveChoices(this.setOptimizablePinsNeeded);
			if (!solved) {
				this.reportSATFailure("glucose was unable to find a solution that should exist");
			}
		}
	}

	private findValidSolution(deviceRequirements: Device) {
		const solutionDifference = this.lastSolution.compare(deviceRequirements);

		let solved = false;
		const solve = () => {
			solved = solveChoices(this.setOptimizablePinsNeeded);
			return solved;
		};

		solutionDifference.findValidSolution(solve);

		// If the last validation failed, then re-validate now that we excluded it

		if (!solved) {
			if (!solve()) {
				if (debug) {
					log("increasing budget to get a valid solution");
				}
				setBudget(-1, -1, -1);
				solved = solve();
				if (!solve()) {
					this.reportSATFailure("glucose was unable to find a solution that should exist");
				}
			}
		}
	}

	private applySolution(deviceRequirements: Device) {
		deviceRequirements.devicePinMap = {};
		const solutionMap: SolutionMap = {
			peripherals: {},
			peripheralPins: {},
			devicePins: deviceRequirements.devicePinMap,
		};
		apply(getSolution(), solutionMap);
		return solutionMap;
	}

	private getIOSet(ioSetName: string, peripheral: string) {
		const found = _.find(this.deviceData.peripherals[peripheral].ioSets, (ioSet) => ioSet.name === ioSetName);
		return found ? found.ioSetRules : null;
	}

	private isSignalInAnyIOSet(peripheral: string, peripheralPin: string) {
		return _.some(this.deviceData.peripherals[peripheral].ioSets, (ioSet) => peripheralPin in ioSet.ioSetRules);
	}

	private addPeripheralErrorDetails(
		peripheralReq: PeripheralReq,
		solutionMap: SolutionMap,
		usingSuggestedSolution: boolean) {

		// The peripheral(s) that could have been chosen must have been 
		// chosen somewhere else.

		// First, find out what other peripherals we could have chosen.

		const choices2 = _.chain(this.deviceData.interfaces[peripheralReq.interfaceName].peripherals)
			.filter((perif) => this.unrestrictedChoices.isValid(peripheralReq, perif))
			.map((perif) => perif.name)
			.value();

		if (_.isEmpty(choices2)) {
			addErrorDetailsToSolution(peripheralReq.solution, "No peripheral exists which meets this requirement");
		} else {

			// Now look to see if that choice was selected on any other interface 
			// requirement

			_.each(choices2, (peripheralChoice) => {
				const conflicts = solutionMap.peripherals[peripheralChoice];
				if (conflicts) {
					const errorText = peripheralChoice +
						" is already in use by " +
						_.chain(conflicts)
							.map((conflict) => this.formattersMap.getEncodingTag(conflict))
							.join(", ");
					addErrorDetailsToSolution(peripheralReq.solution, errorText);
				} else if (usingSuggestedSolution) {
					addErrorDetailsToSolution(peripheralReq.solution, peripheralChoice +
						" appears valid, but was marked as an error in the suggested solution");
				} else {
					this.reportSATFailure("Peripheral " + peripheralChoice + " appears to be a valid assignment for " +
						this.formattersMap.getEncodingTag(peripheralReq) + " but wasn't found by glucose");
				}
			});
		}
	}

	private addPinErrorDetails(
		pinReq: Pin,
		peripheralReq: PeripheralReq,
		solutionMap: SolutionMap,
		usingSuggestedSolution: boolean) {

		const choices2: { [devicePin: string]: ChoiceInfo } = {};
		const chosenPeripheral = peripheralReq.solution.assignedToName;

		const type = (pinReq.connectedToHardware || pinReq.userOverride) ? null : PinType.FREE;
		this.pinMap.forEachMapping(pinReq.interfacePins, type, (devicePin, peripheralPin) => {
			if (this.unrestrictedChoices.isValid(pinReq, devicePin, peripheralPin)) {
				let choice = choices2[devicePin.name];
				if (!choice) {
					choice = choices2[devicePin.name] = {
						validPeripheral: false,
						validPeripheralsInUse: true,
						validPeripheralPin: false,
						peripheralPinConflicts: [],
						excludedInEveryIOSet: devicePin.excludedInEveryIOSet,
						peripheralConflicts: [],
						tag: this.formattersMap.getEncodingTag(devicePin),
					};
				}
				choice.excludedInEveryIOSet = choice.excludedInEveryIOSet && devicePin.excludedInEveryIOSet;

				// Check if this pin choice is on the chosen peripheral, or 
				// only available on an already in use peripheral

				if (peripheralPin.peripheralName !== chosenPeripheral) {
					const conflicts = solutionMap.peripherals[peripheralPin.peripheralName];
					if (conflicts) {
						choice.peripheralConflicts = choice.peripheralConflicts.concat(conflicts);
					} else {
						choice.validPeripheralsInUse = false;
					}
				} else {
					choice.validPeripheral = true;

					// Check if the peripheral pin is already in use on this peripheral

					const conflicts = solutionMap.peripheralPins[peripheralPin.name];
					if (conflicts) {
						choice.peripheralPinConflicts.push(...conflicts);
					} else {
						choice.validPeripheralPin = true;
					}

					// Check the IOSet

					if (peripheralReq.solution.ioSet) {
						const ioSetRules = this.getIOSet(peripheralReq.solution.ioSet, chosenPeripheral);
						if (peripheralPin.name in ioSetRules) {
							if (ioSetRules[peripheralPin.name] !== devicePin.name) {
								choice.invalidIOSet = true;
							}
						} else if (this.isSignalInAnyIOSet(chosenPeripheral, peripheralPin.name)) {
							choice.invalidIOSet = true;
						}
					}
				}

				// And always check if the choice is already in use (as otherwise 
				// fixing the above wouldn't matter)

				if (solutionMap.devicePins[devicePin.name]) {
					choice.inUseBy = _.map(solutionMap.devicePins[devicePin.name],
						(p) => this.formattersMap.getEncodingTag(p)).join(", ");
				}
			}
		});

		if (_.isEmpty(choices2)) {
			if (pinReq.connectedToHardware) {
				addErrorDetailsToSolution(pinReq.solution,
					"There is no mux configuration that can output any signal of this type to the selected hardware");
			} else {
				addErrorDetailsToSolution(pinReq.solution, "No pins exist that meet this requirement");
			}
		}

		// This is somewhat legacy and complex and I don't want to risk refactoring.  If this function is later 
		// revisited, please look at fixing the complexity
		// eslint-disable-next-line complexity
		_.each(choices2, (choice) => {
			let errorText = "";
			if (choice.excludedInEveryIOSet) {
				errorText = choice.tag + " can never be selected as it is not available in any IO set";
			} else {
				if (!choice.validPeripheral && !choice.validPeripheralsInUse) {
					if ("" !== chosenPeripheral) {
						errorText = choice.tag + " is not available on " + chosenPeripheral;
					}
				} else {
					if (choice.invalidIOSet) {
						errorText = choice.tag + " is not valid for " + peripheralReq.solution.ioSet;
					}
					if (!_.isEmpty(choice.peripheralPinConflicts)) {
						if (errorText) {
							if (choice.validPeripheralPin) {
								errorText += " or must be";
							} else {
								errorText += " and must be";
							}
						} else {
							errorText = choice.tag + " is only valid";
						}
						const plural = 1 !== _.size(choice.peripheralPinConflicts);
						errorText += " on the signal" + (plural ? "s " : " ") +
							_.map(choice.peripheralPinConflicts, (perfPin) => perfPin.solution.assignedPeripheralPin).join(", ") +
							" which " + (plural ? "are" : "is") + " in use by " +
							_.map(choice.peripheralPinConflicts, (perfPin) => this.formattersMap.getEncodingTag(perfPin)).join(", ");
					}
				}

				if (choice.inUseBy) {
					if ("" === errorText) {
						errorText = choice.tag + " is currently";
					} else {
						errorText += " and is also";
					}
					errorText += " in use by " + choice.inUseBy;
				}

				if (!choice.validPeripheral && choice.validPeripheralsInUse && 0 !== choice.peripheralConflicts.length) {
					// This must be because the choice is only available on a 
					// peripheral that is already in use

					const peripheralConflicts = _.uniq(choice.peripheralConflicts);
					if ("" === errorText) {
						errorText = choice.tag + " is ";
					} else {
						errorText += " and is also ";
					}
					errorText += "only available on " +
						_.map(peripheralConflicts, (pc) => pc.solution.assignedToName).join(", ");

					errorText += " which is in use by " + _.map(peripheralConflicts,
						(p) => this.formattersMap.getEncodingTag(p)).join(", ");
				}
			}
			if ("" === errorText) {
				if (usingSuggestedSolution) {
					errorText = choice.tag + " appears valid, but was marked as an error in the suggested solution";
				} else {
					this.reportSATFailure(choice.tag + " appears to be a valid assignment for pin " +
						this.formattersMap.getEncodingTag(pinReq) + ", but wasn't found by glucose");
				}
			}

			addErrorDetailsToSolution(pinReq.solution, errorText);
		});
	}

	private getGPIOPinsUsed(solutionMap: SolutionMap) {
		return _.reduce(solutionMap.devicePins, (total, _unused, pinName) =>
			total + (this.freeGPIOPins.has(pinName) ? 1 : 0), 0);
	}

	private summarizeWarnings<T extends PeripheralReq | Pin>(
		req: T, solutionMapEntry: { [assignment: string]: T[] }) {

		// Pin/Peripheral is directly conflicting, but has been oked by the user

		if (req.areConflictsAllowed()) {
			const allowedConflicts = solutionMapEntry[req.userOverride];
			if (1 < _.size(allowedConflicts)) {
				const conflicts = _.chain(allowedConflicts)
					.filter((p) => p !== req)
					.map((p) => this.formattersMap.getEncodingTag(p))
					.join(", ")
					.value();
				const userOverride = req instanceof Pin ?
					this.formattersMap.getEncodingTag(this.deviceData.devicePins[req.userOverride]) :
					req.userOverride;
				addWarningToSolution(req.solution, `${userOverride} is also in use by ${conflicts}`);
			}
		}

		// Pin was overridden to use a hardware component or un-pinned out pin

		if (req.userOverride &&
			this.deviceData.board &&
			req instanceof Pin &&
			!req.connectedToHardware &&
			!req.solution.errorText) {
			const { type, component } = this.pinMap.get(this.deviceData.devicePins[req.userOverride]);
			const userOverride = this.formattersMap.getEncodingTag(this.deviceData.devicePins[req.userOverride]);
			const board = this.deviceData.board.displayName;
			if (PinType.COMPONENT === type) {
				const message = `${userOverride} is connected to ${component.displayName} on the ${board}. ` +
					"Consider selecting it in 'use hardware' above. "
					+ this.formattersMap.getEncodingTag(ResourceConflictText.ON_HARDWARE);
				addWarningToSolution(req.solution, message, ResourceConflictText.ON_HARDWARE);
			} else if (PinType.UNEXPORTED === type) {
				addWarningToSolution(
					req.solution,
					`${userOverride} is not pinned out on the ${board}.  `
					+ this.formattersMap.getEncodingTag(ResourceConflictText.UNPINNED),
					ResourceConflictText.UNPINNED,
				);
			}
		}
	}

	private summarizeErrors(
		deviceRequirements: Device,
		solutionMap: SolutionMap,
		suggestedSolution: SuggestedSolution,
		solveTime: number) {
		_.each(deviceRequirements.interfaceRequirementsMap, (interfaceReq) => {
			let peripheralsSearched = 0;
			_.each(interfaceReq.requirements, (peripheralReq) => {
				if (!(peripheralReq instanceof PeripheralReq)) {
					_.each(peripheralReq.pinRequirements, (pinReq) => {
						if ("" !== pinReq.solution.errorText) {
							if (!pinReq.userOverride && !pinReq.restrictTo) {
								addErrorDetailsToSolution(pinReq.solution, `No free ${peripheralReq.interfaceName} pins are available`);
							} else {
								const type = (pinReq.connectedToHardware || pinReq.userOverride) ? null : PinType.FREE;
								const choices2: DevicePin[] = [];
								this.pinMap.forEachMapping(pinReq.interfacePins, type, (devicePin, peripheralPin) => {
									if (this.unrestrictedChoices.isValid(pinReq, devicePin, peripheralPin)) {
										choices2.push(devicePin);
									}
								});
								if (_.isEmpty(choices2)) {
									if (pinReq.connectedToHardware) {
										addErrorDetailsToSolution(pinReq.solution,
											// eslint-disable-next-line max-len
											"There is no mux configuration that can output any signal of this type to the selected hardware");
									} else {
										addErrorDetailsToSolution(pinReq.solution, "No pins exist that meet this requirement");
									}
								} else {
									_.each(choices2, (choice) => {
										const errorText = this.formattersMap.getEncodingTag(choice) +
											" is currently in use by " +
											// eslint-disable-next-line max-len
											_.map(solutionMap.devicePins[choice.name], (p) => this.formattersMap.getEncodingTag(p)).join(", ");
										addErrorDetailsToSolution(pinReq.solution, errorText);
									});
								}
							}
						} else if (pinReq.used) {
							this.summarizeWarnings(pinReq, solutionMap.devicePins);
						}
					});
				} else {
					// Check for peripheral errors

					if ("" !== peripheralReq.solution.errorText) {
						this.addPeripheralErrorDetails(peripheralReq, solutionMap, !!suggestedSolution);
					} else {
						this.summarizeWarnings(peripheralReq, solutionMap.peripherals);
					}

					// If 8+ peripherals have been searched for, then mark them 
					// with a solver warning.  

					if (!peripheralReq.userOverride && !peripheralReq.canShareWith && solveTime > 1000) {
						++peripheralsSearched;
						if (8 <= peripheralsSearched) {
							addSolverWarningToSolution(peripheralReq.solution);
						}
					}

					// And then errors with the underlying pins

					_.each(peripheralReq.pinRequirements, (pinReq) => {
						if (pinReq.used) {
							if ("" !== pinReq.solution.errorText) {
								this.addPinErrorDetails(
									pinReq,
									peripheralReq,
									solutionMap,
									!!suggestedSolution);
							} else {
								this.summarizeWarnings(pinReq, solutionMap.devicePins);
							}
						}
					});
				}
			});
		});

		deviceRequirements.gpioPinsUsed = this.getGPIOPinsUsed(solutionMap);

		// Append warnings for suggested solutions that weren't valid

		if (suggestedSolution) {
			suggestedSolution.applyWarnings();
		}
	}

	private tryToSolve(
		deviceRequirements: Device,
		restrictToPreferredPins: boolean,
		suggestedSolution: SuggestedSolution,
		powerDomainSettingsEnabled: boolean,
	) {

		// Convert the user's requirements into SAT variables (choices) and clauses (CNF boolean 
		// expressions)

		this.resetChoices(deviceRequirements, restrictToPreferredPins, suggestedSolution, powerDomainSettingsEnabled);
		this.determineChoices(deviceRequirements);
		this.generateClauses();

		// Try to solve

		return solveChoices(this.setOptimizablePinsNeeded);
	}

	private solveImpl(
		deviceRequirements: Device,
		useSuggestedSolution: boolean,
		powerDomainSettingsEnabled: boolean) {
		try {
			// formatNameChoice = (req) => {
			// 	return this.formattersMap.getFormatter({ style: FormatStyle.CLI })(this.formattersMap.getEncodingTag(req));
			// };
			setFormatNameChoice(this.formattersMap);
			const start = new Date().getTime();
			setBudget(glucoseBudget.conflicts, glucoseBudget.propagations, glucoseBudget.restarts);
			setVerbosity(glucoseVerbosity.verbosity, glucoseVerbosity.verbEveryConflicts);

			const suggestedSolution = useSuggestedSolution ? new SuggestedSolution() : null;

			// First, if we have them, try solving with pin preferences, but then solve without them
			// if that generated an error

			let solved = true;
			if (!this.pinMap.pinPreferencesAvailable() ||
				useSuggestedSolution ||
				!this.tryToSolve(deviceRequirements, true, suggestedSolution, powerDomainSettingsEnabled)) {
				solved = this.tryToSolve(deviceRequirements, false, suggestedSolution, powerDomainSettingsEnabled);
			}

			// If we were using a suggested solution, but the solution wasn't valid, then re-solve without
			// suggestions, but make sure to return a warning about that

			if (!solved && suggestedSolution) {
				solved = this.tryToSolve(deviceRequirements, false, null, powerDomainSettingsEnabled);
			}

			// If we still haven't found a solution with all restrictions removed, then start removing 
			// requirements until one is found

			if (!solved) {
				this.findValidSolution(deviceRequirements);
			}

			this.minimizePeripheralUsage();
			this.minimizePowerWarnings();

			const solutionMap = this.applySolution(deviceRequirements);
			this.summarizeErrors(deviceRequirements, solutionMap, suggestedSolution, new Date().getTime() - start);
			this.saveSolution(deviceRequirements, !!suggestedSolution);
		} catch (err) {
			if (err instanceof SATFailure && glucoseBudget.restarts < glucoseBudget.restartsMax) {
				glucoseBudget.restarts *= glucoseBudget.restartsMultiplier;
				if (debug) {
					log("raising budget to " + glucoseBudget.restarts);
				}
				this.solveImpl(deviceRequirements, useSuggestedSolution, powerDomainSettingsEnabled);
			} else {
				throw err;
			}
		}
	}

	private solveProfile(
		deviceRequirements: Device,
		useSuggestedSolution: boolean,
		powerDomainSettingsEnabled: boolean) {
		resetGlucoseTime();
		const start = new Date().getTime();
		const ret = this.solveImpl(deviceRequirements, useSuggestedSolution, powerDomainSettingsEnabled);
		const end = new Date().getTime();
		log("solve() took " + (end - start) + ", " + (end - start - getGlucoseTime()) + " excluding glucose");
		return ret;
	}
}
