import * as _ from "lodash";
import { SimpleEvent } from "./simpleEvent";

export class ErrorStore {

	private readonly event = new SimpleEvent<((error: Error) => void)>();

	private exception: Error = null;

	public registerException(e: Error) {
		// If we already know about an exception, don't replace it. 
		// The second exception is likely because of corrupt state caused by the first exception!

		if (!this.exception) {
			this.exception = e;
			this.event.fire(e);
			this.waiter();
		}
	}

	public onException() {
		return this.event.asRegistration();
	}

	public fetchException() {
		return this.exception;
	}

	public hasException() {
		return null !== this.exception;
	}

	public clearException() {
		this.exception = null;
		this.event.fire(null);
	}

	// For testing only

	public waitForException() {
		return new Promise<void>((resolve) => this.waiter = resolve);
	}

	private waiter = () => { };
}
