import * as _ from "lodash";
import { PinmuxPinInterfaceInstanceMgr } from "../objectManagers/pinmuxPinInterfaceInstance";
import { InterfaceInstanceMgr } from "../objectManagers/interfaceInstance";
import { ModuleInstanceMgr } from "../objectManagers/moduleInstance";
import { ITreeNode, ITreeNodeStatus } from "../../components/TreeNode";
import { TreeNodeStatus } from "./treeStatus";
import { IButtonInfo, IButtonMenuChoice, TreeButtonIcons } from "./button";
import { TreeNodeStatusType } from "../treeNodeStatusType";
import { NodeSelection } from "./nodeSelection";
import { SelectionInNode } from "../../components/actions/selection";
import { RuntimeInstance } from "public/runtime";
import { Validations, ValidationSummary } from "../objectManagers/validations";
import { Tab } from "../tabs";
import { ButtonDisplay } from "../treeNodeButtonDisplay";
import { ActionEnabled } from "../IMyListItem";
export type InstanceMgr = InterfaceInstanceMgr | PinmuxPinInterfaceInstanceMgr | ModuleInstanceMgr;

export const enum InstanceType {
	Module,
	Interface
}

/**
 * Abstract class that creates and tracks managed configuration objects and related object manager. It also
 * manages the runtime of instances and related manager objects.
 */

export abstract class AInstanceContainer<T extends InstanceMgr = InstanceMgr> implements ITreeNode {

	// Currently tracked instances.
	public readonly instances: T[] = [];

	private readonly numberStatus: TreeNodeStatus;
	private readonly iconStatus: TreeNodeStatus;
	private readonly addButtonInfo: AddButtonInfo;
	private expanded = true;
	private readonly nodeSelection: NodeSelection<T>;
	private treeNodePath: string[] = [];
	private parentNode: ITreeNode = null;

	constructor(
		private readonly id: string,
		NodeSelectionClass: new (getInstances: () => T[]) => NodeSelection<T> = NodeSelection,
	) {
		this.id = id.replace(/\s+/g, ""); // will be used as an html id
		this.numberStatus = new TreeNodeStatus(TreeNodeStatusType.TEXT, "interface" + this.id + "Number");
		this.iconStatus = new TreeNodeStatus(TreeNodeStatusType.BADGE, "interface" + this.id + "Icon");
		this.addButtonInfo = new AddButtonInfo(this, "addReqBtn" + this.id);
		this.nodeSelection = new NodeSelectionClass(() => this.getSelectableInstances());
		this.treeNodePath = [this.id];
	}

	public abstract getName(): string;

	public supportsOutputMenuDocking() {
		return false;
	}

	public getUIHash(validations: Validations): string {
		return `${this.getNumberOfUsed()}, ${validations.getSummary(this)}`;
	}

	public getInstanceScriptIdentifier(inst: T) {
		const index = _.findIndex(this.instances, (i) => i === inst);
		return this.getScriptIdentifier() + (index + 1);
	}

	public nextInstanceName(namePrefix: string, startingIndex: number) {
		let candidateName = namePrefix + startingIndex++;
		while (_.find(this.instances, (inst) => inst.getName() === candidateName)) {
			candidateName = namePrefix + startingIndex++;
		}

		return candidateName;
	}

	public removeAllRemovableInstances() {
		const removable = this.getRemovableInstances();
		_.each(removable, (i) => i.remove());
	}

	public instanceAddDisabled() {
		return this.getTotalUsedAcrossContexts() >= this.getMaxAllowed();
	}

	public getInstances() {
		return this.instances;
	}

	public getID() {
		return this.id;
	}

	public getChildren(): ITreeNode[] {
		return [];
	}

	public isTitle() {
		return false;
	}

	public getTooltip() {
		return this.getDescription();
	}

	public getStatus(validations: Validations): ITreeNodeStatus[] {

		const status: ITreeNodeStatus[] = [];

		// generate the number status
		let text = this.getTotalUsedAcrossContexts().toString();
		if (this.getMaxAllowed() < Number.POSITIVE_INFINITY) {
			text += "/" + this.getMaxAllowed();
		}

		// generate status information if something from the container has been added.

		if (this.isAdded()) {

			this.numberStatus.setStatus({
				error: false,
				warning: false,
				success: false,
				text,
			});

			status.push(this.numberStatus);

			const summary = validations.getSummary(this);
			const error = summary === ValidationSummary.Error;
			const warning = summary === ValidationSummary.Warning;
			this.iconStatus.setStatus({
				error,
				warning,
				success: !error && !warning,
			});
			status.push(this.iconStatus);
		}

		return status;
	}

	public isExpanded() {
		return this.expanded;
	}

	public toggleExpanded() {
		this.expanded = !this.expanded;
	}

	public isDisabled() {
		return this.getMaxAllowed() === 0 && this.getNumberOfUsed() === 0;
	}

	public getButtonInfo() {
		return this.addButtonInfo;
	}

	public showButton() {
		return ButtonDisplay.Show;
	}

	public getSelectedMyListItem() {
		return this.nodeSelection.getSelectedMyListItem();
	}

	public treeNodeAddDisabled() {
		return (this.getTotalUsedAcrossContexts() >= this.getMaxAllowed());
	}

	public setShowUserLongDescPref(_status: boolean) {
	}

	public getAlwaysShowUserLongDesc() {
		return false;
	}

	public getSelection() {
		return this.nodeSelection.getSelection();
	}

	public setSelection(selection: SelectionInNode, tabUpdate?: boolean) {
		this.nodeSelection.setSelection(selection, tabUpdate);
	}

	public setParentNode(parentNode: ITreeNode) {
		this.treeNodePath = [...parentNode.getNodePath(), this.id];
		this.parentNode = parentNode;
	}

	public getNodePath() {
		return this.treeNodePath;
	}

	public getParentNode() {
		return this.parentNode;
	}

	public getParentTab(): Tab {
		return null;
	}

	public getUsedPins() {
		const selectedItem = this.getSelectedMyListItem();
		if (selectedItem) {
			return new Set([...selectedItem.getUsedPins(), ...this.getNonInstUsedPins()]);
		} else {
			return this.getNonInstUsedPins();
		}
	}

	public isGraphableNonTopMgr() {
		return false;
	}

	public abstract getScriptIdentifier(): string;
	public abstract getMaxAllowed(): number;
	public abstract getNumberOfUsed(): number;
	public abstract getTotalUsedAcrossContexts(): number;
	public abstract getDisplayName(displayScriptName: boolean): string;
	public abstract getDescription(): string;
	public abstract getNonInstUsedPins(): Set<string>;
	public abstract getRuntimeSelection(): RuntimeInstance;

	protected isAdded() {
		return this.getNumberOfUsed() > 0;
	}

	protected getSelectableInstances() {
		return this.getInstances();
	}

	private getRemovableInstances() {
		return _.filter(this.instances, (i) => i.canRemove().enabled === ActionEnabled.YES);
	}
}

class AddButtonInfo implements IButtonInfo {

	constructor(
		private readonly parent: AInstanceContainer,
		private readonly id: string,
	) {
	}

	public getID() {
		return this.id;
	}

	public getTooltip() {
		let tooltip = "Add " + this.parent.getDisplayName(false);
		const maxAllowed = this.parent.getMaxAllowed();
		const used = this.parent.getTotalUsedAcrossContexts();
		if (used > maxAllowed) {
			tooltip += " (Maximum exceeded)";
		} else if (maxAllowed < Number.POSITIVE_INFINITY) {
			tooltip += " (" + (maxAllowed - used).toString() + " Available)";
		}
		return tooltip;
	}

	public getMenuChoices(): IButtonMenuChoice[] {
		return [];
	}

	public isDisabled() {
		return this.parent.treeNodeAddDisabled();
	}

	public getIcon(): TreeButtonIcons {
		return TreeButtonIcons.ADD;
	}

	public getText(): string {
		return "Add";
	}
}
