import * as _ from "lodash";
import { Port, Connection, ClockTree, Group as GroupDef, IPInstance, Pin } from "clockTree";
import { memoizeOne, sortedFindBy } from "../../../services/utils";
import { Named } from "public/common";
import { GraphSettings } from "../../../services/instanceContainers/clockTreeNode";

// A graph may break connections and show an IPInstance in multiple places.  These interfaces represent nodes/ports on 
// the graph and differ from the original type in that they have an "id" to uniquely represent what they are in the 
// graph should the graph contain duplicates

export type GraphType<T extends {}> = T & { id: string };

export interface IPInstanceNode extends GraphType<IPInstance> {
	inPins: GraphType<Pin>[];
	outPins: GraphType<Pin>[];
}

export interface Edge {
	source: GraphType<Port>;
	target: GraphType<Port>;
	signal: Connection;
	extendAtSource: boolean;
}

interface NodeGroupBase extends Named {
	id: string;
	ipInstances: IPInstanceNode[];	// The ip instances that are in this group	
	groups: NodeGroupBase[];		// The sub-groups contained in this group	
}

interface NodeGroup extends NodeGroupBase {
	containedMembers: string[];		// The names of all ip instances in this group and all sub groups
	groups: NodeGroup[];			// Re-typed so that containedMembers exists on sub groups
}

export interface GraphGroup extends NodeGroupBase {
	groups: GraphGroup[]			// Re-typed so that edges exists on sub groups
	edges: Edge[];					// The edges that start or end in this group
}

// Clone the ipInstance and include properties needed for graphing

function toNode(ipInstance: IPInstance) {
	return {
		...ipInstance,
		id: ipInstance.name,
		inPins: _.map(ipInstance.inPins, (p) => ({ ...p, id: ipInstance.name + p.name })),
		outPins: _.map(ipInstance.outPins, (p) => ({ ...p, id: ipInstance.name + p.name })),
	};
}

// Creates an unfiltered NodeGroup based on the clock tree data

const getRootNodeGroup = memoizeOne((ctt: ClockTree) => {

	// Takes a group definition and transforms it into a NodeGroup

	function processGroup(group: GroupDef): NodeGroup {
		const ipInstances = _.map(group.ipInstances, (instName) => toNode(sortedFindBy(ctt.ipInstances, instName, "name")));
		const groups = _.map(group.groups, processGroup);
		const containedMembers = _.sortBy([
			...group.ipInstances,
			..._.flatMap(groups, (g) => g.containedMembers),
		]);

		return {
			id: group.name,
			name: group.name,
			displayName: group.displayName,
			ipInstances,
			groups,
			containedMembers,
		};
	}

	// Create a "root" group to contain all defined groups.
	// Any ip instances that are not in a group are considered to be in this group

	const groups = _.map(ctt.groups, processGroup);
	const instsInAGroup = _.flatMap(groups, (g) => g.containedMembers);
	const ipInstances = _.chain(ctt.ipInstances)
		.reject((inst) => _.includes(instsInAGroup, inst.name))
		.map(toNode)
		.value();
	const containedMembers = _.map(ctt.ipInstances, (inst) => inst.name);
	return {
		id: "root",
		name: "root",
		displayName: "",
		groups,
		ipInstances,
		containedMembers,
	};
});

// Returns a NodeGroup that is filtered to only include the ip instances specified, and the groups that contain them

function generateNodeGroups(ctt: ClockTree, releventInstances: string[]): NodeGroup {

	const sortedReleventInstances = _.sortBy(releventInstances);
	function filterGroup(group: NodeGroup): NodeGroup {
		const groups = _.chain(group.groups)
			.filter((g) => _.some(g.containedMembers, (i) => sortedincludes(sortedReleventInstances, i)))
			.map(filterGroup)
			.value();
		const ipInstances = _.filter(group.ipInstances, (i) => sortedincludes(sortedReleventInstances, i.name));
		const containedMembers = _.intersection(group.containedMembers, sortedReleventInstances);

		return {
			...group,
			groups,
			ipInstances,
			containedMembers,
		};
	}

	return filterGroup(getRootNodeGroup(ctt));
}

// Oscillators are drawn as a circle, but elk assumes all nodes are square.  So if they have multiple out ports, the 
// ports would not be centered, so we'd need to extend the line from the containing square that elk uses in to the 
// inner circle that we draw.  This function detects that.

export function connectionRequiresExtension(ipInstance: IPInstance) {
	return ipInstance.shape === "Oscillator" && _.size(ipInstance.outPins) === 2;
}

// Return all edges that connect elements of the group with other elements in the group or a contained group

function generateEdges(connectivity: Connection[], group: NodeGroup): Edge[] {
	const instancesInGroup = _.map(group.ipInstances, (inst) => inst.name);
	const instancesToExtend = _.chain(group.ipInstances)
		.filter(connectionRequiresExtension)
		.map((inst) => inst.name)
		.value();
	return _.flatMap(connectivity, (c) => {
		return _.chain(c.targets)
			.filter((t) => {
				return (sortedincludes(instancesInGroup, c.source.instName) && sortedincludes(group.containedMembers, t.instName)) ||
					(sortedincludes(group.containedMembers, c.source.instName) && sortedincludes(instancesInGroup, t.instName));
			})
			.map((target) => ({
				source: { ...c.source, id: c.source.instName + c.source.pinName },
				target: { ...target, id: target.instName + target.pinName },
				signal: c,
				extendAtSource: _.includes(instancesToExtend, c.source.instName),
			}))
			.value();
	});
}

// Recursively creates edges for the nodes in the node group

function connectNodes(connectivity: Connection[], group: NodeGroup): GraphGroup {
	const groups = _.map(group.groups, (g) => connectNodes(connectivity, g));
	const edges = generateEdges(connectivity, group);
	return {
		...group,
		groups,
		edges,
	};
}

// Create a GraphGroup object based on the clock tree data that includes only the indicated nodes.  Break connections 
// in the as indicated by the settings

export function generateGraphGroup(ctt: ClockTree, releventInstances: string[], graphSettings: GraphSettings) {
	const nodeGroup = generateNodeGroups(ctt, releventInstances);
	const graphGroup = connectNodes(ctt.connectivity, nodeGroup);
	breakConnections(graphGroup, graphSettings);
	return graphGroup;
}

function sortedincludes<T>(arr: T[], value: T) {
	return -1 !== _.sortedIndexOf(arr, value);
}

// Recursively break connections as requested in the group and all sub groups

function breakConnections(group: GraphGroup, graphSettings: GraphSettings) {
	if (!_.isEmpty(graphSettings.brokenConnections)) {
		_.each(group.groups, (g) => breakConnections(g, graphSettings));
		breakConnectionsOfType(group, graphSettings, applyAlgorithmToTarget);
		breakConnectionsOfType(group, graphSettings, applyAlgorithmToSource);
	}
}

function isEqualPort(a: Port, b: Port) {
	return a.instName === b.instName && a.pinName === b.pinName;
}

// All the functions below this point are written assuming that a connection is being broken at its target.  However, 
// the algorithms are equally valid to apply to the connection source, only certain keys must be reversed.  These maps
// will return either the expected or opposite keys so that the same algorithms can be applied to break connections
// from either end.

const applyAlgorithmToTarget = {
	source: "source",
	target: "target",
	inPins: "inPins",
	outPins: "outPins",
} as const;

const applyAlgorithmToSource = {
	source: "target",
	target: "source",
	inPins: "outPins",
	outPins: "inPins",
} as const;

type OperateOn = typeof applyAlgorithmToTarget | typeof applyAlgorithmToSource

// Iterates through each requested connection to break and re-connects the original edge to a new isolated named 
// connection node

function breakConnectionsOfType(group: GraphGroup, { brokenConnections }: GraphSettings, operateOn: OperateOn) {
	const { target, source } = operateOn;

	_.each(brokenConnections, (connectionToBreak) => {

		// Find (if any) the edge where its connection target matches the requested connection to break

		const edgeToBreak = _.find(group.edges, (e) => isEqualPort(connectionToBreak, e[target]));
		if (edgeToBreak) {

			// We've found an edge that we've been told to break.  Generate a new unique id for the edge and ports to
			// use to connect, and re-target the edge we found so it's source uses that id

			const id = `$brokenAt_${edgeToBreak[target].instName}_${edgeToBreak[target].pinName}`;
			edgeToBreak[source].id = id;

			// Find the node that the edge used to connect to, which must be a named connection.  Create a new named
			// connection node that connects only to the port where the break was indicated.  This provides a nice
			// line and label just to this port that is not connected anywhere else.

			const node = _.find(group.ipInstances, (i) => i.name === edgeToBreak[source].instName);
			if (node.shape !== "NamedConnection") {
				throw new Error("Only named connections (those with a displayName) can only be broken");
			}
			createIsolatedConnectionNode(group, node, connectionToBreak.name, id, operateOn);

			// The original named connection may not have ports that are connected to anything any more.  We need to
			// remove them, and potentially the whole node should it have no ports at all.

			removeUnusedPorts(group, node, operateOn);
		}
	});
}

// Create a new named connection node, based on the old node, that connects only to one port.

function createIsolatedConnectionNode(
	group: GraphGroup, node: IPInstanceNode, newNodeId: string, newConnectionId: string, { inPins, outPins }: OperateOn
) {
	group.ipInstances.push({
		...node,
		id: newNodeId ?? (newConnectionId + "_inst"),
		[inPins]: [],
		[outPins]: [{
			..._.first(node[outPins]),
			id: newConnectionId,
		}],
	});
}

// Remove any unused ports (pins) from the node now that a connection has been severed.  If the node has no connections
// at all, remove it entirely

function removeUnusedPorts(group: GraphGroup, node: IPInstanceNode, operateOn: OperateOn) {
	const { source, inPins, outPins } = operateOn;
	if (!_.some(group.edges, (e2) => e2[source].id === node[outPins][0].id)) {
		if (_.isEmpty(node[inPins])) {
			_.pull(group.ipInstances, node);
		} else {
			const index = _.indexOf(group.ipInstances, node);
			group.ipInstances[index] = {
				...node,
				[outPins]: [],
			};
		}
	}
}
