import { InterfaceInstanceMgr } from "../objectManagers/interfaceInstance";
import { FormatStyle, CLIFormatOptions, UIFormatOptions, FormatOptions } from "./formattingTypes";
import { FormattedLink, FormattedMsgPart } from "./link";
import { assertUnreachable } from "../utils";
import { format as formatInterface } from "./interfaceFormatter";
import * as _ from "lodash";

export function format(parentMgr: InterfaceInstanceMgr, options: CLIFormatOptions, member?: string): string;
export function format(parentMgr: InterfaceInstanceMgr, options: UIFormatOptions, member?: string): FormattedLink;
export function format(parentMgr: InterfaceInstanceMgr, options: FormatOptions, member?: string): FormattedMsgPart;
export function format(parentMgr: InterfaceInstanceMgr, options: FormatOptions, member?: string): FormattedMsgPart {

	switch (options.style) {
		case FormatStyle.CLI:
			return formatCLI(parentMgr, options, member);
		case FormatStyle.UI:
			return formatUI(parentMgr, options, member);
		default:
			assertUnreachable(options);
			return "";
	}
}

function formatCLI(parentMgr: InterfaceInstanceMgr, options: CLIFormatOptions, member?: string) {
	const self = formatInterface(parentMgr, options, "$pinGroup");
	return member ? `${self}.${member}` : self;
}

function formatUI(parentMgr: InterfaceInstanceMgr, options: UIFormatOptions, member?: string) {
	if (!member) {
		return formatInterface(parentMgr, options, "$pinGroup");
	}
	const multiPinMgr = parentMgr.getMultiPinMgr();
	const pinName = multiPinMgr.memberMgrs[member].def.name;
	const multiPinGroupName = parentMgr.memberMgrs.$pinGroup.def.name; // replace $pinGroup with the actual pin
	const parentFormatted = formatInterface(parentMgr, options, "$pinGroup");
	parentFormatted.destination.memberPath = _.map(parentFormatted.destination.memberPath, (n) =>
		_.replace(n, multiPinGroupName, pinName));
	return parentFormatted;
}
