import * as _ from "lodash";

import { getToolVersion } from "../pinmux/services/toolVersion";
import { ArgsError, MissingArgsError, ResolvedArgs, SetupError } from "../pinmux/services/args/argTypes";
import { generateOutput, listOutput, ScriptStatus } from "./cli_core";
import { usageText } from "./usageText";
import { fs } from "../pinmux/services/fileSystem";
import { createLoader } from "../pinmux/services/resources/otherLoaders/scriptAndProductLoader";
import { createCLIAvailableProductsfromPath } from "../pinmux/services/product/available";
import { ErrorStore } from "../pinmux/services/errorStore";
import { InvalidMinToolVersion } from "../pinmux/services/product/versionCheck";
import { parseAndResolveArgs } from "../pinmux/services/args/parseAndResolveArgs";
import { getOptionsText } from "./help";
import { HttpError } from "../pinmux/services/http";

export async function runCLI(argv: string[]) {
	if (_.includes(argv, "--help")) {
		log(`${usageText}\n${getOptionsText()}`);
		return 0;
	}

	if (_.includes(argv, "--version")) {
		log(`${getToolVersion()}`);
		return 0;
	}

	const errorStore = new ErrorStore();
	const cliAvailableProducts = createCLIAvailableProductsfromPath();

	try {
		// Merge and validate common args
		const resolvedArgs = await parseAndResolveArgs(argv, createLoader(fs), cliAvailableProducts);
		validateArgsForCLI(resolvedArgs);

		const status = (resolvedArgs.listGeneratedFiles || resolvedArgs.listReferencedFiles) ?
			await listOutput(resolvedArgs, errorStore) :
			await generateOutput(resolvedArgs, errorStore);

		if (errorStore.hasException()) {
			throw errorStore.fetchException();
		}
		if (ScriptStatus.ERROR === status) {
			return 1;
		} else {
			return 0;
		}
	} catch (e) {
		handleCLIError(e);
		return 1;
	}
}

function handleCLIError(e: unknown) {
	if (e instanceof ArgsError) {
		logError(e.message);
		log(usageText);
	} else if (e instanceof InvalidMinToolVersion || e instanceof SetupError) {
		logError(e.message);
	}
	else if (e instanceof HttpError) {
		logError(e.response + " " + e.stack);
	} else if (e instanceof Error) {
		logError(e.stack);
	} else {
		logError(e.toString());
	}
}

function validateArgsForCLI(resolvedArgs: ResolvedArgs) {
	if (_.every(resolvedArgs.script, (scriptArgs) => !scriptArgs.script)) {
		throw new MissingArgsError("Missing argument: --script");
	}
	if (_.every(resolvedArgs.script, (scriptArgs) => !scriptArgs.output)) {
		throw new MissingArgsError("Missing argument: --output");
	}
	_.each(resolvedArgs.script, ({ output }) => {
		if (output && fs.fileExists(output) && fs.isFile(output)) {
			throw new ArgsError(`${output} must be a directory`);
		}
	});
}

function logError(msg: string) {
	console.error(msg);
}

function log(msg: string) {
	console.log(msg); // eslint-disable-line no-console
}
