import { Divider, IPInstance, Multiplier } from "clockTree";
import * as _ from "lodash";
import { NameConfigurable, PinFrequencyConfigurable, StandardConfigurable } from "public/defs";
import { Module } from "public/runtime";
import { ITreeNode } from "../../components/TreeNode";
import { getConfigurationChangeNumber } from "../changeNumber";
import { discriminate, IPInstanceShape } from "../clockTree/discriminate";
import { SCHEMA } from "../JSONschemaValidator";
import { Runtime } from "../resources/runtime";
import { createModuleInstanceFindStatement } from "../scripting/serialize";
import { TabName } from "../tabNames";
import { assertUnreachable, getDisplayName, memoizeOne } from "../utils";
import { BooleanConfigurableMgr } from "./configurables/booleanConfigurableMgr";
import { createMetaContentConfigurableMgr, validateConfigurable } from "./configurables/configurable";
import { EnumerationConfigurableMgr } from "./configurables/enumerationConfigurableMgr";
import { PinFrequencyConfigurableMgr } from "./configurables/pinFrequencyConfigurableMgr";
import { ModuleInstanceMgr } from "./moduleInstance";
import { NameMemberMgr } from "./name";
import { ActionEnabled, ActionState } from "../IMyListItem";

/**
 * A ModuleInstanceMgr that is tied to a specific ip instance in the clock tree
 */
export class ClockIpInstanceMgr extends ModuleInstanceMgr {

	private static getUsedMemo = memoizeOne((ipInstances: ClockIpInstanceMgr[], _configurationId: number) => {

		// Find all the terminal ip instances, or the ones that indicate they are "in use" due to something else.  Then
		// take the input pins to those instances and find every signal that feeds into them.  The instances connected 
		// to those signals can be considered "used"

		return _.chain(ipInstances)
			.filter((inst) => {
				if (inst.overrides$isUsed) {
					return inst.managedObject.$isUsed;
				}
				return inst.isTerminalNode(ipInstances);
			})
			.flatMap((i) => i.getInputPins())
			.thru((pins) => PinFrequencyConfigurableMgr.getUsed(pins))
			.map((port) => (port.parentObjectMgr as ClockIpInstanceMgr))
			.uniq()
			.value();
	});

	public static createInstance(
		runtime: Runtime,
		mod: Module,
		ipInstance: IPInstance) {

		return ModuleInstanceMgr.createInstanceImpl(runtime, mod, () => new ClockIpInstanceMgr(runtime, mod, ipInstance));
	}

	// Based on the current set of instances, which instances are used based (ie actually feed into the terminal 
	// instances)

	public static getUsed(ipInstances: ClockIpInstanceMgr[]) {
		return ClockIpInstanceMgr.getUsedMemo(ipInstances, getConfigurationChangeNumber());
	}

	private mostRecentTreeNode: ITreeNode;
	private overrides$isUsed = false;

	protected constructor(
		runtime: Runtime,
		module: Module,
		private readonly ipInstance: IPInstance,
	) {
		super(runtime, module, false);

		this.addFixedMember(this.runtime.getFormattersMap(), "$ipInstance", ipInstance);
	}

	// Nothing can own a clock tree module instance - it is always associated directly with a specific ip instance 
	// block.  Likewise, $hardware is always null for these modules.

	public override getContainingInstanceMgrs() {
		return [this];
	}

	// Returns all the tree nodes we should tag errors/warnings on

	public override getContainingTreeNodes() {

		const nodes = this.runtime.lookupNodes(this.ipInstance);
		if (!nodes) {
			return [];
		}

		// If there's an error on a key node (system oscillator, or main PLL), then it will be possible to view the 
		// error in almost EVERY node.  That isn't ideal as it makes things look really bad.  So, if there are default
		// views for the ip instance, use that instead.

		const { defaultViews, views } = nodes;
		if (!_.isEmpty(defaultViews)) {
			return defaultViews;
		}

		// If there isn't a default view, look for a view with the same display name, as that's likely the intended
		// default view

		const sameNamedNode = _.find(views, (n) => n.getDisplayName(false) === getDisplayName(this.ipInstance, false));
		if (sameNamedNode) {
			return [sameNamedNode];
		}

		// Otherwise, we have no choice but to say you can see this error in multiple left-pane locations...

		return views;
	}

	// Returns the single tree node we should navigate to to see this ipInstance.

	public override getLeafTreeNode() {

		// Ideally, use the tree node most recently viewed.  That has the advantage that forward/backward navigation 
		// will actually include the tree node being used.  However, if it hasn't been viewed yet (error on a graph not
		// yet viewed), then use the arbitrarily first node in the containing nodes.

		return this.mostRecentTreeNode ?? _.first(this.getContainingTreeNodes());
	}

	// Indicate that this inst was *just* viewed via this tree node

	public viewedUsing(treeNode: ITreeNode) {
		this.mostRecentTreeNode = treeNode;
	}

	public isDisabled() {
		if (this.memberMgrs.disabled) {
			return (this.memberMgrs.disabled as BooleanConfigurableMgr).getValue();
		}
		if (!_.isEmpty(this.ipInstance.inPins)) {
			const inPinNames = _.map(this.ipInstance.inPins, ({ name }) => name);
			return _.every(inPinNames, (name) => {
				const value = (this.memberMgrs[name] as PinFrequencyConfigurableMgr).getValue();
				return value === 0 || (_.isArray(value) && value[0] === 0 && value[1] === 0);
			});
		} else {
			const outPinNames = _.map(this.ipInstance.outPins, ({ name }) => name);
			return _.every(outPinNames, (name) => {
				const value = (this.memberMgrs[name] as PinFrequencyConfigurableMgr).getValue();
				return value === 0 || (_.isArray(value) && value[0] === 0 && value[1] === 0);
			});
		}
	}

	public override getPrimaryTab() {
		return TabName.CLOCKTREE;
	}

	// Cannot remove ever - it's associated with the static clock tree

	public override canRemove(): ActionState {
		return { enabled: ActionEnabled.NEVER };
	}

	public override isEverRemovable() {
		return false;
	}

	public getIpInstance() {
		return this.ipInstance;
	}

	// Allow input pins to be added after construction once the connectivity is established

	public addInputPin(def: Pick<PinFrequencyConfigurable, "name" | "getValue">) {
		if (def.name in this.memberMgrs) {
			(this.memberMgrs[def.name] as PinFrequencyConfigurableMgr).updateDefinition(def.getValue);
		} else {
			const fullDef = {
				...def,
				hidden: true,
				default: 0,
				displayName: _.find(this.ipInstance.inPins, (p) => p.name === def.name).displayName,
			};
			const configurable = this.createMetaContentConfigurableMgr(fullDef) as PinFrequencyConfigurableMgr;
			this.nonObjectMembers.push(configurable);
			this.builtInMembers.push(configurable);
		}
	}

	// Returns the text to use for a label in a graph for a node representing this module

	public override getGraphLabel(showScriptingNames: boolean) {
		return getDisplayName(this.ipInstance, showScriptingNames);
	}

	// Returns the text to use for a title in the configurables pane in a graph view

	public override getGraphConfigurablesTitle(showScriptingNames: boolean) {
		return this.getGraphLabel(showScriptingNames);
	}

	// Returns the tooltip for a module when viewed in a graph

	public override getToolTip() {
		return super.getToolTip() ?? this.ipInstance.description;
	}

	public override canCopy(): ActionState {
		return { enabled: ActionEnabled.NEVER };
	}

	// The name should be created to match the associated ip instance's name

	protected override createNameMemberMgr(nameConfig: NameConfigurable) {

		validateConfigurable(nameConfig, `Configurable "$name" of "${this.module.$name}"`, SCHEMA.NameConfigurable);

		const config = {
			...nameConfig,
			default: this.ipInstance.name,
		};

		const isHidden = !this.isTopModule() && nameConfig.hidden !== false;

		return {
			id: this.ipInstance.name,
			nameMemberMgr: new NameMemberMgr(this, this.runtime.getFormattersMap(), config,
				{
					isReadOnly: true,
					isHidden,
					displayName: this.ipInstance.displayName,
				}),
		};
	}

	// Same as parent version, but passes along ipInstance so that pin configurables can be identified

	protected override createMetaContentConfigurableMgr(def: StandardConfigurable) {
		return createMetaContentConfigurableMgr(
			def,
			this,
			this.module.$name,
			this.runtime,
			false,
			this.ipInstance,
			this.runtime.getTopModules().getFrequencyFormat());
	}

	// We want to pass $ipInstance to the extendConfig function

	protected override getExtendConfigArgs() {
		return { $ipInstance: this.ipInstance };
	}

	// Call the parent version, but then validate that all output pins were defined by the meta-content

	protected override initMetaConfigurables() {
		super.initMetaConfigurables();

		this.add$isUsedConfigurable();

		this.validateMetaConfigurables();

		this.supplyPinDisplayNames();
	}

	// Instead of calling addModule/addInstance, we need to find the pre-existing instance

	protected override createAddInstanceStatements(scriptIdentifier: string) {
		return [createModuleInstanceFindStatement(scriptIdentifier, this.getName())];
	}

	private add$isUsedConfigurable() {
		if (this.memberMgrs.$isUsed) {
			if (!(this.memberMgrs.$isUsed instanceof BooleanConfigurableMgr)) {
				throw new Error(`${this.getName()} (${this.module.$name}) defined a non-boolean configurable named '$isUsed'`);
			}
			this.overrides$isUsed = true;
		} else {
			new BooleanConfigurableMgr(this, this.runtime.getFormattersMap(), {
				name: "$isUsed",
				hidden: true,
				default: true,
				getValue: () => _.includes(ClockIpInstanceMgr.getUsed(this.runtime.getIpInstanceMgrs()), this),
			});
		}
	}

	private validateMetaConfigurables() {

		// Check that optional "disabled" configurable is a boolean

		if (this.memberMgrs.disabled && !(this.memberMgrs.disabled instanceof BooleanConfigurableMgr)) {
			throw new Error(`${this.getName()} (${this.module.$name}) defined a non-boolean configurable named 'disabled'`);
		}

		// Check output pins were defined

		if (!_.every(this.ipInstance.outPins, (pin) => pin.name in this.memberMgrs)) {
			const missingPins = _.chain(this.ipInstance.outPins)
				.reject((pin) => pin.name in this.memberMgrs)
				.map((pin) => pin.name)
				.join(", ")
				.value();
			throw new Error(`${this.getName()} (${this.module.$name}) did not define configurables for ${missingPins}`);
		}

		// Check that specific configurables required for specific UI shapes are valid

		this.validateSpecificConfigurables();
	}

	private validateSpecificConfigurables() {
		const discriminated = discriminate(this.ipInstance);
		switch (discriminated.shape) {
			case IPInstanceShape.DIVIDER:
				this.validateDividerConfigurables(discriminated.ipInstance);
				break;
			case IPInstanceShape.MUX:
				this.validateMuxConfigurables();
				break;
			case IPInstanceShape.MULTIPLIER:
				this.validateMultiplerConfigurables(discriminated.ipInstance);
				break;
			case IPInstanceShape.GATE:
				this.validateGateConfigurables();
				break;
			case IPInstanceShape.PIN_FUNCTION:
			case IPInstanceShape.OSCILLATOR:
			case IPInstanceShape.ADDER:
			case IPInstanceShape.NAMED_CONNECTION:
			case IPInstanceShape.LARGE_SQUARE:
			case IPInstanceShape.MEDIUM_SQUARE:
			case IPInstanceShape.SMALL_SQUARE:
				break;
			default:
				assertUnreachable(discriminated);
		}
	}

	private validateGateConfigurables() {
		if (this.memberMgrs.enable && !(this.memberMgrs.enable instanceof BooleanConfigurableMgr)) {
			throw new Error(`${this.getName()} (${this.module.$name}) exposed an 'enable' configurable that was not a boolean`);
		}
	}

	private validateMultiplerConfigurables(ipInstance: Multiplier) {
		if (_.size(ipInstance.multiplyValues) > 1
			&& !(this.memberMgrs.multiplyValue instanceof EnumerationConfigurableMgr)) {
			throw new Error(`${this.getName()} (${this.module.$name}) did not expose a 'multiplyValue' configurable`);
		}
	}

	private validateMuxConfigurables() {
		if (!(this.memberMgrs.inputSelect instanceof EnumerationConfigurableMgr)) {
			throw new Error(`${this.getName()} (${this.module.$name}) did not expose a 'inputSelect' configurable`);
		}
	}

	private validateDividerConfigurables(ipInstance: Divider) {
		if (_.size(ipInstance.divideValues) > 1
			&& !(this.memberMgrs.divideValue instanceof EnumerationConfigurableMgr)) {
			throw new Error(`${this.getName()} (${this.module.$name}) did not expose a 'divideValue' configurable`);
		}
	}

	private getInputPins() {
		return _.map(this.ipInstance.inPins, (p) => this.memberMgrs[p.name]) as PinFrequencyConfigurableMgr[];
	}

	// Returns true if the node would be considered "terminal" in a graph with the supplied other nodes.  A terminal 
	// node is one without any outputs to elsewhere in the same graph.

	private isTerminalNode(ipInstances: ClockIpInstanceMgr[]) {
		return _.every(this.ipInstance.outPins, (pin) => {
			const { connectivity } = this.runtime.getClockTreeGraph();
			const connection = _.find(connectivity, (c) => c.source.instName === this.ipInstance.name && c.source.pinName === pin.name);
			return _.every(connection.targets, (t) => !_.some(ipInstances, (i) => t.instName === i.getID()));
		});
	}

	private supplyPinDisplayNames() {
		_.each([...this.ipInstance.inPins, ...this.ipInstance.outPins], (pin) => {
			const memberMgr = this.memberMgrs[pin.name];
			if (memberMgr) {
				memberMgr.def.displayName ??= pin.displayName;
			}
		});
	}
}
