import * as _ from "lodash";
// ------------------------------------------------------------------------------------------------
// ClauseGenerator
// A "clause" in this domain is a boolean algebra expression that must be true that consists only 
// of boolean literals, NOTs of those literals, and ORs.  Since all must be true, they can be 
// thought of as all be ANDed together in one super expression.  The SAT solver (glucose) is then
// responsible for solving such that all clauses are true.  We treat the various choices in the 
// system as literals, so the SAT solver will tell us what choices to take.
//
// This file is an abstraction for creating clauses in to the above notation (CNF) based on real-
// world understandable meanings.  For instance, the mutuallyExclude function creates boolean 
// expressions that ensures that the two choices can never both be taken
// ------------------------------------------------------------------------------------------------

import { AbstractChoice, IChoice, PartiallyShared } from "./choiceFactories/common";
import { addLiteral, endClause } from "./clauses";

export interface Iterable<K, V> {
	forEach(callbackfn: (value: V, index: K) => void): void;
}

// Glucose represents "not" as a negative version of the literal

export function not(choiceId: number) {
	return -choiceId;
}

export function mutuallyExclude(a: IChoice, b: IChoice, comments: string, warning?: IChoice) {
	addLiteral(not(a.id));
	addLiteral(not(b.id));
	if (warning) {
		addLiteral(warning.id);
	}
	endClause(comments);
}

// Each entry in choiceMap is an array of choices where at most one can be taken

export function mutuallyExclusive<Key, ChoiceType extends AbstractChoice>(
	choiceMap: Iterable<Key, ChoiceType[]>, getWarning: (choiceName: Key) => AbstractChoice, comments: string) {

	choiceMap.forEach((choices, choiceName) => {

		// Since we deal with and's of or's, we individually exclude every 
		// combination

		for (let i = 0; i < choices.length; ++i) {
			for (let j = i + 1; j < choices.length; ++j) {
				mutuallyExclude(choices[i], choices[j], comments, getWarning ? getWarning(choiceName) : null);
			}
		}
	});
}

// Each entry in choiceMap contains a group of choices that must be mutually
// excluded with everything, and another map of choices that must be excluded 
// with everything that doesn't share the same key.  This handles the case 
// where choices must all be mutually exclusive, except a few exceptions

export function mutuallyExcludeUnsharedChoices<Key, ChoiceType extends AbstractChoice>(
	choiceMap: Iterable<Key, PartiallyShared<ChoiceType>>, comments: string) {

	choiceMap.forEach((choices) => {

		// Everything under "mutuallyExclusive" must be so with itself

		mutuallyExclusive([choices.mutuallyExclusive], null, comments);

		// Everything that's shareable must individually be excluded from everything else

		if (choices.shareable) {
			const keys = _.keys(choices.shareable);
			for (let i = 0; i < keys.length; ++i) {
				const sharedChoices = choices.shareable[keys[i]];

				// Exclude each choice with everything under "mutuallyExclusive"

				_.each(sharedChoices, (sharedChoice) => {
					_.each(choices.mutuallyExclusive, (choice) => mutuallyExclude(choice, sharedChoice, comments));
				});

				// And then exclude each choice with every other choice under 
				// the other "shareable" keys

				for (let j = i + 1; j < keys.length; ++j) {

					const otherSharedChoices = choices.shareable[keys[j]];
					_.each(sharedChoices, (sharedChoice) => {
						_.each(otherSharedChoices, (otherSharedchoice) => mutuallyExclude(otherSharedchoice, sharedChoice, comments));
					});
				}
			}
		}
	});
}

// Each entry in choiceMap is an array of choices than can only be taken if the
// key (another choice) is also taken

export function dependentChoices<ChoiceType extends AbstractChoice>(
	choiceMap: Iterable<number, ChoiceType[]>, comments: string) {

	choiceMap.forEach((choices, choiceName) => {
		_.each(choices, (choice) => {

			// Forbid each choice if the dependent choice is not chosen

			addLiteral(not(choice.id));
			addLiteral(choiceName);
			endClause(comments);
		});
	});
}

// Each array in choiceMap must have at least one of the choices chosen

export function chooseAtLeastOneOf<Key, ChoiceType extends AbstractChoice>(
	choiceMap: Iterable<Key, ChoiceType[]>, getError: (choiceName: Key) => AbstractChoice, comments: string) {

	choiceMap.forEach((choices, choiceName) => {
		_.each(choices, (choice) => {
			addLiteral(choice.id);
		});
		if (getError) {
			addLiteral(getError(choiceName).id);
		}
		endClause(comments);
	});
}

// One of the choices in "onlyIfOneOf" must be true, or the "toAllow" choice is forced to false.

export function allowOnlyIfOneOf(toAllow: number, onlyIfOneOf: IChoice[], comments: string) {
	addLiteral(not(toAllow));
	_.each(onlyIfOneOf, (choice) => addLiteral(choice.id));
	endClause(comments);
}

// Each entry in choiceMap must have at least one of the choices chosen, but 
// only if the key (another choice) is also chosen

export function chooseAtLeastOneOfOnlyIf<ChoiceType extends AbstractChoice>(
	choiceMap: Iterable<number, ChoiceType[]>, getError: (choiceName: number) => AbstractChoice, comments: string) {

	choiceMap.forEach((choices, choiceName) => {
		if (getError) {
			addLiteral(getError(choiceName).id);
		}
		allowOnlyIfOneOf(choiceName, choices, comments);
	});
}

// Exactly one choice per entry in choiceMap must be chosen

export function chooseOneOf<Key, ChoiceType extends AbstractChoice>(
	choiceMap: Iterable<Key, ChoiceType[]>, getError: (choiceName: Key) => AbstractChoice, comments: string) {
	// First, add a clause that's the or of every member of each group.  That 
	// ensures at least one is chosen.

	chooseAtLeastOneOf(choiceMap, getError, comments + " (at least one of)");

	// But, since we only want one, make the mutually exclusive

	mutuallyExclusive(choiceMap, null, comments + " (but only one)");
}

// Exactly one choice per entry in choiceMap must be chosen, but only if the
// key (another choice) is also chosen

export function chooseOneOfOnlyIf<ChoiceType extends AbstractChoice>(
	choiceMap: Iterable<number, ChoiceType[]>, getError: (choiceName: number) => AbstractChoice, comments: string) {
	// First, add a clause that's the or of every member of each group.  That 
	// ensures at least one is chosen.

	chooseAtLeastOneOfOnlyIf(choiceMap, getError, comments + " (at least one of)");

	// Next, if onlyIf is true, then explicitly forbid any choice if the dependent
	// choice is not chosen

	dependentChoices(choiceMap, comments + " (forbid if the dependent choice is not chosen)");

	// But, since we only want one, make the mutually exclusive

	mutuallyExclusive(choiceMap, null, comments + " (but only one)");
}

// Each choice in the collection must be taken

export function chooseAll<Key, ChoiceType extends AbstractChoice>(
	overrides: Iterable<Key, ChoiceType>, getError: (choiceName: Key) => AbstractChoice, comments: string) {
	// If the user overrides a choice and fixes it, well then that choice must 
	// be taken.  Just add that id in it's own clause to force it to true.

	overrides.forEach((override, overrideName) => {
		addLiteral(override.id);
		if (getError) {
			addLiteral(getError(overrideName).id);
		}
		endClause(comments);
	});
}
