import * as _ from "lodash";
import * as path from "path";
import { FS } from "../../fileSystem";
import { http, HttpError } from "../../http";
import { storage } from "../../storage";
import { isCloud } from "../../platform";
import { convertUnknownToError } from "../../utils";

export interface ScriptAndProductLoader {
	readScriptFile(scriptPath: string): Promise<string>;
	readProductFile(productPath: string): Promise<string>;
	resolve(pathToResolve: string): string;
}

export class ScriptLoadError extends Error {
	constructor(public originalError: Error, public script: string) {
		super(originalError.message);
	}
}

class LocalLoader implements ScriptAndProductLoader {

	private path = require("path");

	constructor(private readonly fs: Pick<FS, "cwd" | "readFile" | "fileExists" | "isFile">) { }

	public async readScriptFile(scriptPath: string) {
		try {

			return await this.asyncReadFile(scriptPath);
		} catch (e) {
			throw new ScriptLoadError(convertUnknownToError(e), scriptPath);
		}
	}

	public readProductFile(productPath: string) {
		return this.asyncReadFile(productPath);
	}

	public resolve(pathToResolve: string): string {
		return this.path.resolve(this.fs.cwd(), pathToResolve);
	}

	private asyncReadFile(filePath: string) {
		if (!this.fs.fileExists(filePath)) {
			return Promise.reject(new Error(`File "${filePath}" does not exist`));
		} else if (!this.fs.isFile(filePath)) {
			return Promise.reject(new Error(`${filePath} is a directory`));
		} else {
			let result: string;
			try {
				result = this.fs.readFile(filePath);
			} catch (e) {
				return Promise.reject(new Error(`Failed to load ${filePath}: ${convertUnknownToError(e).message}`));
			}
			return Promise.resolve(result);
		}
	}
}

class CloudLoader implements ScriptAndProductLoader {
	public async readScriptFile(scriptPath: string): Promise<string> {
		// the script file may be a reference design in which case it won't be in the user's workspace
		if (_.startsWith(scriptPath, "/mnt/tirex-content/")) {
			return this.readProductFile(scriptPath);
		}
		try {
			const result = await storage.openFile(scriptPath);
			return result.data;
		} catch (e) {
			throw new ScriptLoadError(convertUnknownToError(e), scriptPath);
		}
	}

	public readProductFile(productPath: string): Promise<string> {
		const productUrl = _.trimStart(productPath, "/");
		const fileName = path.basename(productPath);
		return http.get(productUrl)
			.catch((e) => {
				if (e instanceof HttpError) {
					if (404 === e.response) {
						throw new Error(`File "${fileName}" does not exist`);
					}
				}
				throw new Error(`Failed to load ${productPath}: ${e.message}`);
			});
	}

	public resolve(pathToResolve: string): string {
		return pathToResolve;
	}
}

export function createLoader(fs: Pick<FS, "cwd" | "readFile" | "fileExists" | "isFile">) {
	return isCloud() ? new CloudLoader() : new LocalLoader(fs);
}
