import { UnitsNumberConfigurable, Units, NumberAndUnits } from "public/defs";
import { SetSource } from "../member";
import { Validations } from "../validations";
import {
	NumStrFormatType,
	Radix,
	extendNumberFormats,
	logErrorIfIntegerAndNotSafe,
	errorIfNotInteger,
	stringToNum,
	numToString,
	isInRange,
} from "../../utils/numberUtils";
import { isDivisibleBy, isNumberAndUnitsNumber, numberConvertTo, toIdealUnit } from "../../utils/unitsUtils";
import { UnitsConfigurableMgr } from "./unitsConfigurableMgr";

export class UnitsNumberConfigurableMgr extends UnitsConfigurableMgr<number> {

	public override getScriptValue(): { value: any; shouldQuoteStrings: boolean; } {
		return {
			value: `{ val: ${this.numToString(this.value.val)}, units: "${this.value.units}" }`,
			shouldQuoteStrings: false,
		};
	}

	public override validate(validations: Validations): void {
		super.validate(validations);
		logErrorIfIntegerAndNotSafe(validations, this, this.value.val);
		if (this.def.step && !isDivisibleBy(this.value, this.def.step)) {
			validations.logError(`Value must be divisible by ${this.numToString(this.def.step.val)}${this.def.step.units}`, this);
		}
	}

	protected override convertToImpl(input: NumberAndUnits<number>, output: Units): number {
		return numberConvertTo(input, output);
	}

	protected override validateValue(value: NumberAndUnits<number>, forceWrite: boolean, source: SetSource): void {
		super.validateValue(value, forceWrite, source);

		errorIfNotInteger(this.isInteger(), value.val);
	}

	protected override defaultValueType(): string {
		return "NumberAndUnits<number>";
	}

	protected override valIsInstance(val: any): boolean {
		return isNumberAndUnitsNumber(val);
	}

	protected override createMatchFormats(unitsFormat: string): RegExp[] {
		const baseFormats = this.getRadix() === Radix.HEX ? ["hex", "posInt"] :
			this.isInteger() ? ["hex", "int"] : ["hex", "dec"];

		return extendNumberFormats(baseFormats as NumStrFormatType[], unitsFormat);
	}

	protected override stringToNum(val: string): number {
		return stringToNum(val);
	}

	protected override numToString(val: number): string {
		return numToString(val, this.def.displayFormat);
	}

	protected override isInRange(val: number, range: [low: number, high: number]): boolean {
		return isInRange(val, range);
	}

	protected override isEqual(val: NumberAndUnits<number>): boolean {
		return this.value.val === val.val && this.value.units === val.units;
	}

	protected override onSet(newVal: NumberAndUnits<number>, source: SetSource): void {
		if (!this.isInteger()) {
			super.onSet(newVal, source);
		}
	}

	protected override toIdealUnit(val: NumberAndUnits<number>, permittedUnitsRange: [low: number, high: number]) {
		return toIdealUnit(val, ...permittedUnitsRange);
	}

	private isInteger() {
		return (this.def as UnitsNumberConfigurable).isInteger;
	}
}
